const FILES = {
"app/components/shared/RichContent.tsx": "import \"@/app/styles/rich-content.css\";\n\n/** Renders HTML that was sanitised on save (see app/lib/sanitize.ts). */\nexport default function RichContent({\n  html,\n  className = \"\",\n}: {\n  html: string;\n  className?: string;\n}) {\n  if (!html) return null;\n  return (\n    <div\n      className={`rich-content ${className}`}\n      dangerouslySetInnerHTML={{ __html: html }}\n    />\n  );\n}\n",
"app/components/shared/VideoEmbed.tsx": "import { parseVideoUrl } from \"@/app/lib/video\";\n\n/** Responsive 16:9 YouTube/Vimeo player. Renders nothing for an invalid link. */\nexport default function VideoEmbed({\n  url,\n  title,\n  className = \"\",\n}: {\n  url: string | null | undefined;\n  title: string;\n  className?: string;\n}) {\n  const video = parseVideoUrl(url);\n  if (!video) return null;\n  return (\n    <div\n      className={`relative w-full overflow-hidden bg-black aspect-video rounded-lg ${className}`}\n    >\n      <iframe\n        src={video.embedUrl}\n        title={title}\n        className=\"absolute inset-0 w-full h-full border-0\"\n        loading=\"lazy\"\n        allow=\"accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\n        referrerPolicy=\"strict-origin-when-cross-origin\"\n        allowFullScreen\n      />\n    </div>\n  );\n}\n",
"app/components/shared/LegalPage.tsx": "import Topbar from \"@/app/components/layout/Topbar\";\nimport Navbar from \"@/app/components/layout/Navbar\";\nimport Footer from \"@/app/components/layout/Footer\";\nimport RichContent from \"@/app/components/shared/RichContent\";\nimport { getLegalContent, type LegalPageSlug } from \"@/app/lib/legalContent\";\n\n/** Public page for Terms / Privacy / Disclaimer, content managed in the admin panel. */\nexport default async function LegalPage({ slug }: { slug: LegalPageSlug }) {\n  const content = await getLegalContent(slug);\n  const sections = content.sections.filter((s) => !s.hidden);\n\n  return (\n    <>\n      <Topbar />\n      <Navbar />\n      <main className=\"min-h-screen bg-cream\">\n        <div className=\"max-w-[860px] mx-auto px-4 sm:px-8 lg:px-12 py-12 lg:py-16\">\n          <h1 className=\"mb-2 text-3xl font-bold font-display text-green\">{content.title}</h1>\n          <div className=\"w-12 h-[3px] bg-gold rounded mb-3\" />\n          {content.updatedAt && (\n            <p className=\"mb-8 text-xs text-ink-muted font-body\">\n              Last updated{\" \"}\n              {new Date(content.updatedAt).toLocaleDateString(\"en-GB\", {\n                day: \"numeric\",\n                month: \"long\",\n                year: \"numeric\",\n              })}\n            </p>\n          )}\n          {!content.updatedAt && <div className=\"mb-5\" />}\n\n          <div className=\"text-sm text-ink-mid font-body\">\n            <RichContent html={content.intro} className=\"mb-7\" />\n            <div className=\"space-y-7\">\n              {sections.map((s) => (\n                <section key={s.id}>\n                  {s.heading && (\n                    <h2 className=\"mb-2 text-base font-bold font-display text-green\">{s.heading}</h2>\n                  )}\n                  <RichContent html={s.html} />\n                </section>\n              ))}\n            </div>\n          </div>\n        </div>\n      </main>\n      <Footer />\n    </>\n  );\n}\n",
"app/components/admin/AdminNav.tsx": "\"use client\";\nimport Link from \"next/link\";\nimport { usePathname, useSearchParams } from \"next/navigation\";\nimport { signOut } from \"next-auth/react\";\nimport { useState, Suspense, useRef, useLayoutEffect } from \"react\";\n\nconst NAV_SCROLL_KEY = \"admin-nav-scroll\";\n\nconst NAV_GROUPS = [\n  {\n    label: \"Overview\",\n    items: [\n      { label: \"Dashboard\", href: \"/admin\" },\n      { label: \"Event Banners\", href: \"/admin/banners\" },\n      { label: \"Comments\", href: \"/admin/comments\" },\n      { label: \"Contact Queries\", href: \"/admin/contact\" },\n      { label: \"Registered Users\", href: \"/admin/users\" },\n    ],\n  },\n  {\n    label: \"Hall of Fame\",\n    items: [\n      { label: \"Manage Profiles\", href: \"/admin/profiles\" },\n      { label: \"Add Profile\", href: \"/admin/profiles/new\" },\n      { label: \"Profile Categories\", href: \"/admin/categories\" },\n    ],\n  },\n  {\n    label: \"Pakistani Businesses\",\n    items: [\n      { label: \"Manage Businesses\", href: \"/admin/business\" },\n      { label: \"Add Business\", href: \"/admin/business/new\" },\n      { label: \"Business Categories\", href: \"/admin/business-categories\" },\n    ],\n  },\n  {\n    label: \"Pakistani Products\",\n    items: [\n      { label: \"Manage Products\", href: \"/admin/products\" },\n      { label: \"Add Product\", href: \"/admin/products/new\" },\n      { label: \"Product Categories\", href: \"/admin/product-categories\" },\n    ],\n  },\n  {\n    label: \"Discussion Forum & Stories\",\n    items: [\n      { label: \"Discussion Forum\", href: \"/admin/news\" },\n      { label: \"Add to Discussion Forum\", href: \"/admin/news/new\" },\n      { label: \"Your Stories\", href: \"/admin/user-stories\" },\n    ],\n  },\n  {\n    label: \"Pride TV\",\n    items: [\n      { label: \"Manage Videos\", href: \"/admin/media\" },\n      { label: \"Video Categories\", href: \"/admin/video-categories\" },\n    ],\n  },\n  {\n    label: \"Team & Sponsors\",\n    items: [\n      { label: \"Pride Team\", href: \"/admin/team\" },\n      { label: \"Sponsors\", href: \"/admin/sponsors\" },\n    ],\n  },\n  {\n    label: \"Pages\",\n    items: [\n      { label: \"Homepage\", href: \"/admin/homepage\" },\n      { label: \"Who Is Who\", href: \"/admin/pages/whoiswho\" },\n      { label: \"Pakistani Products\", href: \"/admin/pages/products\" },\n      { label: \"Pakistani Businesses\", href: \"/admin/pages/businesses\" },\n      { label: \"Discussion Forum\", href: \"/admin/pages/news\" },\n      { label: \"Your Stories\", href: \"/admin/pages/stories\" },\n      { label: \"Contact\", href: \"/admin/pages/contact\" },\n      { label: \"Pride TV\", href: \"/admin/pages/pridetv\" },\n      { label: \"About Us\", href: \"/admin/pages/about\" },\n      { label: \"Our Mission\", href: \"/admin/pages/mission\" },\n      { label: \"Pride Team Page\", href: \"/admin/pages/team\" },\n      { label: \"Sponsors Page\", href: \"/admin/pages/sponsors\" },\n      { label: \"Terms & Conditions\", href: \"/admin/pages/legal/terms\" },\n      { label: \"Privacy Policy\", href: \"/admin/pages/legal/privacy\" },\n      { label: \"Disclaimer\", href: \"/admin/pages/legal/disclaimer\" },\n    ],\n  },\n];\n\nconst GROUP_ICONS: Record<string, JSX.Element> = {\n  Overview: (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <rect width=\"7\" height=\"9\" x=\"3\" y=\"3\" rx=\"1\" />\n      <rect width=\"7\" height=\"5\" x=\"14\" y=\"3\" rx=\"1\" />\n      <rect width=\"7\" height=\"9\" x=\"14\" y=\"12\" rx=\"1\" />\n      <rect width=\"7\" height=\"5\" x=\"3\" y=\"16\" rx=\"1\" />\n    </svg>\n  ),\n  \"Hall of Fame\": (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <circle cx=\"12\" cy=\"8\" r=\"4\" />\n      <path d=\"M20 21a8 8 0 0 0-16 0\" />\n    </svg>\n  ),\n  \"Pakistani Businesses\": (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\" />\n      <polyline points=\"9 22 9 12 15 12 15 22\" />\n    </svg>\n  ),\n  \"Pakistani Products\": (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <path d=\"M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z\" />\n      <line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\" />\n      <path d=\"M16 10a4 4 0 0 1-8 0\" />\n    </svg>\n  ),\n  \"Discussion Forum & Stories\": (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\" />\n      <path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\" />\n    </svg>\n  ),\n  \"Pride TV\": (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <polygon points=\"23 7 16 12 23 17 23 7\" />\n      <rect width=\"15\" height=\"14\" x=\"1\" y=\"5\" rx=\"2\" />\n    </svg>\n  ),\n  \"Team & Sponsors\": (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\" />\n      <circle cx=\"9\" cy=\"7\" r=\"4\" />\n      <path d=\"M22 21v-2a4 4 0 0 0-3-3.87\" />\n      <path d=\"M16 3.13a4 4 0 0 1 0 7.75\" />\n    </svg>\n  ),\n  Pages: (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n      <path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\" />\n      <polyline points=\"14 2 14 8 20 8\" />\n      <line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\" />\n      <line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\" />\n    </svg>\n  ),\n};\n\nfunction AdminNavInner() {\n  const pathname = usePathname();\n  const searchParams = useSearchParams();\n  const currentSearch = searchParams.toString();\n  const [open, setOpen] = useState(false);\n  const navRef = useRef<HTMLElement>(null);\n\n  // Restore scroll position BEFORE the browser paints, so there's no visible jump.\n  // If nothing is saved yet, bring the active link into view instead.\n  useLayoutEffect(() => {\n    const el = navRef.current;\n    if (!el) return;\n    let saved: string | null = null;\n    try {\n      saved = sessionStorage.getItem(NAV_SCROLL_KEY);\n    } catch {}\n    if (saved) {\n      el.scrollTop = parseInt(saved, 10) || 0;\n    } else {\n      el.querySelector<HTMLElement>(\"[data-active='true']\")?.scrollIntoView({ block: \"nearest\" });\n    }\n  }, []);\n\n  function handleScroll() {\n    if (!navRef.current) return;\n    try {\n      sessionStorage.setItem(NAV_SCROLL_KEY, String(navRef.current.scrollTop));\n    } catch {}\n  }\n\n  function isActive(href: string): boolean {\n    const [hrefPath, hrefQuery] = href.split(\"?\");\n    if (pathname !== hrefPath) return false;\n    if (!hrefQuery) return !currentSearch;\n    return currentSearch === hrefQuery;\n  }\n\n  // No sidebar on the login page. Must stay AFTER all hooks above.\n  if (pathname?.startsWith(\"/admin/login\")) return null;\n\n  return (\n    <>\n      {/* Mobile top bar */}\n      <div className=\"fixed top-0 left-0 right-0 z-50 flex items-center justify-between px-4 py-3 border-b lg:hidden bg-green border-white/10\">\n        <div className=\"flex items-center gap-2.5\">\n          <div className=\"flex items-center justify-center flex-shrink-0 w-6 h-6 rounded-md bg-gold\">\n            <span className=\"text-white font-bold text-[10px] font-display\">P</span>\n          </div>\n          <span className=\"text-sm font-bold text-white font-display\">Admin Panel</span>\n        </div>\n        <button\n          onClick={() => setOpen(!open)}\n          className=\"flex flex-col gap-1.5 p-1.5 rounded-md hover:bg-white/10 transition-colors\"\n          aria-label=\"Toggle menu\"\n        >\n          <span className={`block w-5 h-0.5 bg-white transition-transform ${open ? \"rotate-45 translate-y-2\" : \"\"}`} />\n          <span className={`block w-5 h-0.5 bg-white transition-opacity ${open ? \"opacity-0\" : \"\"}`} />\n          <span className={`block w-5 h-0.5 bg-white transition-transform ${open ? \"-rotate-45 -translate-y-2\" : \"\"}`} />\n        </button>\n      </div>\n\n      {/* Mobile backdrop */}\n      {open && (\n        <div\n          className=\"fixed inset-0 z-40 lg:hidden bg-black/50 backdrop-blur-sm\"\n          onClick={() => setOpen(false)}\n        />\n      )}\n\n      {/* Sidebar */}\n      <aside\n        className={`fixed top-0 left-0 h-full w-64 bg-green z-50 flex flex-col transition-transform duration-300 lg:translate-x-0 ${open ? \"translate-x-0\" : \"-translate-x-full lg:translate-x-0\"}`}\n      >\n        {/* Logo */}\n        <div className=\"flex-shrink-0 px-5 py-5 border-b border-white/10\">\n          <div className=\"flex items-center gap-3\">\n            <div className=\"flex items-center justify-center flex-shrink-0 w-8 h-8 rounded-lg bg-gold\">\n              <span className=\"text-sm font-bold text-white font-display\">P</span>\n            </div>\n            <div>\n              <p className=\"text-sm font-bold leading-tight text-white font-display\">Pride of Pakistan</p>\n              <p className=\"text-[10px] text-gold/80 font-body mt-0.5 uppercase tracking-widest\">Admin Panel</p>\n            </div>\n          </div>\n        </div>\n\n        {/* Nav groups — always expanded */}\n        <nav\n          ref={navRef}\n          onScroll={handleScroll}\n          className=\"flex-1 py-3 overflow-y-auto scrollbar-thin\"\n        >\n          {NAV_GROUPS.map((group) => {\n            const hasActive = group.items.some((i) => isActive(i.href));\n            return (\n              <div key={group.label} className=\"mb-1\">\n                <div className=\"flex items-center gap-2 px-4 py-2\">\n                  <span className={`flex-shrink-0 transition-colors ${hasActive ? \"text-gold\" : \"text-white/35\"}`}>\n                    {GROUP_ICONS[group.label]}\n                  </span>\n                  <span className={`text-[10px] font-bold uppercase tracking-[.14em] font-body ${hasActive ? \"text-gold\" : \"text-white/35\"}`}>\n                    {group.label}\n                  </span>\n                </div>\n\n                <div className=\"pb-1\">\n                  {group.items.map(({ label, href }) => {\n                    const active = isActive(href);\n                    return (\n                      <Link\n                        key={href}\n                        href={href}\n                        scroll={false}\n                        data-active={active}\n                        onClick={() => setOpen(false)}\n                        className={`flex items-center gap-2.5 px-4 py-2 mx-2 rounded-lg text-[13px] font-medium font-body transition-all no-underline ${\n                          active\n                            ? \"bg-white/15 text-white font-semibold\"\n                            : \"text-white/60 hover:bg-white/8 hover:text-white/90\"\n                        }`}\n                      >\n                        <span className={`w-1.5 h-1.5 rounded-full flex-shrink-0 transition-colors ${active ? \"bg-gold\" : \"bg-transparent\"}`} />\n                        {label}\n                      </Link>\n                    );\n                  })}\n                </div>\n              </div>\n            );\n          })}\n        </nav>\n\n        {/* Footer */}\n        <div className=\"flex-shrink-0 border-t border-white/10\">\n          <div className=\"px-3 py-3 space-y-0.5\">\n            <Link\n              href=\"/\"\n              className=\"flex items-center gap-2.5 px-3 py-2.5 rounded-lg text-sm font-body text-white/60 hover:bg-white/10 hover:text-white transition-colors no-underline\"\n            >\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n                <path d=\"m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\" />\n                <polyline points=\"9 22 9 12 15 12 15 22\" />\n              </svg>\n              View Site\n            </Link>\n            <Link\n              href=\"/admin/settings\"\n              scroll={false}\n              className={`flex items-center gap-2.5 px-3 py-2.5 rounded-lg text-sm font-body transition-colors no-underline ${\n                pathname === \"/admin/settings\"\n                  ? \"bg-white/15 text-white\"\n                  : \"text-white/60 hover:bg-white/10 hover:text-white\"\n              }`}\n            >\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n                <path d=\"M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z\" />\n                <circle cx=\"12\" cy=\"12\" r=\"3\" />\n              </svg>\n              Settings\n            </Link>\n            <button\n              onClick={() => {\n                try { sessionStorage.removeItem(NAV_SCROLL_KEY); } catch {}\n                signOut({ callbackUrl: \"/admin/login\" });\n              }}\n              className=\"w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg text-sm font-body text-white/60 hover:bg-red-500/20 hover:text-red-300 transition-colors text-left\"\n            >\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n                <path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\" />\n                <polyline points=\"16 17 21 12 16 7\" />\n                <line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\" />\n              </svg>\n              Sign Out\n            </button>\n          </div>\n        </div>\n      </aside>\n    </>\n  );\n}\n\nexport default function AdminNav() {\n  return (\n    <Suspense\n      fallback={\n        <aside className=\"fixed top-0 left-0 z-50 flex-col hidden w-64 h-full bg-green lg:flex\" />\n      }\n    >\n      <AdminNavInner />\n    </Suspense>\n  );\n}\n",
"app/components/admin/ImageUpload.tsx": "\"use client\";\nimport { useState } from \"react\";\n\n/** Uploads an image to /api/upload (Cloudinary) and returns its URL. */\nexport default function ImageUpload({\n  value,\n  onChange,\n  label = \"Image\",\n  hint,\n  shape = \"wide\",\n}: {\n  value: string | null;\n  onChange: (url: string) => void;\n  label?: string;\n  hint?: string;\n  shape?: \"wide\" | \"square\";\n}) {\n  const [uploading, setUploading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function handleFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0];\n    e.target.value = \"\";\n    if (!file) return;\n    if (!file.type.startsWith(\"image/\")) return setError(\"Please choose an image file.\");\n    if (file.size > 5 * 1024 * 1024) return setError(\"Image must be under 5 MB.\");\n    setUploading(true);\n    setError(null);\n    try {\n      const fd = new FormData();\n      fd.append(\"file\", file);\n      const res = await fetch(\"/api/upload\", { method: \"POST\", body: fd });\n      const json = await res.json().catch(() => ({}));\n      if (!res.ok) throw new Error(json.error ?? \"Upload failed.\");\n      onChange(json.url ?? json.path);\n    } catch (err) {\n      setError((err as Error).message);\n    } finally {\n      setUploading(false);\n    }\n  }\n\n  return (\n    <div>\n      <label className=\"block text-xs font-semibold text-ink-muted uppercase tracking-wide mb-1.5 font-body\">\n        {label}\n      </label>\n      <div className=\"flex items-center gap-4\">\n        <div\n          className={`flex-shrink-0 overflow-hidden border rounded-lg border-border bg-cream flex items-center justify-center ${\n            shape === \"square\" ? \"w-24 h-24\" : \"w-40 h-24\"\n          }`}\n        >\n          {value ? (\n            // eslint-disable-next-line @next/next/no-img-element\n            <img\n              src={value}\n              alt=\"\"\n              className={`w-full h-full ${shape === \"square\" ? \"object-cover object-top\" : \"object-contain p-2\"}`}\n            />\n          ) : (\n            <span className=\"text-[11px] text-ink-muted font-body\">No image</span>\n          )}\n        </div>\n        <div className=\"space-y-2\">\n          <label\n            className={`inline-block cursor-pointer bg-gold text-white px-4 py-2 rounded-md text-xs font-semibold font-body hover:bg-gold-light hover:text-ink-dark transition-colors ${\n              uploading ? \"opacity-50 pointer-events-none\" : \"\"\n            }`}\n          >\n            {uploading ? \"Uploading…\" : value ? \"Change image\" : \"Upload image\"}\n            <input type=\"file\" accept=\"image/*\" className=\"hidden\" onChange={handleFile} />\n          </label>\n          {value && (\n            <button\n              type=\"button\"\n              onClick={() => onChange(\"\")}\n              className=\"block text-xs text-red-500 font-body hover:underline\"\n            >\n              Remove\n            </button>\n          )}\n          {hint && <p className=\"text-[11px] text-ink-muted font-body\">{hint}</p>}\n          {error && <p className=\"text-xs text-red-500 font-body\">{error}</p>}\n        </div>\n      </div>\n    </div>\n  );\n}\n",
"app/components/admin/RichEditor.tsx": "\"use client\";\nimport { useEditor, EditorContent } from \"@tiptap/react\";\nimport StarterKit from \"@tiptap/starter-kit\";\nimport \"@/app/styles/rich-content.css\";\n\n/**\n * Reusable rich-text editor for admin forms.\n * Uncontrolled: pass the starting HTML once, receive updates via onChange.\n * To load different content, change the component's `key`.\n */\nexport default function RichEditor({\n  value,\n  onChange,\n  minHeight = 160,\n  placeholder,\n}: {\n  value: string;\n  onChange: (html: string) => void;\n  minHeight?: number;\n  placeholder?: string;\n}) {\n  const editor = useEditor({\n    extensions: [\n      StarterKit.configure({\n        heading: { levels: [2, 3] },\n        link: { openOnClick: false, autolink: true },\n      }),\n    ],\n    content: value || \"\",\n    immediatelyRender: false,\n    editorProps: {\n      attributes: {\n        class:\n          \"rich-content max-w-none focus:outline-none font-body text-ink-dark leading-relaxed p-4 text-sm\",\n        style: `min-height:${minHeight}px`,\n        ...(placeholder ? { \"data-placeholder\": placeholder } : {}),\n      },\n    },\n    onUpdate: ({ editor }) => {\n      const html = editor.getHTML();\n      onChange(html === \"<p></p>\" ? \"\" : html);\n    },\n  });\n\n  function run(action: () => void) {\n    return (e: React.MouseEvent) => {\n      e.preventDefault();\n      e.stopPropagation();\n      action();\n    };\n  }\n\n  function setLink() {\n    if (!editor) return;\n    const previous = editor.getAttributes(\"link\").href as string | undefined;\n    const url = window.prompt(\n      \"Link address (e.g. https://example.com or mailto:info@prideofpakistan.com). Leave empty to remove.\",\n      previous ?? \"https://\",\n    );\n    if (url === null) return;\n    if (url.trim() === \"\" || url.trim() === \"https://\") {\n      editor.chain().focus().extendMarkRange(\"link\").unsetLink().run();\n      return;\n    }\n    editor.chain().focus().extendMarkRange(\"link\").setLink({ href: url.trim() }).run();\n  }\n\n  const btn = (active: boolean) =>\n    `px-2.5 py-1 rounded text-xs font-body transition-colors ${\n      active ? \"bg-green text-white\" : \"text-ink-mid hover:bg-border\"\n    }`;\n  const divider = <div className=\"w-px h-4 mx-1 bg-border\" />;\n\n  return (\n    <div className=\"overflow-hidden bg-white border border-border rounded-xl\">\n      <div className=\"flex flex-wrap items-center gap-0.5 px-3 py-2 border-b border-border bg-cream\">\n        <button type=\"button\" title=\"Heading\" onClick={run(() => editor?.chain().focus().toggleHeading({ level: 2 }).run())} className={`${btn(!!editor?.isActive(\"heading\", { level: 2 }))} font-bold`}>H2</button>\n        <button type=\"button\" title=\"Sub-heading\" onClick={run(() => editor?.chain().focus().toggleHeading({ level: 3 }).run())} className={`${btn(!!editor?.isActive(\"heading\", { level: 3 }))} font-bold`}>H3</button>\n        {divider}\n        <button type=\"button\" title=\"Bold\" onClick={run(() => editor?.chain().focus().toggleBold().run())} className={`${btn(!!editor?.isActive(\"bold\"))} font-bold`}>B</button>\n        <button type=\"button\" title=\"Italic\" onClick={run(() => editor?.chain().focus().toggleItalic().run())} className={`${btn(!!editor?.isActive(\"italic\"))} italic`}>I</button>\n        <button type=\"button\" title=\"Underline\" onClick={run(() => editor?.chain().focus().toggleUnderline().run())} className={`${btn(!!editor?.isActive(\"underline\"))} underline`}>U</button>\n        {divider}\n        <button type=\"button\" title=\"Bullet list\" onClick={run(() => editor?.chain().focus().toggleBulletList().run())} className={btn(!!editor?.isActive(\"bulletList\"))}>• List</button>\n        <button type=\"button\" title=\"Numbered list\" onClick={run(() => editor?.chain().focus().toggleOrderedList().run())} className={btn(!!editor?.isActive(\"orderedList\"))}>1. List</button>\n        <button type=\"button\" title=\"Quote\" onClick={run(() => editor?.chain().focus().toggleBlockquote().run())} className={btn(!!editor?.isActive(\"blockquote\"))}>“ Quote</button>\n        {divider}\n        <button type=\"button\" title=\"Add or edit link\" onClick={run(setLink)} className={btn(!!editor?.isActive(\"link\"))}>Link</button>\n        {divider}\n        <button type=\"button\" title=\"Undo\" onClick={run(() => editor?.chain().focus().undo().run())} className={btn(false)}>↩</button>\n        <button type=\"button\" title=\"Redo\" onClick={run(() => editor?.chain().focus().redo().run())} className={btn(false)}>↪</button>\n      </div>\n      <EditorContent editor={editor} />\n    </div>\n  );\n}\n",
"app/components/home/SponsorsSection.tsx": "import Link from \"next/link\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { resolveImage } from \"@/app/lib/images\";\n\n/** Homepage strip of live sponsor logos. Renders nothing when there are none. */\nexport default async function SponsorsSection() {\n  const sponsors = await prisma.sponsor\n    .findMany({\n      where: { status: 1 },\n      orderBy: [{ sortOrder: \"asc\" }, { id: \"asc\" }],\n      take: 12,\n    })\n    .catch(() => []);\n\n  if (sponsors.length === 0) return null;\n\n  return (\n    <section className=\"py-14 bg-white border-t border-border sm:py-16\">\n      <div className=\"max-w-[1280px] mx-auto px-4 sm:px-8 lg:px-12\">\n        <div className=\"flex flex-wrap items-end justify-between gap-4 mb-8\">\n          <div>\n            <p className=\"text-[11px] font-bold tracking-[.16em] uppercase text-gold mb-2 font-body\">\n              Our Supporters\n            </p>\n            <h2 className=\"text-2xl font-bold font-display sm:text-3xl text-green\">Our Sponsors</h2>\n          </div>\n          <Link href=\"/our-sponsors\" className=\"text-sm font-semibold no-underline text-gold font-body hover:underline\">\n            View all sponsors →\n          </Link>\n        </div>\n\n        <div className=\"grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-6\">\n          {sponsors.map((s) => {\n            const logo = resolveImage(s.smallimage);\n            const inner = logo ? (\n              // eslint-disable-next-line @next/next/no-img-element\n              <img\n                src={logo}\n                alt={s.title}\n                className=\"object-contain w-full h-full transition duration-300 grayscale group-hover:grayscale-0\"\n              />\n            ) : (\n              <span className=\"text-sm font-bold text-center font-display text-green\">{s.title}</span>\n            );\n            const cls =\n              \"group flex items-center justify-center h-24 p-4 border rounded-xl border-border bg-cream/50 hover:border-gold hover:bg-white transition-colors no-underline\";\n            return s.website ? (\n              <a key={s.id} href={s.website} target=\"_blank\" rel=\"noopener noreferrer sponsored\" title={s.title} className={cls}>\n                {inner}\n              </a>\n            ) : (\n              <div key={s.id} title={s.title} className={cls}>\n                {inner}\n              </div>\n            );\n          })}\n        </div>\n      </div>\n    </section>\n  );\n}\n",
"app/api/admin/sponsors/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { sponsorData } from \"./validate\";\n\n// POST - create a sponsor (added at the end)\nexport async function POST(req: NextRequest) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const parsed = sponsorData(await req.json().catch(() => ({})));\n  if (\"error\" in parsed) return NextResponse.json(parsed, { status: 400 });\n\n  const last = await prisma.sponsor.findFirst({ orderBy: { sortOrder: \"desc\" } });\n  const sponsor = await prisma.sponsor.create({\n    data: { ...parsed.data, sortOrder: (last?.sortOrder ?? 0) + 1 },\n  });\n  return NextResponse.json({ id: sponsor.id });\n}\n\n// PUT { order: number[] } - save display order\nexport async function PUT(req: NextRequest) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const body = await req.json().catch(() => ({}));\n  const order: number[] = Array.isArray(body.order)\n    ? body.order.map(Number).filter((n: number) => Number.isInteger(n))\n    : [];\n  await prisma.$transaction(\n    order.map((id, i) => prisma.sponsor.update({ where: { id }, data: { sortOrder: i + 1 } })),\n  );\n  return NextResponse.json({ success: true });\n}\n",
"app/api/admin/sponsors/validate.ts": "import { plainText } from \"@/app/lib/sanitize\";\nimport { externalUrl } from \"@/app/lib/images\";\n\nexport function sponsorData(body: Record<string, unknown>) {\n  const title = plainText(body.title, 255);\n  if (!title) return { error: \"Sponsor name is required.\" } as const;\n  const website = externalUrl(plainText(body.website, 500)) ?? \"\";\n  if (website && !/^https?:\\/\\/[^\\s.]+\\.[^\\s]+$/i.test(website))\n    return { error: \"Website address doesn't look right.\" } as const;\n  return {\n    data: {\n      title,\n      shortdesc: plainText(body.shortdesc, 2000),\n      smallimage: plainText(body.smallimage, 255),\n      website,\n      status: body.status ? 1 : 0,\n    },\n  } as const;\n}\n",
"app/api/admin/sponsors/[id]/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { sponsorData } from \"../validate\";\n\n// PATCH - full update, or { status } alone to show/hide\nexport async function PATCH(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const { id } = await params;\n  const body = await req.json().catch(() => ({}));\n\n  if (Object.keys(body).length === 1 && \"status\" in body) {\n    await prisma.sponsor.update({\n      where: { id: Number(id) },\n      data: { status: body.status ? 1 : 0 },\n    });\n    return NextResponse.json({ success: true });\n  }\n\n  const parsed = sponsorData(body);\n  if (\"error\" in parsed) return NextResponse.json(parsed, { status: 400 });\n  await prisma.sponsor.update({ where: { id: Number(id) }, data: parsed.data });\n  return NextResponse.json({ success: true });\n}\n\nexport async function DELETE(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const { id } = await params;\n  await prisma.sponsor.delete({ where: { id: Number(id) } });\n  return NextResponse.json({ success: true });\n}\n",
"app/api/admin/users/[id]/password/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport bcrypt from \"bcryptjs\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\n\n// PATCH { password: string } - admin sets a new password for a registered (public) user\nexport async function PATCH(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n\n  const { id } = await params;\n  const body = await req.json().catch(() => ({}));\n  const password = typeof body.password === \"string\" ? body.password : \"\";\n\n  if (password.length < 8)\n    return NextResponse.json(\n      { error: \"Password must be at least 8 characters.\" },\n      { status: 400 },\n    );\n  if (password.length > 128)\n    return NextResponse.json({ error: \"Password is too long.\" }, { status: 400 });\n\n  const user = await prisma.publicUser.findUnique({\n    where: { id },\n    select: { id: true },\n  });\n  if (!user) return NextResponse.json({ error: \"User not found.\" }, { status: 404 });\n\n  const hash = await bcrypt.hash(password, 12);\n  await prisma.publicUser.update({ where: { id }, data: { password: hash } });\n\n  return NextResponse.json({ success: true });\n}\n",
"app/api/admin/videos/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { getServerSession } from \"next-auth\";\nimport { authOptions } from \"@/app/lib/auth\";\nimport { prisma } from \"@/app/lib/prisma\";\n\nasync function adminCheck() {\n  const session = await getServerSession(authOptions);\n  return (session?.user as { role?: string })?.role === \"ADMIN\";\n}\n\nasync function purgeHomepage() {\n  const baseUrl = process.env.NEXTAUTH_URL ?? \"http://localhost:3000\";\n  await fetch(\n    `${baseUrl}/api/revalidate?secret=${process.env.REVALIDATE_SECRET}`,\n    {\n      method: \"POST\",\n    },\n  ).catch(() => {});\n}\n\nexport async function GET() {\n  try {\n    const videos = await prisma.video.findMany({\n      orderBy: { datetime: \"desc\" },\n    });\n    return NextResponse.json(\n      videos.map((v) => ({\n        ...v,\n        video_id: Number(v.video_id),\n        views: Number(v.views),\n      })),\n    );\n  } catch (err) {\n    console.error(\"Videos GET error:\", err);\n    return NextResponse.json({ error: \"Server error\" }, { status: 500 });\n  }\n}\n\nexport async function POST(req: NextRequest) {\n  if (!(await adminCheck()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n\n  try {\n    const {\n      title,\n      description,\n      video_embed_code,\n      thumb_url,\n      category,\n      tags,\n      featured,\n    } = await req.json();\n\n    if (!title?.trim() || !video_embed_code?.trim()) {\n      return NextResponse.json(\n        { error: \"Title and URL are required.\" },\n        { status: 400 },\n      );\n    }\n\n    const video = await prisma.video.create({\n      data: {\n        title: title.trim(),\n        description: description?.trim() ?? \"\",\n        video_embed_code: video_embed_code.trim(),\n        thumb_url: thumb_url?.trim() ?? \"\",\n        category: Number.isInteger(Number(category)) ? Number(category) : 0,\n        tags: tags?.trim() ?? \"\",\n        featured: featured ? \"feature\" : \"no\",\n        status: \"active\",\n        views: BigInt(0),\n        ads_embed_code: \"\",\n        seo_title: title.trim(),\n        seo_keywords: tags?.trim() ?? \"\",\n        seo_description: description?.trim()?.slice(0, 255) ?? \"\",\n        server: \"youtube\",\n      },\n    });\n\n    await purgeHomepage();\n    return NextResponse.json({\n      success: true,\n      video_id: Number(video.video_id),\n    });\n  } catch (err) {\n    console.error(\"Video POST error:\", err);\n    return NextResponse.json({ error: \"Server error\" }, { status: 500 });\n  }\n}\n\nexport async function PATCH(req: NextRequest) {\n  if (!(await adminCheck()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n\n  try {\n    const {\n      video_id,\n      title,\n      description,\n      video_embed_code,\n      thumb_url,\n      status,\n      featured,\n      category,\n    } = await req.json();\n    if (!video_id)\n      return NextResponse.json({ error: \"Missing video_id\" }, { status: 400 });\n\n    await prisma.video.update({\n      where: { video_id: BigInt(video_id) },\n      data: {\n        ...(title !== undefined && { title }),\n        ...(description !== undefined && { description }),\n        ...(video_embed_code !== undefined && { video_embed_code }),\n        ...(thumb_url !== undefined && { thumb_url }),\n        ...(status !== undefined && { status }),\n        ...(featured !== undefined && {\n          featured: featured ? \"feature\" : \"no\",\n        }),\n        ...(category !== undefined &&\n          Number.isInteger(Number(category)) && { category: Number(category) }),\n      },\n    });\n\n    await purgeHomepage();\n    return NextResponse.json({ success: true });\n  } catch (err) {\n    console.error(\"Video PATCH error:\", err);\n    return NextResponse.json({ error: \"Server error\" }, { status: 500 });\n  }\n}\n\nexport async function DELETE(req: NextRequest) {\n  if (!(await adminCheck()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n\n  const { searchParams } = new URL(req.url);\n  const id = searchParams.get(\"id\");\n  if (!id) return NextResponse.json({ error: \"Missing id\" }, { status: 400 });\n\n  try {\n    await prisma.video.delete({ where: { video_id: BigInt(id) } });\n    await purgeHomepage();\n    return NextResponse.json({ success: true });\n  } catch (err) {\n    console.error(\"Video DELETE error:\", err);\n    return NextResponse.json({ error: \"Server error\" }, { status: 500 });\n  }\n}\n",
"app/api/admin/team/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { teamData } from \"./validate\";\n\nexport async function POST(req: NextRequest) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const parsed = teamData(await req.json().catch(() => ({})));\n  if (\"error\" in parsed) return NextResponse.json(parsed, { status: 400 });\n  const member = await prisma.prideTeam.create({ data: parsed.data });\n  return NextResponse.json({ id: member.id });\n}\n",
"app/api/admin/team/validate.ts": "import { plainText } from \"@/app/lib/sanitize\";\n\nexport function teamData(body: Record<string, unknown>) {\n  const fullname = plainText(body.fullname, 50);\n  if (!fullname) return { error: \"Name is required.\" } as const;\n  const email = plainText(body.email, 200);\n  if (email && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))\n    return { error: \"Email address doesn't look right.\" } as const;\n  return {\n    data: {\n      fullname,\n      designation: plainText(body.designation, 255),\n      city: plainText(body.city, 100),\n      country: plainText(body.country, 100),\n      phone: plainText(body.phone, 50),\n      email,\n      image: plainText(body.image, 200),\n      description: plainText(body.description, 5000),\n      status: body.status ? 1 : 0,\n    },\n  } as const;\n}\n",
"app/api/admin/team/[id]/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { teamData } from \"../validate\";\n\n// PATCH - full update, or { status } alone to show/hide\nexport async function PATCH(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const { id } = await params;\n  const body = await req.json().catch(() => ({}));\n\n  if (Object.keys(body).length === 1 && \"status\" in body) {\n    await prisma.prideTeam.update({\n      where: { id: Number(id) },\n      data: { status: body.status ? 1 : 0 },\n    });\n    return NextResponse.json({ success: true });\n  }\n\n  const parsed = teamData(body);\n  if (\"error\" in parsed) return NextResponse.json(parsed, { status: 400 });\n  await prisma.prideTeam.update({ where: { id: Number(id) }, data: parsed.data });\n  return NextResponse.json({ success: true });\n}\n\nexport async function DELETE(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const { id } = await params;\n  await prisma.prideTeam.delete({ where: { id: Number(id) } });\n  return NextResponse.json({ success: true });\n}\n",
"app/api/admin/business/[id]/video/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { revalidatePath } from \"next/cache\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { parseVideoUrl } from \"@/app/lib/video\";\n\n// PATCH { video_url: string }  - empty string removes the video\nexport async function PATCH(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n\n  const { id } = await params;\n  const bizId = Number(id);\n  if (!Number.isInteger(bizId) || bizId <= 0)\n    return NextResponse.json({ error: \"Invalid business.\" }, { status: 400 });\n\n  const body = await req.json().catch(() => ({}));\n  const raw = typeof body.video_url === \"string\" ? body.video_url.trim() : \"\";\n\n  let stored = \"\";\n  if (raw) {\n    const parsed = parseVideoUrl(raw);\n    if (!parsed)\n      return NextResponse.json(\n        { error: \"Please paste a YouTube or Vimeo link.\" },\n        { status: 400 },\n      );\n    stored = parsed.watchUrl;\n  }\n\n  try {\n    await prisma.business.update({\n      where: { id: bizId },\n      data: { video_url: stored },\n    });\n    revalidatePath(`/business/${bizId}`);\n    return NextResponse.json({ success: true, video_url: stored });\n  } catch (err) {\n    console.error(\"Business video update error:\", err);\n    return NextResponse.json({ error: \"Server error\" }, { status: 500 });\n  }\n}\n",
"app/api/admin/legal/[slug]/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { revalidatePath } from \"next/cache\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { plainText, sanitizeRichHtml } from \"@/app/lib/sanitize\";\nimport { LEGAL_PAGES, isLegalSlug, type LegalContent } from \"@/app/lib/legalContent\";\n\nexport async function PATCH(\n  req: NextRequest,\n  { params }: { params: Promise<{ slug: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n\n  const { slug } = await params;\n  if (!isLegalSlug(slug))\n    return NextResponse.json({ error: \"Unknown page.\" }, { status: 404 });\n\n  const body = await req.json().catch(() => ({}));\n  const title = plainText(body.title, 150);\n  if (!title) return NextResponse.json({ error: \"Page title is required.\" }, { status: 400 });\n\n  const sections = (Array.isArray(body.sections) ? body.sections : [])\n    .slice(0, 100)\n    .map((s: Record<string, unknown>, i: number) => ({\n      id: plainText(s.id, 40) || `s${Date.now()}${i}`,\n      heading: plainText(s.heading, 255),\n      html: sanitizeRichHtml(typeof s.html === \"string\" ? s.html : \"\"),\n      hidden: Boolean(s.hidden),\n    }))\n    .filter((s: { heading: string; html: string }) => s.heading || s.html);\n\n  const content: LegalContent = {\n    title,\n    intro: sanitizeRichHtml(typeof body.intro === \"string\" ? body.intro : \"\"),\n    sections,\n    updatedAt: new Date().toISOString(),\n  };\n\n  const key = LEGAL_PAGES[slug].key;\n  await prisma.pageContent.upsert({\n    where: { page: key },\n    update: { content: content as object },\n    create: { page: key, content: content as object },\n  });\n  revalidatePath(LEGAL_PAGES[slug].path);\n\n  return NextResponse.json({ success: true, content });\n}\n",
"app/api/admin/video-categories/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { plainText } from \"@/app/lib/sanitize\";\n\n// POST { name } - create a category (added at the end of the list)\nexport async function POST(req: NextRequest) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const body = await req.json().catch(() => ({}));\n  const name = plainText(body.name, 100);\n  if (!name) return NextResponse.json({ error: \"Name is required.\" }, { status: 400 });\n\n  const last = await prisma.videoCategory.findFirst({ orderBy: { sortOrder: \"desc\" } });\n  if (!last) {\n    // First category ever: existing videos carry a leftover default (1) from the\n    // old site. Mark them Uncategorised so they don't all land in this new category.\n    await prisma.video.updateMany({ data: { category: 0 } });\n  }\n  const cat = await prisma.videoCategory.create({\n    data: { name, status: 1, sortOrder: (last?.sortOrder ?? 0) + 1 },\n  });\n  return NextResponse.json({ id: cat.id, sortOrder: cat.sortOrder });\n}\n\n// PUT { order: number[] } - save a new display order\nexport async function PUT(req: NextRequest) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const body = await req.json().catch(() => ({}));\n  const order: number[] = Array.isArray(body.order)\n    ? body.order.map(Number).filter((n: number) => Number.isInteger(n))\n    : [];\n  await prisma.$transaction(\n    order.map((id, i) =>\n      prisma.videoCategory.update({ where: { id }, data: { sortOrder: i + 1 } }),\n    ),\n  );\n  return NextResponse.json({ success: true });\n}\n",
"app/api/admin/video-categories/[id]/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { plainText } from \"@/app/lib/sanitize\";\n\n// PATCH { name?, status? }\nexport async function PATCH(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const { id } = await params;\n  const body = await req.json().catch(() => ({}));\n  const name = body.name !== undefined ? plainText(body.name, 100) : undefined;\n  if (name === \"\") return NextResponse.json({ error: \"Name is required.\" }, { status: 400 });\n\n  await prisma.videoCategory.update({\n    where: { id: Number(id) },\n    data: {\n      ...(name !== undefined && { name }),\n      ...(body.status !== undefined && { status: body.status ? 1 : 0 }),\n    },\n  });\n  return NextResponse.json({ success: true });\n}\n\n// DELETE - videos in this category become \"Uncategorised\" (category 0); nothing is deleted\nexport async function DELETE(\n  req: NextRequest,\n  { params }: { params: Promise<{ id: string }> },\n) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n  const { id } = await params;\n  const catId = Number(id);\n  await prisma.$transaction([\n    prisma.video.updateMany({ where: { category: catId }, data: { category: 0 } }),\n    prisma.videoCategory.delete({ where: { id: catId } }),\n  ]);\n  return NextResponse.json({ success: true });\n}\n",
"app/api/admin/contact-info/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { revalidatePath } from \"next/cache\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { isAdmin } from \"@/app/lib/adminAuth\";\nimport { plainText } from \"@/app/lib/sanitize\";\nimport {\n  CONTACT_INFO_KEY,\n  type ContactInfo,\n  type ContactItemType,\n  type SocialPlatform,\n} from \"@/app/lib/contactInfo\";\n\nconst ITEM_TYPES: ContactItemType[] = [\"email\", \"phone\", \"url\", \"text\"];\nconst PLATFORMS: SocialPlatform[] = [\"facebook\", \"instagram\", \"youtube\", \"linkedin\", \"tiktok\", \"whatsapp\", \"other\"];\n\ntype Raw = Record<string, unknown>;\nconst arr = (v: unknown): Raw[] => (Array.isArray(v) ? v.filter((x) => x && typeof x === \"object\") : []);\nconst id = (v: unknown, i: number) => plainText(v, 40) || `i${Date.now()}${i}`;\n\nexport async function PATCH(req: NextRequest) {\n  if (!(await isAdmin()))\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 403 });\n\n  const b = (await req.json().catch(() => ({}))) as Raw;\n\n  const items = arr(b.items)\n    .map((it, i) => ({\n      id: id(it.id, i),\n      label: plainText(it.label, 100),\n      value: plainText(it.value, 255),\n      type: ITEM_TYPES.includes(it.type as ContactItemType) ? (it.type as ContactItemType) : \"text\",\n      hidden: Boolean(it.hidden),\n    }))\n    .filter((it) => it.value);\n\n  const socials = arr(b.socials)\n    .map((s, i) => {\n      const raw = plainText(s.url, 500);\n      const url = raw && !/^https?:\\/\\//i.test(raw) ? `https://${raw}` : raw;\n      return {\n        id: id(s.id, i),\n        platform: PLATFORMS.includes(s.platform as SocialPlatform) ? (s.platform as SocialPlatform) : \"other\",\n        label: plainText(s.label, 60),\n        url,\n        hidden: Boolean(s.hidden),\n      };\n    })\n    .filter((s) => s.url);\n\n  const formEmail = plainText(b.formEmail, 200);\n  if (formEmail && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(formEmail))\n    return NextResponse.json({ error: \"The form email address doesn't look right.\" }, { status: 400 });\n\n  const content: ContactInfo = {\n    introHeading: plainText(b.introHeading, 200),\n    introText: plainText(b.introText, 2000),\n    infoTitle: plainText(b.infoTitle, 100),\n    items,\n    responseTitle: plainText(b.responseTitle, 100),\n    responseText: plainText(b.responseText, 500),\n    socialTitle: plainText(b.socialTitle, 100),\n    socials,\n    formHeading: plainText(b.formHeading, 100),\n    formSubtext: plainText(b.formSubtext, 300),\n    formEmail,\n    successHeading: plainText(b.successHeading, 100),\n    successText: plainText(b.successText, 300),\n  };\n\n  await prisma.pageContent.upsert({\n    where: { page: CONTACT_INFO_KEY },\n    update: { content: content as object },\n    create: { page: CONTACT_INFO_KEY, content: content as object },\n  });\n  revalidatePath(\"/contact\");\n\n  return NextResponse.json({ success: true, content });\n}\n",
"app/api/upload/route.ts": "import { NextRequest, NextResponse } from 'next/server'\nimport { getServerSession } from 'next-auth'\nimport { v2 as cloudinary } from 'cloudinary'\nimport { authOptions } from '@/app/lib/auth'\n\ncloudinary.config({\n  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,\n  api_key:    process.env.CLOUDINARY_API_KEY,\n  api_secret: process.env.CLOUDINARY_API_SECRET,\n})\n\nconst MAX_BYTES = 8 * 1024 * 1024 // 8 MB\n\nexport async function POST(req: NextRequest) {\n  // Only signed-in users (admins or registered members) may upload\n  const session = await getServerSession(authOptions)\n  if (!session) return NextResponse.json({ error: 'Please sign in to upload.' }, { status: 401 })\n\n  try {\n    const formData = await req.formData()\n    const file = formData.get('file')\n    if (!(file instanceof File) || file.size === 0)\n      return NextResponse.json({ error: 'No file' }, { status: 400 })\n    if (!file.type.startsWith('image/'))\n      return NextResponse.json({ error: 'Only image files can be uploaded.' }, { status: 400 })\n    if (file.size > MAX_BYTES)\n      return NextResponse.json({ error: 'Image must be under 8 MB.' }, { status: 400 })\n\n    const buffer = Buffer.from(await file.arrayBuffer())\n\n    const result = await new Promise<{ secure_url: string; public_id: string }>(\n      (resolve, reject) => {\n        cloudinary.uploader.upload_stream(\n          { folder: 'prideofpakistan', resource_type: 'image' },\n          (error, result) => {\n            if (error || !result) reject(error)\n            else resolve(result)\n          }\n        ).end(buffer)\n      }\n    )\n\n    return NextResponse.json({\n      success: true,\n      url: result.secure_url,\n      path: result.secure_url, // full Cloudinary URL\n    })\n  } catch (err) {\n    console.error('Upload error:', err)\n    return NextResponse.json({ error: 'Upload failed' }, { status: 500 })\n  }\n}\n",
"app/api/revalidate/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { revalidatePath } from \"next/cache\";\n\nconst PATHS = [\n  \"/\",\n  \"/who-is-who\",\n  \"/products\",\n  \"/business\",\n  \"/news\",\n  \"/your-stories\",\n  \"/contact\",\n  \"/about\",\n  \"/mission\",\n  \"/pride-tv\",\n  \"/pride-team\",\n  \"/our-sponsors\",\n  \"/terms-of-use\",\n  \"/privacy-policy\",\n  \"/disclaimer\",\n];\n\nfunction doRevalidate() {\n  for (const path of PATHS) {\n    revalidatePath(path, \"page\");\n  }\n}\n\nexport async function GET(req: NextRequest) {\n  const secret = req.nextUrl.searchParams.get(\"secret\");\n  if (secret !== process.env.REVALIDATE_SECRET) {\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 401 });\n  }\n  doRevalidate();\n  return NextResponse.json({ revalidated: true, paths: PATHS });\n}\n\nexport async function POST(req: NextRequest) {\n  const secret = req.nextUrl.searchParams.get(\"secret\");\n  if (secret !== process.env.REVALIDATE_SECRET) {\n    return NextResponse.json({ error: \"Unauthorized\" }, { status: 401 });\n  }\n  doRevalidate();\n  return NextResponse.json({ revalidated: true, paths: PATHS });\n}\n",
"app/styles/rich-content.css": "/* Typography for HTML written in the admin rich-text editor.\n   Used both inside the editor and on the public pages. */\n.rich-content > * + * { margin-top: 0.85em; }\n.rich-content p { line-height: 1.75; }\n.rich-content h2 {\n  font-family: \"Playfair Display\", serif;\n  font-size: 1.3rem;\n  font-weight: 700;\n  color: #0D4A2E;\n  margin-top: 1.6em;\n  line-height: 1.3;\n}\n.rich-content h3 {\n  font-family: \"Playfair Display\", serif;\n  font-size: 1.1rem;\n  font-weight: 700;\n  color: #0D4A2E;\n  margin-top: 1.3em;\n}\n.rich-content ul { list-style: disc; padding-left: 1.4rem; }\n.rich-content ol { list-style: decimal; padding-left: 1.4rem; }\n.rich-content li + li { margin-top: 0.35em; }\n.rich-content li > p { margin: 0; }\n.rich-content a { color: #C9992A; text-decoration: underline; text-underline-offset: 2px; }\n.rich-content a:hover { color: #0D4A2E; }\n.rich-content strong, .rich-content b { color: #1A1208; font-weight: 600; }\n.rich-content blockquote {\n  border-left: 3px solid #C9992A;\n  padding-left: 1rem;\n  color: #7A6B50;\n  font-style: italic;\n}\n.rich-content hr { border: 0; border-top: 1px solid #DDD0B0; margin: 1.5em 0; }\n.rich-content > :first-child { margin-top: 0; }\n",
"app/lib/legalContent.ts": "import { cache } from \"react\";\nimport { prisma } from \"@/app/lib/prisma\";\n\nexport const LEGAL_PAGES = {\n  terms: { key: \"legal_terms\", path: \"/terms-of-use\", label: \"Terms & Conditions\" },\n  privacy: { key: \"legal_privacy\", path: \"/privacy-policy\", label: \"Privacy Policy\" },\n  disclaimer: { key: \"legal_disclaimer\", path: \"/disclaimer\", label: \"Disclaimer\" },\n} as const;\n\nexport type LegalPageSlug = keyof typeof LEGAL_PAGES;\n\nexport function isLegalSlug(v: string): v is LegalPageSlug {\n  return v in LEGAL_PAGES;\n}\n\nexport interface LegalSection {\n  id: string;\n  heading: string;\n  html: string;\n  hidden?: boolean;\n}\n\nexport interface LegalContent {\n  title: string;\n  intro: string; // rich HTML, optional\n  sections: LegalSection[];\n  updatedAt: string | null;\n}\n\nconst EMAIL =\n  '<a href=\"mailto:info@prideofpakistan.com\">info@prideofpakistan.com</a>';\n\n// Defaults = the text that was hard-coded on the site before, so nothing is lost.\nexport const LEGAL_DEFAULTS: Record<LegalPageSlug, LegalContent> = {\n  terms: {\n    title: \"Terms of Use\",\n    intro: \"\",\n    updatedAt: null,\n    sections: [\n      {\n        id: \"t1\",\n        heading: \"1. Agreement between you and Pride of Pakistan\",\n        html: \"<p>This is an Agreement between you and Pride of Pakistan website. Your use of the Pride of Pakistan website constitutes your acceptance of this Agreement and any information that you submit is correct.</p>\",\n      },\n      {\n        id: \"t2\",\n        heading: \"2. Pride of Pakistan may modify this Agreement\",\n        html: \"<p>Pride of Pakistan reserves the right to change the terms and conditions under which it offers the Pride of Pakistan website.</p>\",\n      },\n      {\n        id: \"t3\",\n        heading: \"3. No unlawful use of the Pride of Pakistan website\",\n        html: \"<p>You may not use the Pride of Pakistan website in any way that breaches any code of conduct or policy applicable to the Pride of Pakistan website. You may not use the Pride of Pakistan website in any manner that could damage, disable, overburden, or impair Pride of Pakistan web site or interfere with any other party's use of the Pride of Pakistan website.</p>\",\n      },\n      {\n        id: \"t4\",\n        heading: \"4. Materials you post or provide\",\n        html: \"<p>Any material you post or provide for Pride of Pakistan website, you grant permission to use, copy, edit, modify, translate and reformat your submission. Pride of Pakistan will not pay you for your submission and may remove your submission at any time.</p>\",\n      },\n      {\n        id: \"t5\",\n        heading: \"5. Copyright and trademark notices\",\n        html: \"<p>All contents of the Pride of Pakistan website are Copyright. The names of actual companies and products mentioned herein may be the trademarks of their respective owners.</p>\",\n      },\n      {\n        id: \"t6\",\n        heading: \"6. Other Acknowledgements\",\n        html: \"<p>Pride of Pakistan may change or delete features in any way, at any time and for any reason. Pride of Pakistan will not guarantee that it will be error free and will not be liable for any omissions, inaccuracies, deletion, negligence, computer virus, delay or interruption in the transmission to the users or under any other cause of action.</p>\",\n      },\n    ],\n  },\n  privacy: {\n    title: \"Privacy Policy\",\n    intro:\n      \"<p>Pride of Pakistan is committed to protecting your privacy and has developed this policy because we want you to feel confident about the privacy of your personal details.</p>\",\n    updatedAt: null,\n    sections: [\n      {\n        id: \"p1\",\n        heading: \"Who this policy applies to\",\n        html: \"<p>Pride of Pakistan is a general audience web site, intended for users of all ages and this Privacy Policy applies to data collection and usage on Pride of Pakistan web site.</p>\",\n      },\n      {\n        id: \"p2\",\n        heading: \"What we display\",\n        html: \"<p>General information gathered from your given data is displayed on the Pride of Pakistan web site, but personal information, such as your date of birth, home or business address, telephone number and e-mail address will not be displayed, shared or disclosed to any other party unless we have your permission to do so.</p>\",\n      },\n      {\n        id: \"p3\",\n        heading: \"Sharing your information\",\n        html: \"<p>Pride of Pakistan does not sell, rent or lease its profile list to third parties, however Pride of Pakistan may, from time to time, contact you about a particular offering that may be of interest to you.</p>\",\n      },\n      {\n        id: \"p4\",\n        heading: \"Where your data is stored\",\n        html: \"<p>Personal information collected on this site may be stored and processed in Pakistan or any other country for hosting purposes only and you consent to any such transfer of information, and retention of data.</p>\",\n      },\n      {\n        id: \"p5\",\n        heading: \"Changes to this policy\",\n        html: \"<p>Pride of Pakistan will occasionally update this Privacy Policy with the passage of time and will not be obligatory to inform you about the updating in the policy.</p>\",\n      },\n      {\n        id: \"p6\",\n        heading: \"Contact\",\n        html: `<p>Pride of Pakistan welcomes your comments regarding this Privacy Policy. If you believe that Pride of Pakistan has not adhered to this policy, please contact Pride of Pakistan by ${EMAIL}</p>`,\n      },\n    ],\n  },\n  disclaimer: {\n    title: \"Disclaimer\",\n    intro: \"\",\n    updatedAt: null,\n    sections: [\n      {\n        id: \"d1\",\n        heading: \"\",\n        html: \"<p>Pride of Pakistan website is for information and social entertainment purposes only. Content posted on this site may contain errors or inaccuracies, as it is based on gossip, news, rumours and personal opinions.</p>\",\n      },\n      {\n        id: \"d2\",\n        heading: \"\",\n        html: \"<p>We do not endorse the quality of any services, products, information or materials displayed, purchased, or obtained by you as a result of an advertisement or any other information on the Pride of Pakistan website. The Pride of Pakistan website reserves the right, without any obligation whatsoever to make improvements, to remove any listing / material or correct any error or omissions in any part of the website.</p>\",\n      },\n      {\n        id: \"d3\",\n        heading: \"\",\n        html: `<p>All images, videos, news and articles that appear on this website are copyright to their respective owners. If you own the rights to any of the images, videos, news, articles or any other material and do not wish them to appear on this site, please do not hesitate to contact ${EMAIL} for immediate removal.</p>`,\n      },\n      {\n        id: \"d4\",\n        heading: \"\",\n        html: \"<p>Pride of Pakistan website may contain links to other websites and the owner assumes no responsibility for the content of such websites. The owner of Pride of Pakistan website is not responsible for the accuracy, copyright compliance, legality or decency of material posted in any section of this site.</p>\",\n      },\n    ],\n  },\n};\n\nexport const getLegalContent = cache(async function getLegalContent(\n  slug: LegalPageSlug,\n): Promise<LegalContent> {\n  const fallback = LEGAL_DEFAULTS[slug];\n  try {\n    const row = await prisma.pageContent.findUnique({\n      where: { page: LEGAL_PAGES[slug].key },\n    });\n    if (!row) return fallback;\n    const c = row.content as Partial<LegalContent>;\n    return {\n      title: c.title || fallback.title,\n      intro: c.intro ?? \"\",\n      sections: Array.isArray(c.sections) ? c.sections : fallback.sections,\n      updatedAt: c.updatedAt ?? row.updatedAt.toISOString(),\n    };\n  } catch {\n    return fallback;\n  }\n});\n",
"app/lib/video.ts": "// Shared helpers for YouTube / Vimeo links.\n// Accepts a watch URL, share link, Shorts link, embed URL, a bare YouTube ID,\n// or a full <iframe> embed code, and normalises it.\n\nexport interface ParsedVideo {\n  provider: \"youtube\" | \"vimeo\";\n  id: string;\n  /** Privacy-friendly embed URL, safe to put in an <iframe src> */\n  embedUrl: string;\n  /** Canonical URL to store in the database */\n  watchUrl: string;\n  thumbnail: string | null;\n}\n\nconst YT_ID = /^[a-zA-Z0-9_-]{11}$/;\n\nexport function parseVideoUrl(raw: string | null | undefined): ParsedVideo | null {\n  if (!raw) return null;\n  let input = raw.trim();\n  if (!input) return null;\n\n  // Pasted <iframe ... src=\"...\"> embed code\n  const src = input.match(/src=[\"']([^\"']+)[\"']/i);\n  if (src?.[1]) input = src[1];\n\n  if (YT_ID.test(input)) return youtube(input);\n\n  let url: URL;\n  try {\n    url = new URL(input.startsWith(\"http\") ? input : `https://${input}`);\n  } catch {\n    return null;\n  }\n\n  const host = url.hostname.replace(/^(www\\.|m\\.|music\\.)/, \"\");\n\n  if (host === \"youtu.be\") {\n    const id = url.pathname.split(\"/\")[1];\n    return id && YT_ID.test(id) ? youtube(id) : null;\n  }\n\n  if (host === \"youtube.com\" || host === \"youtube-nocookie.com\") {\n    const v = url.searchParams.get(\"v\");\n    if (v && YT_ID.test(v)) return youtube(v);\n    const m = url.pathname.match(/^\\/(?:embed|shorts|live|v)\\/([a-zA-Z0-9_-]{11})/);\n    return m ? youtube(m[1]) : null;\n  }\n\n  if (host === \"vimeo.com\" || host === \"player.vimeo.com\") {\n    const m = url.pathname.match(/(?:^|\\/)(\\d{6,12})(?:\\/|$)/);\n    if (!m) return null;\n    return {\n      provider: \"vimeo\",\n      id: m[1],\n      embedUrl: `https://player.vimeo.com/video/${m[1]}?dnt=1`,\n      watchUrl: `https://vimeo.com/${m[1]}`,\n      thumbnail: null,\n    };\n  }\n\n  return null;\n}\n\nfunction youtube(id: string): ParsedVideo {\n  return {\n    provider: \"youtube\",\n    id,\n    embedUrl: `https://www.youtube-nocookie.com/embed/${id}?rel=0&modestbranding=1`,\n    watchUrl: `https://www.youtube.com/watch?v=${id}`,\n    thumbnail: `https://img.youtube.com/vi/${id}/hqdefault.jpg`,\n  };\n}\n",
"app/lib/contactInfo.ts": "import { prisma } from \"@/app/lib/prisma\";\n\nexport const CONTACT_INFO_KEY = \"contact_info\";\n\nexport type ContactItemType = \"email\" | \"phone\" | \"url\" | \"text\";\nexport type SocialPlatform =\n  | \"facebook\"\n  | \"instagram\"\n  | \"youtube\"\n  | \"linkedin\"\n  | \"tiktok\"\n  | \"whatsapp\"\n  | \"other\";\n\nexport interface ContactItem {\n  id: string;\n  label: string;\n  value: string;\n  type: ContactItemType;\n  hidden?: boolean;\n}\n\nexport interface SocialLink {\n  id: string;\n  platform: SocialPlatform;\n  label: string;\n  url: string;\n  hidden?: boolean;\n}\n\nexport interface ContactInfo {\n  introHeading: string;\n  introText: string;\n  infoTitle: string;\n  items: ContactItem[];\n  responseTitle: string;\n  responseText: string;\n  socialTitle: string;\n  socials: SocialLink[];\n  formHeading: string;\n  formSubtext: string;\n  formEmail: string;\n  successHeading: string;\n  successText: string;\n}\n\nexport const CONTACT_DEFAULTS: ContactInfo = {\n  introHeading: \"We'd Love to Hear From You\",\n  introText:\n    \"Pride of Pakistan is a growing movement. We welcome individuals, businesses, organisations, and communities who want to be part of redefining how the world sees Pakistan.\",\n  infoTitle: \"Contact Information\",\n  items: [\n    { id: \"c1\", label: \"General Enquiries\", value: \"info@prideofpakistan.com\", type: \"email\" },\n    { id: \"c2\", label: \"Marketing & Sponsorships\", value: \"marketing@prideofpakistan.com\", type: \"email\" },\n    { id: \"c3\", label: \"Website\", value: \"www.prideofpakistan.com\", type: \"url\" },\n  ],\n  responseTitle: \"Response Time\",\n  responseText: \"We aim to respond to all enquiries as soon as possible\",\n  socialTitle: \"Follow Us\",\n  socials: [\n    { id: \"s1\", platform: \"facebook\", label: \"Facebook\", url: \"https://www.facebook.com/prideofpakistan\" },\n  ],\n  formHeading: \"Send a Message\",\n  formSubtext: \"We aim to respond within 2 working days.\",\n  formEmail: \"info@prideofpakistan.com\",\n  successHeading: \"Message Sent!\",\n  successText: \"Thank you for reaching out. We'll be in touch shortly.\",\n};\n\nexport async function getContactInfo(): Promise<ContactInfo> {\n  try {\n    const row = await prisma.pageContent.findUnique({\n      where: { page: CONTACT_INFO_KEY },\n    });\n    if (!row) return CONTACT_DEFAULTS;\n    return { ...CONTACT_DEFAULTS, ...(row.content as Partial<ContactInfo>) };\n  } catch {\n    return CONTACT_DEFAULTS;\n  }\n}\n",
"app/lib/adminAuth.ts": "import { getServerSession } from \"next-auth\";\nimport { authOptions } from \"@/app/lib/auth\";\n\n/** True when the current request belongs to a signed-in admin. */\nexport async function isAdmin(): Promise<boolean> {\n  const session = await getServerSession(authOptions);\n  return (session?.user as { role?: string } | undefined)?.role === \"ADMIN\";\n}\n",
"app/lib/images.ts": "/** Turns stored image values (Cloudinary URL, /path, or legacy filename) into a usable src. */\nexport function resolveImage(img: string | null | undefined): string | null {\n  if (!img || img.trim() === \"\") return null;\n  if (img.startsWith(\"http\")) return img;\n  if (img.startsWith(\"/\")) return img;\n  if (img.startsWith(\"uploads/\")) return `/${img}`;\n  return `/uploads/${img}`;\n}\n\n/** Adds https:// to bare domains so external links work. */\nexport function externalUrl(url: string | null | undefined): string | null {\n  if (!url || !url.trim()) return null;\n  const u = url.trim();\n  return /^https?:\\/\\//i.test(u) ? u : `https://${u}`;\n}\n",
"app/lib/sanitize.ts": "import sanitizeHtml from \"sanitize-html\";\n\n/**\n * Cleans HTML coming from the admin rich-text editor before it is stored.\n * Only formatting tags survive; scripts, styles, event handlers and\n * javascript: links are stripped.\n */\nexport function sanitizeRichHtml(html: string): string {\n  return sanitizeHtml(html ?? \"\", {\n    allowedTags: [\n      \"p\", \"br\", \"h2\", \"h3\", \"h4\", \"strong\", \"b\", \"em\", \"i\", \"u\", \"s\",\n      \"ul\", \"ol\", \"li\", \"blockquote\", \"a\", \"hr\",\n    ],\n    allowedAttributes: { a: [\"href\", \"target\", \"rel\"] },\n    allowedSchemes: [\"http\", \"https\", \"mailto\", \"tel\"],\n    transformTags: {\n      a: (tagName, attribs) => {\n        const href = attribs.href ?? \"\";\n        const out: Record<string, string> = { href };\n        if (/^https?:\\/\\//i.test(href)) {\n          out.target = \"_blank\";\n          out.rel = \"noopener noreferrer\";\n        }\n        return { tagName, attribs: out };\n      },\n    },\n  }).trim();\n}\n\n/** Normalises a plain-text field (React escapes it when rendering). */\nexport function plainText(value: unknown, max = 2000): string {\n  if (typeof value !== \"string\") return \"\";\n  return value.trim().slice(0, max);\n}\n",
"app/(admin)/admin/sponsors/SponsorsClient.tsx": "\"use client\";\nimport { useState } from \"react\";\nimport ImageUpload from \"@/app/components/admin/ImageUpload\";\n\ninterface Sponsor {\n  id: number;\n  title: string;\n  shortdesc: string;\n  smallimage: string;\n  website: string;\n  status: number;\n}\n\nconst EMPTY: Omit<Sponsor, \"id\"> = {\n  title: \"\",\n  shortdesc: \"\",\n  smallimage: \"\",\n  website: \"\",\n  status: 1,\n};\n\nconst input =\n  \"w-full px-3 py-2.5 text-sm border border-border rounded-md font-body focus:outline-none focus:border-gold transition-colors\";\nconst labelCls =\n  \"block text-xs font-semibold text-ink-muted uppercase tracking-wide mb-1.5 font-body\";\n\nexport default function SponsorsClient({ sponsors: initial }: { sponsors: Sponsor[] }) {\n  const [sponsors, setSponsors] = useState(initial);\n  const [form, setForm] = useState(EMPTY);\n  const [editingId, setEditingId] = useState<number | null>(null);\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [notice, setNotice] = useState<string | null>(null);\n\n  function reset() {\n    setForm(EMPTY);\n    setEditingId(null);\n    setError(null);\n  }\n\n  function edit(s: Sponsor) {\n    setForm({ title: s.title, shortdesc: s.shortdesc, smallimage: s.smallimage, website: s.website, status: s.status });\n    setEditingId(s.id);\n    setError(null);\n    setNotice(null);\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\n  }\n\n  async function save() {\n    if (!form.title.trim()) return setError(\"Sponsor name is required.\");\n    setSaving(true);\n    setError(null);\n    try {\n      const res = await fetch(\n        editingId ? `/api/admin/sponsors/${editingId}` : \"/api/admin/sponsors\",\n        {\n          method: editingId ? \"PATCH\" : \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify(form),\n        },\n      );\n      const json = await res.json().catch(() => ({}));\n      if (!res.ok) return setError(json.error ?? \"Failed to save.\");\n      const website =\n        form.website && !/^https?:\\/\\//i.test(form.website) ? `https://${form.website}` : form.website;\n      if (editingId) {\n        setSponsors((prev) => prev.map((s) => (s.id === editingId ? { ...s, ...form, website } : s)));\n        setNotice(\"Sponsor updated.\");\n      } else {\n        setSponsors((prev) => [...prev, { id: json.id, ...form, website }]);\n        setNotice(\"Sponsor added.\");\n      }\n      reset();\n    } catch {\n      setError(\"Something went wrong.\");\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  async function toggle(s: Sponsor) {\n    const status = s.status === 1 ? 0 : 1;\n    setSponsors((prev) => prev.map((x) => (x.id === s.id ? { ...x, status } : x)));\n    await fetch(`/api/admin/sponsors/${s.id}`, {\n      method: \"PATCH\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ status }),\n    });\n  }\n\n  async function move(i: number, dir: -1 | 1) {\n    const j = i + dir;\n    if (j < 0 || j >= sponsors.length) return;\n    const next = [...sponsors];\n    [next[i], next[j]] = [next[j], next[i]];\n    setSponsors(next);\n    await fetch(\"/api/admin/sponsors\", {\n      method: \"PUT\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ order: next.map((s) => s.id) }),\n    });\n  }\n\n  async function remove(s: Sponsor) {\n    if (!confirm(`Delete sponsor \"${s.title}\"? This cannot be undone.`)) return;\n    const res = await fetch(`/api/admin/sponsors/${s.id}`, { method: \"DELETE\" });\n    if (res.ok) {\n      setSponsors((prev) => prev.filter((x) => x.id !== s.id));\n      if (editingId === s.id) reset();\n    }\n  }\n\n  return (\n    <div className=\"space-y-8\">\n      <div className=\"p-6 space-y-5 bg-white border border-border rounded-xl\">\n        <h2 className=\"text-lg font-bold font-display text-green\">\n          {editingId ? \"Edit Sponsor\" : \"Add a Sponsor\"}\n        </h2>\n\n        <div>\n          <label className={labelCls}>\n            Sponsor name <span className=\"text-gold\">*</span>\n          </label>\n          <input className={input} value={form.title} onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))} placeholder=\"e.g. Habib Bank Limited\" />\n        </div>\n\n        <ImageUpload\n          label=\"Logo\"\n          value={form.smallimage || null}\n          onChange={(url) => setForm((f) => ({ ...f, smallimage: url }))}\n          hint=\"A PNG with a transparent background looks best.\"\n        />\n\n        <div>\n          <label className={labelCls}>Website</label>\n          <input className={input} value={form.website} onChange={(e) => setForm((f) => ({ ...f, website: e.target.value }))} placeholder=\"https://www.example.com\" />\n          <p className=\"text-[11px] text-ink-muted font-body mt-1\">Visitors go here when they click the logo.</p>\n        </div>\n\n        <div>\n          <label className={labelCls}>Short description</label>\n          <textarea rows={3} className={`${input} resize-none`} value={form.shortdesc} onChange={(e) => setForm((f) => ({ ...f, shortdesc: e.target.value }))} placeholder=\"One or two lines about the sponsor…\" />\n        </div>\n\n        <label className=\"flex items-center gap-3 cursor-pointer select-none w-fit\">\n          <input type=\"checkbox\" checked={form.status === 1} onChange={(e) => setForm((f) => ({ ...f, status: e.target.checked ? 1 : 0 }))} className=\"w-4 h-4 accent-[#C9992A]\" />\n          <span className=\"text-sm text-ink-dark font-body\">Show on the website</span>\n        </label>\n\n        {error && <p className=\"text-sm text-red-500 font-body\">{error}</p>}\n\n        <div className=\"flex gap-3\">\n          <button onClick={save} disabled={saving} className=\"bg-gold text-white px-6 py-2.5 rounded-md text-sm font-semibold font-body hover:bg-gold-light hover:text-ink-dark transition-colors disabled:opacity-50\">\n            {saving ? \"Saving…\" : editingId ? \"Update Sponsor\" : \"Add Sponsor\"}\n          </button>\n          {editingId && (\n            <button onClick={reset} className=\"border border-border text-ink-mid px-6 py-2.5 rounded-md text-sm font-semibold font-body hover:border-green hover:text-green transition-colors\">\n              Cancel\n            </button>\n          )}\n        </div>\n      </div>\n\n      <div>\n        <div className=\"flex items-center justify-between mb-4\">\n          <h2 className=\"text-lg font-bold font-display text-green\">\n            All Sponsors <span className=\"text-base font-normal text-ink-muted\">({sponsors.length})</span>\n          </h2>\n          {notice && <p className=\"text-sm text-green font-body\">{notice}</p>}\n        </div>\n\n        {sponsors.length === 0 ? (\n          <div className=\"py-16 text-center bg-white border border-border rounded-xl\">\n            <p className=\"text-sm text-ink-muted font-body\">No sponsors yet. Add the first one above.</p>\n          </div>\n        ) : (\n          <div className=\"space-y-3\">\n            {sponsors.map((s, i) => (\n              <div key={s.id} className={`flex items-center gap-4 p-4 bg-white border border-border rounded-xl ${s.status === 1 ? \"\" : \"opacity-60\"}`}>\n                <div className=\"flex flex-col\">\n                  <button onClick={() => move(i, -1)} disabled={i === 0} className=\"text-[10px] leading-none text-ink-muted hover:text-green disabled:opacity-25\" aria-label=\"Move up\">▲</button>\n                  <button onClick={() => move(i, 1)} disabled={i === sponsors.length - 1} className=\"text-[10px] leading-none text-ink-muted hover:text-green disabled:opacity-25\" aria-label=\"Move down\">▼</button>\n                </div>\n                <div className=\"flex items-center justify-center flex-shrink-0 w-24 h-16 overflow-hidden border rounded-lg border-border bg-cream\">\n                  {s.smallimage ? (\n                    // eslint-disable-next-line @next/next/no-img-element\n                    <img src={s.smallimage} alt={s.title} className=\"object-contain w-full h-full p-1.5\" />\n                  ) : (\n                    <span className=\"text-lg font-bold font-display text-green\">{s.title.charAt(0)}</span>\n                  )}\n                </div>\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-semibold truncate text-ink-dark font-body\">{s.title}</p>\n                  {s.website ? (\n                    <a href={s.website} target=\"_blank\" rel=\"noopener noreferrer\" className=\"block text-xs no-underline truncate text-gold hover:underline font-body\">\n                      {s.website.replace(/^https?:\\/\\/(www\\.)?/, \"\")}\n                    </a>\n                  ) : (\n                    <p className=\"text-xs text-ink-muted font-body\">No website</p>\n                  )}\n                </div>\n                <div className=\"flex flex-wrap items-center justify-end flex-shrink-0 gap-3\">\n                  <button onClick={() => toggle(s)} className={`text-[11px] font-bold px-2.5 py-1 rounded-md border font-body ${s.status === 1 ? \"bg-green/10 text-green border-green/20\" : \"bg-amber-50 text-amber-700 border-amber-200\"}`}>\n                    {s.status === 1 ? \"● Live\" : \"● Hidden\"}\n                  </button>\n                  <button onClick={() => edit(s)} className=\"text-xs font-semibold text-gold font-body hover:underline\">Edit</button>\n                  <button onClick={() => remove(s)} className=\"text-xs text-red-500 font-body hover:underline\">Delete</button>\n                </div>\n              </div>\n            ))}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/sponsors/page.tsx": "import { prisma } from \"@/app/lib/prisma\";\nimport { resolveImage } from \"@/app/lib/images\";\nimport SponsorsClient from \"./SponsorsClient\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function AdminSponsorsPage() {\n  const sponsors = await prisma.sponsor.findMany({\n    orderBy: [{ sortOrder: \"asc\" }, { id: \"asc\" }],\n  });\n\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <div className=\"max-w-[900px]\">\n        <h1 className=\"mb-1 text-2xl font-bold font-display text-green\">Sponsors</h1>\n        <p className=\"mb-8 text-sm text-ink-muted font-body\">\n          Live sponsors appear on the homepage and the{\" \"}\n          <a href=\"/our-sponsors\" target=\"_blank\" className=\"text-gold hover:underline\">\n            Our Sponsors\n          </a>{\" \"}\n          page, in the order shown here.\n        </p>\n        <SponsorsClient\n          sponsors={sponsors.map((s) => ({\n            id: s.id,\n            title: s.title,\n            shortdesc: s.shortdesc,\n            smallimage: resolveImage(s.smallimage) ?? \"\",\n            website: s.website,\n            status: s.status,\n          }))}\n        />\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/users/page.tsx": "import Link from \"next/link\";\nimport type { Prisma } from \"@prisma/client\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport UsersTableClient from \"./UsersTableClient\";\n\nexport const dynamic = \"force-dynamic\";\n\nconst PAGE_SIZE = 25;\n\nexport default async function AdminUsersPage({\n  searchParams,\n}: {\n  searchParams: Promise<{ q?: string; page?: string }>;\n}) {\n  const { q = \"\", page = \"1\" } = await searchParams;\n  const query = q.trim();\n  const current = Math.max(1, Number(page) || 1);\n\n  const where: Prisma.PublicUserWhereInput = query\n    ? {\n        OR: [\n          { name: { contains: query, mode: \"insensitive\" } },\n          { email: { contains: query, mode: \"insensitive\" } },\n        ],\n      }\n    : {};\n\n  const [users, total, allTotal] = await Promise.all([\n    prisma.publicUser.findMany({\n      where,\n      orderBy: { createdAt: \"desc\" },\n      skip: (current - 1) * PAGE_SIZE,\n      take: PAGE_SIZE,\n      select: { id: true, name: true, email: true, emailVerified: true, createdAt: true },\n    }),\n    prisma.publicUser.count({ where }),\n    query ? prisma.publicUser.count() : Promise.resolve(0),\n  ]);\n\n  const pages = Math.max(1, Math.ceil(total / PAGE_SIZE));\n  const href = (p: number) =>\n    `/admin/users?${new URLSearchParams({ ...(query && { q: query }), page: String(p) })}`;\n\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <div className=\"max-w-[1100px]\">\n        <h1 className=\"mb-1 text-2xl font-bold font-display text-green\">Registered Users</h1>\n        <p className=\"mb-6 text-sm text-ink-muted font-body\">\n          {query\n            ? `${total} of ${allTotal} accounts match “${query}”`\n            : `${total} registered account${total === 1 ? \"\" : \"s\"}`}\n          . You can set a new password for anyone who is locked out.\n        </p>\n\n        <form method=\"get\" className=\"flex gap-3 p-4 mb-5 bg-white border border-border rounded-xl\">\n          <input\n            type=\"search\"\n            name=\"q\"\n            defaultValue={query}\n            placeholder=\"Search by name or email…\"\n            className=\"flex-1 px-3 py-2.5 text-sm border border-border rounded-md font-body focus:outline-none focus:border-gold\"\n          />\n          <button\n            type=\"submit\"\n            className=\"px-5 py-2.5 text-sm font-semibold text-white rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark\"\n          >\n            Search\n          </button>\n          {query && (\n            <Link\n              href=\"/admin/users\"\n              className=\"self-center text-sm no-underline text-ink-muted font-body hover:text-green\"\n            >\n              Clear\n            </Link>\n          )}\n        </form>\n\n        <UsersTableClient\n          users={users.map((u) => ({ ...u, createdAt: u.createdAt.toISOString() }))}\n          offset={(current - 1) * PAGE_SIZE}\n        />\n\n        {pages > 1 && (\n          <div className=\"flex items-center justify-between mt-5 text-sm font-body\">\n            <span className=\"text-ink-muted\">\n              Page {current} of {pages}\n            </span>\n            <div className=\"flex gap-2\">\n              {current > 1 && (\n                <Link href={href(current - 1)} className=\"px-4 py-2 no-underline bg-white border rounded-md border-border text-ink-mid hover:border-gold hover:text-gold\">\n                  ← Previous\n                </Link>\n              )}\n              {current < pages && (\n                <Link href={href(current + 1)} className=\"px-4 py-2 no-underline bg-white border rounded-md border-border text-ink-mid hover:border-gold hover:text-gold\">\n                  Next →\n                </Link>\n              )}\n            </div>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/users/UsersTableClient.tsx": "\"use client\";\nimport { useState } from \"react\";\n\ninterface User {\n  id: string;\n  name: string;\n  email: string;\n  emailVerified: boolean;\n  createdAt: string;\n}\n\nfunction generatePassword(length = 12): string {\n  // No look-alike characters (0/O, 1/l/I) so it is easy to read out to someone\n  const chars = \"ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789\";\n  const bytes = new Uint32Array(length);\n  crypto.getRandomValues(bytes);\n  return Array.from(bytes, (b) => chars[b % chars.length]).join(\"\");\n}\n\nfunction PasswordPanel({ user, onClose }: { user: User; onClose: () => void }) {\n  const [password, setPassword] = useState(\"\");\n  const [confirm, setConfirm] = useState(\"\");\n  const [show, setShow] = useState(false);\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [done, setDone] = useState<string | null>(null);\n  const [copied, setCopied] = useState(false);\n\n  async function handleSave() {\n    setError(null);\n    if (password.length < 8) return setError(\"Password must be at least 8 characters.\");\n    if (password !== confirm) return setError(\"The two passwords don't match.\");\n    setSaving(true);\n    try {\n      const res = await fetch(`/api/admin/users/${user.id}/password`, {\n        method: \"PATCH\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ password }),\n      });\n      const json = await res.json().catch(() => ({}));\n      if (!res.ok) return setError(json.error ?? \"Failed to update password.\");\n      setDone(password);\n    } catch {\n      setError(\"Something went wrong.\");\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  if (done) {\n    return (\n      <div className=\"p-4 space-y-3 border rounded-lg bg-green/5 border-green/20\">\n        <p className=\"text-sm font-semibold text-green font-body\">\n          Password updated for {user.name}.\n        </p>\n        <p className=\"text-xs text-ink-muted font-body\">\n          Share the new password with them privately (e.g. WhatsApp or phone), and ask them to keep it safe.\n        </p>\n        <div className=\"flex flex-wrap items-center gap-2\">\n          <code className=\"px-3 py-1.5 text-sm bg-white border rounded border-border\">{done}</code>\n          <button\n            type=\"button\"\n            onClick={async () => {\n              await navigator.clipboard.writeText(done).catch(() => {});\n              setCopied(true);\n            }}\n            className=\"text-xs font-semibold text-gold font-body hover:underline\"\n          >\n            {copied ? \"Copied\" : \"Copy\"}\n          </button>\n          <button type=\"button\" onClick={onClose} className=\"ml-auto text-xs text-ink-muted font-body hover:text-green\">\n            Close\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"p-4 space-y-3 border rounded-lg bg-cream border-border\">\n      <p className=\"text-sm font-semibold text-ink-dark font-body\">\n        Set a new password for {user.name}\n      </p>\n      <div className=\"grid grid-cols-1 gap-3 sm:grid-cols-2\">\n        <input\n          type={show ? \"text\" : \"password\"}\n          value={password}\n          onChange={(e) => setPassword(e.target.value)}\n          placeholder=\"New password (min 8 characters)\"\n          autoComplete=\"new-password\"\n          className=\"px-3 py-2 text-sm bg-white border rounded-md border-border font-body focus:outline-none focus:border-gold\"\n        />\n        <input\n          type={show ? \"text\" : \"password\"}\n          value={confirm}\n          onChange={(e) => setConfirm(e.target.value)}\n          placeholder=\"Type it again\"\n          autoComplete=\"new-password\"\n          className=\"px-3 py-2 text-sm bg-white border rounded-md border-border font-body focus:outline-none focus:border-gold\"\n        />\n      </div>\n      <div className=\"flex flex-wrap items-center gap-4 text-xs font-body\">\n        <button\n          type=\"button\"\n          onClick={() => {\n            const p = generatePassword();\n            setPassword(p);\n            setConfirm(p);\n            setShow(true);\n          }}\n          className=\"font-semibold text-gold hover:underline\"\n        >\n          Generate a password\n        </button>\n        <label className=\"flex items-center gap-1.5 cursor-pointer text-ink-muted\">\n          <input type=\"checkbox\" checked={show} onChange={(e) => setShow(e.target.checked)} />\n          Show\n        </label>\n      </div>\n      {error && <p className=\"text-xs text-red-500 font-body\">{error}</p>}\n      <div className=\"flex gap-3\">\n        <button\n          type=\"button\"\n          onClick={handleSave}\n          disabled={saving}\n          className=\"px-5 py-2 text-sm font-semibold text-white rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark disabled:opacity-50\"\n        >\n          {saving ? \"Saving…\" : \"Update Password\"}\n        </button>\n        <button\n          type=\"button\"\n          onClick={onClose}\n          className=\"px-5 py-2 text-sm font-semibold border rounded-md border-border text-ink-mid font-body hover:border-green hover:text-green\"\n        >\n          Cancel\n        </button>\n      </div>\n    </div>\n  );\n}\n\nexport default function UsersTableClient({ users, offset }: { users: User[]; offset: number }) {\n  const [openId, setOpenId] = useState<string | null>(null);\n\n  if (users.length === 0) {\n    return (\n      <div className=\"py-16 text-center bg-white border border-border rounded-xl\">\n        <p className=\"text-sm text-ink-muted font-body\">No accounts found.</p>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"overflow-hidden bg-white border border-border rounded-xl\">\n      <div className=\"hidden md:grid grid-cols-[40px_1.2fr_1.5fr_110px_110px_130px] gap-4 px-5 py-3 border-b border-border bg-cream text-[11px] font-bold uppercase tracking-wide text-ink-muted font-body\">\n        <span>#</span>\n        <span>Name</span>\n        <span>Email</span>\n        <span>Verified</span>\n        <span>Joined</span>\n        <span className=\"text-right\">Actions</span>\n      </div>\n      <div className=\"divide-y divide-border\">\n        {users.map((u, i) => (\n          <div key={u.id} className=\"px-5 py-3\">\n            <div className=\"grid grid-cols-1 md:grid-cols-[40px_1.2fr_1.5fr_110px_110px_130px] gap-1 md:gap-4 md:items-center\">\n              <span className=\"hidden text-xs md:block text-ink-muted font-body\">{offset + i + 1}</span>\n              <span className=\"text-sm font-semibold truncate text-ink-dark font-body\">{u.name}</span>\n              <a href={`mailto:${u.email}`} className=\"text-sm no-underline truncate text-ink-mid font-body hover:text-gold\">\n                {u.email}\n              </a>\n              <span>\n                <span\n                  className={`text-[11px] font-bold px-2 py-0.5 rounded border font-body ${\n                    u.emailVerified\n                      ? \"bg-green/10 text-green border-green/20\"\n                      : \"bg-gray-50 text-gray-500 border-gray-200\"\n                  }`}\n                >\n                  {u.emailVerified ? \"Verified\" : \"Not verified\"}\n                </span>\n              </span>\n              <span className=\"text-xs text-ink-muted font-body\">\n                {new Date(u.createdAt).toLocaleDateString(\"en-GB\", {\n                  day: \"numeric\",\n                  month: \"short\",\n                  year: \"numeric\",\n                })}\n              </span>\n              <span className=\"md:text-right\">\n                <button\n                  type=\"button\"\n                  onClick={() => setOpenId(openId === u.id ? null : u.id)}\n                  className=\"text-xs font-semibold text-gold font-body hover:underline\"\n                >\n                  {openId === u.id ? \"Close\" : \"Set password\"}\n                </button>\n              </span>\n            </div>\n            {openId === u.id && (\n              <div className=\"mt-3\">\n                <PasswordPanel user={u} onClose={() => setOpenId(null)} />\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/team/page.tsx": "import { prisma } from \"@/app/lib/prisma\";\nimport { resolveImage } from \"@/app/lib/images\";\nimport TeamClient from \"./TeamClient\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function AdminTeamPage() {\n  const members = await prisma.prideTeam.findMany({ orderBy: { fullname: \"asc\" } });\n\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <div className=\"max-w-[900px]\">\n        <h1 className=\"mb-1 text-2xl font-bold font-display text-green\">Pride Team</h1>\n        <p className=\"mb-8 text-sm text-ink-muted font-body\">\n          Live members appear on the{\" \"}\n          <a href=\"/pride-team\" target=\"_blank\" className=\"text-gold hover:underline\">\n            Pride Team\n          </a>{\" \"}\n          page in alphabetical order. Phone and email are for your records only and are never shown publicly.\n        </p>\n        <TeamClient\n          members={members.map((m) => ({\n            id: m.id,\n            fullname: m.fullname,\n            designation: m.designation,\n            city: m.city,\n            country: m.country,\n            phone: m.phone,\n            email: m.email,\n            image: resolveImage(m.image) ?? \"\",\n            description: m.description,\n            status: m.status,\n          }))}\n        />\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/team/TeamClient.tsx": "\"use client\";\nimport { useMemo, useState } from \"react\";\nimport ImageUpload from \"@/app/components/admin/ImageUpload\";\n\ninterface Member {\n  id: number;\n  fullname: string;\n  designation: string;\n  city: string;\n  country: string;\n  phone: string;\n  email: string;\n  image: string;\n  description: string;\n  status: number;\n}\n\nconst EMPTY: Omit<Member, \"id\"> = {\n  fullname: \"\",\n  designation: \"\",\n  city: \"\",\n  country: \"Pakistan\",\n  phone: \"\",\n  email: \"\",\n  image: \"\",\n  description: \"\",\n  status: 1,\n};\n\nconst input =\n  \"w-full px-3 py-2.5 text-sm border border-border rounded-md font-body focus:outline-none focus:border-gold transition-colors\";\nconst labelCls =\n  \"block text-xs font-semibold text-ink-muted uppercase tracking-wide mb-1.5 font-body\";\n\nconst byName = (a: Member, b: Member) => a.fullname.localeCompare(b.fullname);\n\nexport default function TeamClient({ members: initial }: { members: Member[] }) {\n  const [members, setMembers] = useState(initial);\n  const [form, setForm] = useState(EMPTY);\n  const [editingId, setEditingId] = useState<number | null>(null);\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [notice, setNotice] = useState<string | null>(null);\n  const [search, setSearch] = useState(\"\");\n\n  const shown = useMemo(() => {\n    const q = search.trim().toLowerCase();\n    if (!q) return members;\n    return members.filter((m) =>\n      [m.fullname, m.designation, m.city, m.country].some((v) => v.toLowerCase().includes(q)),\n    );\n  }, [members, search]);\n\n  const set = (key: keyof typeof EMPTY) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>\n    setForm((f) => ({ ...f, [key]: e.target.value }));\n\n  function reset() {\n    setForm(EMPTY);\n    setEditingId(null);\n    setError(null);\n  }\n\n  function edit(m: Member) {\n    const { id: _id, ...rest } = m;\n    void _id;\n    setForm(rest);\n    setEditingId(m.id);\n    setError(null);\n    setNotice(null);\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\n  }\n\n  async function save() {\n    if (!form.fullname.trim()) return setError(\"Name is required.\");\n    setSaving(true);\n    setError(null);\n    try {\n      const res = await fetch(editingId ? `/api/admin/team/${editingId}` : \"/api/admin/team\", {\n        method: editingId ? \"PATCH\" : \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(form),\n      });\n      const json = await res.json().catch(() => ({}));\n      if (!res.ok) return setError(json.error ?? \"Failed to save.\");\n      if (editingId) {\n        setMembers((prev) => prev.map((m) => (m.id === editingId ? { ...m, ...form } : m)).sort(byName));\n        setNotice(`${form.fullname} updated.`);\n      } else {\n        setMembers((prev) => [...prev, { id: json.id, ...form }].sort(byName));\n        setNotice(`${form.fullname} added.`);\n      }\n      reset();\n    } catch {\n      setError(\"Something went wrong.\");\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  async function toggle(m: Member) {\n    const status = m.status === 1 ? 0 : 1;\n    setMembers((prev) => prev.map((x) => (x.id === m.id ? { ...x, status } : x)));\n    await fetch(`/api/admin/team/${m.id}`, {\n      method: \"PATCH\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ status }),\n    });\n  }\n\n  async function remove(m: Member) {\n    if (!confirm(`Remove ${m.fullname} from the Pride Team? This cannot be undone.`)) return;\n    const res = await fetch(`/api/admin/team/${m.id}`, { method: \"DELETE\" });\n    if (res.ok) {\n      setMembers((prev) => prev.filter((x) => x.id !== m.id));\n      if (editingId === m.id) reset();\n    }\n  }\n\n  return (\n    <div className=\"space-y-8\">\n      <div className=\"p-6 space-y-5 bg-white border border-border rounded-xl\">\n        <h2 className=\"text-lg font-bold font-display text-green\">\n          {editingId ? \"Edit Team Member\" : \"Add a Team Member\"}\n        </h2>\n\n        <ImageUpload\n          label=\"Photo\"\n          shape=\"square\"\n          value={form.image || null}\n          onChange={(url) => setForm((f) => ({ ...f, image: url }))}\n          hint=\"A square, head-and-shoulders photo works best.\"\n        />\n\n        <div className=\"grid grid-cols-1 gap-4 sm:grid-cols-2\">\n          <div>\n            <label className={labelCls}>Full name <span className=\"text-gold\">*</span></label>\n            <input className={input} value={form.fullname} onChange={set(\"fullname\")} maxLength={50} />\n          </div>\n          <div>\n            <label className={labelCls}>Designation</label>\n            <input className={input} value={form.designation} onChange={set(\"designation\")} placeholder=\"e.g. Regional Coordinator\" />\n          </div>\n          <div>\n            <label className={labelCls}>City</label>\n            <input className={input} value={form.city} onChange={set(\"city\")} />\n          </div>\n          <div>\n            <label className={labelCls}>Country</label>\n            <input className={input} value={form.country} onChange={set(\"country\")} />\n          </div>\n          <div>\n            <label className={labelCls}>Phone <span className=\"font-normal normal-case\">(private)</span></label>\n            <input className={input} value={form.phone} onChange={set(\"phone\")} />\n          </div>\n          <div>\n            <label className={labelCls}>Email <span className=\"font-normal normal-case\">(private)</span></label>\n            <input className={input} type=\"email\" value={form.email} onChange={set(\"email\")} />\n          </div>\n        </div>\n\n        <div>\n          <label className={labelCls}>Short description</label>\n          <textarea rows={4} className={`${input} resize-none`} value={form.description} onChange={set(\"description\")} placeholder=\"A few lines about this person and their role…\" />\n        </div>\n\n        <label className=\"flex items-center gap-3 cursor-pointer select-none w-fit\">\n          <input type=\"checkbox\" checked={form.status === 1} onChange={(e) => setForm((f) => ({ ...f, status: e.target.checked ? 1 : 0 }))} className=\"w-4 h-4 accent-[#C9992A]\" />\n          <span className=\"text-sm text-ink-dark font-body\">Show on the website</span>\n        </label>\n\n        {error && <p className=\"text-sm text-red-500 font-body\">{error}</p>}\n\n        <div className=\"flex gap-3\">\n          <button onClick={save} disabled={saving} className=\"bg-gold text-white px-6 py-2.5 rounded-md text-sm font-semibold font-body hover:bg-gold-light hover:text-ink-dark transition-colors disabled:opacity-50\">\n            {saving ? \"Saving…\" : editingId ? \"Update Member\" : \"Add Member\"}\n          </button>\n          {editingId && (\n            <button onClick={reset} className=\"border border-border text-ink-mid px-6 py-2.5 rounded-md text-sm font-semibold font-body hover:border-green hover:text-green transition-colors\">\n              Cancel\n            </button>\n          )}\n        </div>\n      </div>\n\n      <div>\n        <div className=\"flex flex-wrap items-center justify-between gap-3 mb-4\">\n          <h2 className=\"text-lg font-bold font-display text-green\">\n            Team Members <span className=\"text-base font-normal text-ink-muted\">({shown.length})</span>\n          </h2>\n          <input\n            type=\"search\"\n            value={search}\n            onChange={(e) => setSearch(e.target.value)}\n            placeholder=\"Search members…\"\n            className=\"px-3 py-2 text-sm bg-white border rounded-md border-border font-body focus:outline-none focus:border-gold\"\n          />\n        </div>\n        {notice && <p className=\"mb-3 text-sm text-green font-body\">{notice}</p>}\n\n        {shown.length === 0 ? (\n          <div className=\"py-16 text-center bg-white border border-border rounded-xl\">\n            <p className=\"text-sm text-ink-muted font-body\">\n              {members.length === 0 ? \"No team members yet. Add the first one above.\" : \"No members match your search.\"}\n            </p>\n          </div>\n        ) : (\n          <div className=\"space-y-3\">\n            {shown.map((m) => (\n              <div key={m.id} className={`flex items-center gap-4 p-4 bg-white border border-border rounded-xl ${m.status === 1 ? \"\" : \"opacity-60\"}`}>\n                <div className=\"flex items-center justify-center flex-shrink-0 overflow-hidden rounded-full w-14 h-14 bg-green\">\n                  {m.image ? (\n                    // eslint-disable-next-line @next/next/no-img-element\n                    <img src={m.image} alt={m.fullname} className=\"object-cover object-top w-full h-full\" />\n                  ) : (\n                    <span className=\"text-lg font-bold text-white font-display\">{m.fullname.charAt(0)}</span>\n                  )}\n                </div>\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-semibold truncate text-ink-dark font-body\">{m.fullname}</p>\n                  <p className=\"text-xs truncate text-ink-muted font-body\">\n                    {[m.designation, [m.city, m.country].filter(Boolean).join(\", \")].filter(Boolean).join(\" · \")}\n                  </p>\n                </div>\n                <div className=\"flex flex-wrap items-center justify-end flex-shrink-0 gap-3\">\n                  <button onClick={() => toggle(m)} className={`text-[11px] font-bold px-2.5 py-1 rounded-md border font-body ${m.status === 1 ? \"bg-green/10 text-green border-green/20\" : \"bg-amber-50 text-amber-700 border-amber-200\"}`}>\n                    {m.status === 1 ? \"● Live\" : \"● Hidden\"}\n                  </button>\n                  <button onClick={() => edit(m)} className=\"text-xs font-semibold text-gold font-body hover:underline\">Edit</button>\n                  <button onClick={() => remove(m)} className=\"text-xs text-red-500 font-body hover:underline\">Delete</button>\n                </div>\n              </div>\n            ))}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/business/[id]/edit/BusinessVideoField.tsx": "\"use client\";\nimport { useState } from \"react\";\nimport { parseVideoUrl } from \"@/app/lib/video\";\n\nexport default function BusinessVideoField({\n  businessId,\n  initial,\n}: {\n  businessId: number;\n  initial: string;\n}) {\n  const [saved, setSaved] = useState(initial);\n  const [value, setValue] = useState(initial);\n  const [saving, setSaving] = useState(false);\n  const [message, setMessage] = useState<{ ok: boolean; text: string } | null>(null);\n\n  const parsed = parseVideoUrl(value);\n  const dirty = value.trim() !== saved;\n  const invalid = value.trim() !== \"\" && !parsed;\n\n  async function save(next: string) {\n    setSaving(true);\n    setMessage(null);\n    try {\n      const res = await fetch(`/api/admin/business/${businessId}/video`, {\n        method: \"PATCH\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ video_url: next }),\n      });\n      const json = await res.json().catch(() => ({}));\n      if (!res.ok) {\n        setMessage({ ok: false, text: json.error ?? \"Failed to save.\" });\n        return;\n      }\n      setSaved(json.video_url ?? \"\");\n      setValue(json.video_url ?? \"\");\n      setMessage({ ok: true, text: next ? \"Video saved. It now shows on the business page.\" : \"Video removed.\" });\n    } catch {\n      setMessage({ ok: false, text: \"Something went wrong.\" });\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  if (!businessId) {\n    return (\n      <div className=\"max-w-[900px] mt-6 p-6 bg-white border border-border rounded-xl\">\n        <h2 className=\"text-base font-bold font-display text-green\">Business Video</h2>\n        <p className=\"mt-1 text-sm text-ink-muted font-body\">\n          Save the business first, then you can add a video here.\n        </p>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"max-w-[900px] mt-6 p-6 space-y-4 bg-white border border-border rounded-xl\">\n      <div>\n        <h2 className=\"text-base font-bold font-display text-green\">Business Video</h2>\n        <p className=\"mt-1 text-sm text-ink-muted font-body\">\n          Paste a YouTube or Vimeo link. It plays on this business&apos;s public page.\n        </p>\n      </div>\n\n      <input\n        type=\"text\"\n        value={value}\n        onChange={(e) => {\n          setValue(e.target.value);\n          setMessage(null);\n        }}\n        placeholder=\"https://www.youtube.com/watch?v=...\"\n        className={`w-full px-3 py-2.5 text-sm border rounded-md font-body focus:outline-none transition-colors ${\n          invalid ? \"border-red-300 focus:border-red-400\" : \"border-border focus:border-gold\"\n        }`}\n      />\n      {invalid && (\n        <p className=\"text-xs text-red-500 font-body\">\n          That doesn&apos;t look like a YouTube or Vimeo link.\n        </p>\n      )}\n\n      {parsed && (\n        <div className=\"relative w-full max-w-[480px] overflow-hidden bg-black aspect-video rounded-lg\">\n          <iframe\n            src={parsed.embedUrl}\n            title=\"Video preview\"\n            className=\"absolute inset-0 w-full h-full border-0\"\n            allow=\"encrypted-media; picture-in-picture\"\n            allowFullScreen\n          />\n        </div>\n      )}\n\n      {message && (\n        <p className={`text-sm font-body ${message.ok ? \"text-green\" : \"text-red-500\"}`}>\n          {message.text}\n        </p>\n      )}\n\n      <div className=\"flex flex-wrap gap-3\">\n        <button\n          type=\"button\"\n          onClick={() => save(value.trim())}\n          disabled={saving || !dirty || invalid}\n          className=\"bg-gold text-white px-5 py-2.5 rounded-md text-sm font-semibold font-body hover:bg-gold-light hover:text-ink-dark transition-colors disabled:opacity-50\"\n        >\n          {saving ? \"Saving…\" : \"Save Video\"}\n        </button>\n        {saved && (\n          <button\n            type=\"button\"\n            onClick={() => {\n              if (confirm(\"Remove the video from this business?\")) save(\"\");\n            }}\n            disabled={saving}\n            className=\"px-5 py-2.5 rounded-md text-sm font-semibold font-body border border-red-200 text-red-600 hover:bg-red-50 transition-colors disabled:opacity-50\"\n          >\n            Remove Video\n          </button>\n        )}\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/video-categories/VideoCategoriesClient.tsx": "\"use client\";\nimport { useState } from \"react\";\nimport Link from \"next/link\";\n\ninterface Category {\n  id: number;\n  name: string;\n  status: number;\n  count: number;\n}\n\nexport default function VideoCategoriesClient({\n  categories: initial,\n  uncategorised,\n}: {\n  categories: Category[];\n  uncategorised: number;\n}) {\n  const [categories, setCategories] = useState(initial);\n  const [newName, setNewName] = useState(\"\");\n  const [editingId, setEditingId] = useState<number | null>(null);\n  const [editName, setEditName] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function call(url: string, method: string, body?: unknown) {\n    const res = await fetch(url, {\n      method,\n      headers: body ? { \"Content-Type\": \"application/json\" } : undefined,\n      body: body ? JSON.stringify(body) : undefined,\n    });\n    const json = await res.json().catch(() => ({}));\n    if (!res.ok) throw new Error(json.error ?? \"Request failed.\");\n    return json;\n  }\n\n  async function handleAdd() {\n    const name = newName.trim();\n    if (!name) return setError(\"Name is required.\");\n    setBusy(true);\n    setError(null);\n    try {\n      const json = await call(\"/api/admin/video-categories\", \"POST\", { name });\n      setCategories((prev) => [...prev, { id: json.id, name, status: 1, count: 0 }]);\n      setNewName(\"\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function handleRename(id: number) {\n    const name = editName.trim();\n    if (!name) return;\n    setBusy(true);\n    try {\n      await call(`/api/admin/video-categories/${id}`, \"PATCH\", { name });\n      setCategories((prev) => prev.map((c) => (c.id === id ? { ...c, name } : c)));\n      setEditingId(null);\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function toggle(c: Category) {\n    const status = c.status === 1 ? 0 : 1;\n    setCategories((prev) => prev.map((x) => (x.id === c.id ? { ...x, status } : x)));\n    try {\n      await call(`/api/admin/video-categories/${c.id}`, \"PATCH\", { status });\n    } catch (e) {\n      setError((e as Error).message);\n    }\n  }\n\n  async function move(index: number, dir: -1 | 1) {\n    const target = index + dir;\n    if (target < 0 || target >= categories.length) return;\n    const next = [...categories];\n    [next[index], next[target]] = [next[target], next[index]];\n    setCategories(next);\n    try {\n      await call(\"/api/admin/video-categories\", \"PUT\", { order: next.map((c) => c.id) });\n    } catch (e) {\n      setError((e as Error).message);\n    }\n  }\n\n  async function handleDelete(c: Category) {\n    const msg = c.count\n      ? `Delete \"${c.name}\"? Its ${c.count} video(s) will stay on the site as Uncategorised.`\n      : `Delete \"${c.name}\"?`;\n    if (!confirm(msg)) return;\n    setBusy(true);\n    try {\n      await call(`/api/admin/video-categories/${c.id}`, \"DELETE\");\n      setCategories((prev) => prev.filter((x) => x.id !== c.id));\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className=\"space-y-5\">\n      <div className=\"p-5 bg-white border border-border rounded-xl\">\n        <h2 className=\"mb-4 text-base font-bold font-display text-green\">Add New Category</h2>\n        <div className=\"flex gap-3\">\n          <input\n            type=\"text\"\n            value={newName}\n            onChange={(e) => setNewName(e.target.value)}\n            onKeyDown={(e) => e.key === \"Enter\" && handleAdd()}\n            placeholder=\"e.g. Interviews, Events, Culture…\"\n            className=\"flex-1 border border-border rounded-md px-3 py-2.5 text-sm font-body focus:outline-none focus:border-gold\"\n          />\n          <button\n            onClick={handleAdd}\n            disabled={busy}\n            className=\"bg-gold text-white px-5 py-2.5 rounded-md text-sm font-semibold font-body hover:bg-gold-light hover:text-ink-dark disabled:opacity-50\"\n          >\n            Add\n          </button>\n        </div>\n        {error && <p className=\"mt-2 text-xs text-red-500 font-body\">{error}</p>}\n      </div>\n\n      <div className=\"overflow-hidden bg-white border border-border rounded-xl\">\n        <div className=\"flex items-center justify-between px-5 py-3 border-b border-border bg-cream\">\n          <p className=\"text-xs font-bold tracking-wide uppercase text-ink-muted font-body\">\n            {categories.length} categories\n          </p>\n          {uncategorised > 0 && (\n            <p className=\"text-xs text-ink-muted font-body\">\n              {uncategorised} video(s) uncategorised ·{\" \"}\n              <Link href=\"/admin/media\" className=\"text-gold hover:underline\">\n                assign them\n              </Link>\n            </p>\n          )}\n        </div>\n        {categories.length === 0 ? (\n          <p className=\"px-5 py-10 text-sm text-center text-ink-muted font-body\">\n            No categories yet. Add your first one above.\n          </p>\n        ) : (\n          <div className=\"divide-y divide-border\">\n            {categories.map((c, i) => (\n              <div key={c.id} className=\"flex items-center gap-3 px-5 py-3\">\n                <div className=\"flex flex-col\">\n                  <button onClick={() => move(i, -1)} disabled={i === 0} className=\"text-[10px] leading-none text-ink-muted hover:text-green disabled:opacity-25\" aria-label=\"Move up\">▲</button>\n                  <button onClick={() => move(i, 1)} disabled={i === categories.length - 1} className=\"text-[10px] leading-none text-ink-muted hover:text-green disabled:opacity-25\" aria-label=\"Move down\">▼</button>\n                </div>\n                {editingId === c.id ? (\n                  <>\n                    <input\n                      type=\"text\"\n                      value={editName}\n                      onChange={(e) => setEditName(e.target.value)}\n                      onKeyDown={(e) => e.key === \"Enter\" && handleRename(c.id)}\n                      autoFocus\n                      className=\"flex-1 border border-gold rounded-md px-3 py-1.5 text-sm font-body focus:outline-none\"\n                    />\n                    <button onClick={() => handleRename(c.id)} disabled={busy} className=\"text-xs font-semibold text-green font-body hover:underline\">Save</button>\n                    <button onClick={() => setEditingId(null)} className=\"text-xs text-ink-muted font-body hover:underline\">Cancel</button>\n                  </>\n                ) : (\n                  <>\n                    <div className=\"flex-1 min-w-0\">\n                      <p className={`text-sm font-body ${c.status === 1 ? \"text-ink-dark\" : \"text-ink-muted line-through\"}`}>{c.name}</p>\n                      <p className=\"text-[11px] text-ink-muted font-body\">{c.count} video{c.count === 1 ? \"\" : \"s\"}</p>\n                    </div>\n                    <button\n                      onClick={() => toggle(c)}\n                      className={`text-[11px] font-bold px-2.5 py-1 rounded-md border font-body ${\n                        c.status === 1\n                          ? \"bg-green/10 text-green border-green/20\"\n                          : \"bg-amber-50 text-amber-700 border-amber-200\"\n                      }`}\n                    >\n                      {c.status === 1 ? \"● Live\" : \"● Hidden\"}\n                    </button>\n                    <button onClick={() => { setEditingId(c.id); setEditName(c.name); }} className=\"text-xs font-semibold text-gold font-body hover:underline\">Rename</button>\n                    <button onClick={() => handleDelete(c)} disabled={busy} className=\"text-xs text-red-500 font-body hover:underline disabled:opacity-50\">Delete</button>\n                  </>\n                )}\n              </div>\n            ))}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/video-categories/page.tsx": "import { prisma } from \"@/app/lib/prisma\";\nimport VideoCategoriesClient from \"./VideoCategoriesClient\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function VideoCategoriesPage() {\n  const [categories, counts] = await Promise.all([\n    prisma.videoCategory.findMany({ orderBy: [{ sortOrder: \"asc\" }, { name: \"asc\" }] }),\n    prisma.video.groupBy({ by: [\"category\"], _count: { _all: true } }),\n  ]);\n  const countMap = new Map(counts.map((c) => [c.category, c._count._all]));\n  const known = new Set(categories.map((c) => c.id));\n  const uncategorised = counts\n    .filter((c) => !known.has(c.category))\n    .reduce((sum, c) => sum + c._count._all, 0);\n\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <div className=\"max-w-[700px]\">\n        <h1 className=\"mb-1 text-2xl font-bold font-display text-green\">Pride TV Categories</h1>\n        <p className=\"mb-8 text-sm text-ink-muted font-body\">\n          Group Pride TV videos into categories. Visitors can filter by these on the Pride TV page.\n          Hidden categories don&apos;t appear on the website.\n        </p>\n        <VideoCategoriesClient\n          categories={categories.map((c) => ({\n            id: c.id,\n            name: c.name,\n            status: c.status,\n            count: countMap.get(c.id) ?? 0,\n          }))}\n          uncategorised={uncategorised}\n        />\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/media/page.tsx": "import MediaAdminClient from \"./MediaAdminClient\";\nimport { prisma } from \"@/app/lib/prisma\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function AdminMediaPage() {\n  const [rows, categories] = await Promise.all([\n    prisma.video.findMany({ orderBy: { datetime: \"desc\" } }).catch(() => []),\n    prisma.videoCategory\n      .findMany({ orderBy: [{ sortOrder: \"asc\" }, { name: \"asc\" }] })\n      .catch(() => []),\n  ]);\n\n  const videos = rows.map((v) => ({\n    video_id: Number(v.video_id),\n    title: v.title,\n    video_embed_code: v.video_embed_code,\n    thumb_url: v.thumb_url,\n    status: v.status,\n    featured: v.featured,\n    views: Number(v.views),\n    datetime: v.datetime.toISOString(),\n    category: v.category,\n  }));\n\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <div className=\"max-w-[900px]\">\n        <h1 className=\"mb-1 text-2xl font-bold font-display text-green\">\n          Pride TV Media\n        </h1>\n        <p className=\"mb-8 text-sm text-ink-muted font-body\">\n          Add YouTube videos with a custom caption. They appear as embedded\n          players on the homepage and Pride TV page.\n        </p>\n        <MediaAdminClient\n          videos={videos}\n          categories={categories.map((c) => ({ id: c.id, name: c.name }))}\n        />\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/media/MediaAdminClient.tsx": "\"use client\";\nimport { useState } from \"react\";\n\ninterface Video {\n  video_id: number;\n  title: string;\n  video_embed_code: string;\n  thumb_url: string;\n  status: string;\n  featured: string;\n  views: number;\n  datetime: string;\n  category: number;\n}\n\ninterface Category {\n  id: number;\n  name: string;\n}\n\nfunction extractYoutubeId(input: string): string | null {\n  const patterns = [\n    /youtube\\.com\\/embed\\/([^\"?&/\\s]+)/,\n    /youtu\\.be\\/([^\"?&/\\s]+)/,\n    /youtube\\.com\\/watch\\?v=([^\"?&/\\s]+)/,\n    /youtube\\.com\\/v\\/([^\"?&/\\s]+)/,\n    /youtube\\.com\\/shorts\\/([^\"?&/\\s]+)/,\n  ];\n  for (const p of patterns) {\n    const m = input.match(p);\n    if (m?.[1]) return m[1];\n  }\n  return null;\n}\n\nfunction getEmbedUrl(input: string): string {\n  const id = extractYoutubeId(input);\n  if (id) return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1`;\n  // If already an embed URL, return as-is\n  if (\n    input.includes(\"youtube.com/embed/\") ||\n    input.includes(\"vimeo.com/video/\")\n  )\n    return input;\n  return input;\n}\n\nfunction getThumbnail(input: string): string {\n  const id = extractYoutubeId(input);\n  if (id) return `https://img.youtube.com/vi/${id}/hqdefault.jpg`;\n  return \"\";\n}\n\nexport default function MediaAdminClient({\n  videos: initial,\n  categories,\n}: {\n  videos: Video[];\n  categories: Category[];\n}) {\n  const EMPTY_FORM = {\n    title: \"\",\n    url: \"\",\n    featured: false,\n    category: categories[0]?.id ?? 0,\n  };\n  const categoryName = (id: number) =>\n    categories.find((c) => c.id === id)?.name ?? \"Uncategorised\";\n\n  const [videos, setVideos] = useState(initial);\n  const [form, setForm] = useState(EMPTY_FORM);\n  const [filter, setFilter] = useState<number | \"all\">(\"all\");\n  const [editingId, setEditingId] = useState<number | null>(null);\n  const [saving, setSaving] = useState(false);\n  const [deleting, setDeleting] = useState<number | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [preview, setPreview] = useState<string | null>(null);\n\n  // When URL changes - show thumbnail preview\n  function handleUrlChange(val: string) {\n    setForm((f) => ({ ...f, url: val }));\n    const thumb = getThumbnail(val);\n    setPreview(thumb || null);\n  }\n\n  function openEdit(v: Video) {\n    setForm({\n      title: v.title,\n      url: v.video_embed_code,\n      featured: v.featured === \"feature\",\n      category: categories.some((c) => c.id === v.category) ? v.category : 0,\n    });\n    setEditingId(v.video_id);\n    setPreview(getThumbnail(v.video_embed_code) || v.thumb_url || null);\n    setError(null);\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\n  }\n\n  function resetForm() {\n    setForm(EMPTY_FORM);\n    setEditingId(null);\n    setPreview(null);\n    setError(null);\n  }\n\n  async function handleSave() {\n    if (!form.title.trim()) {\n      setError(\"Caption is required.\");\n      return;\n    }\n    if (!form.url.trim()) {\n      setError(\"YouTube URL or embed code is required.\");\n      return;\n    }\n\n    const embedUrl = getEmbedUrl(form.url);\n    const thumb = getThumbnail(form.url) || \"\";\n\n    setSaving(true);\n    setError(null);\n\n    try {\n      if (editingId !== null) {\n        const res = await fetch(\"/api/admin/videos\", {\n          method: \"PATCH\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({\n            video_id: editingId,\n            title: form.title.trim(),\n            video_embed_code: embedUrl,\n            thumb_url: thumb,\n            featured: form.featured,\n            category: form.category,\n          }),\n        });\n        if (!res.ok) throw new Error();\n\n        setVideos((prev) =>\n          prev.map((v) =>\n            v.video_id === editingId\n              ? {\n                  ...v,\n                  title: form.title.trim(),\n                  video_embed_code: embedUrl,\n                  thumb_url: thumb,\n                  featured: form.featured ? \"feature\" : \"no\",\n                  category: form.category,\n                }\n              : v,\n          ),\n        );\n      } else {\n        const res = await fetch(\"/api/admin/videos\", {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({\n            title: form.title.trim(),\n            video_embed_code: embedUrl,\n            thumb_url: thumb,\n            featured: form.featured,\n            description: \"\",\n            tags: \"\",\n            category: form.category,\n          }),\n        });\n        if (!res.ok) throw new Error();\n\n        const json = await res.json();\n        setVideos((prev) => [\n          {\n            video_id: json.video_id,\n            title: form.title.trim(),\n            video_embed_code: embedUrl,\n            thumb_url: thumb,\n            status: \"active\",\n            featured: form.featured ? \"feature\" : \"no\",\n            views: 0,\n            datetime: new Date().toISOString(),\n            category: form.category,\n          },\n          ...prev,\n        ]);\n      }\n      resetForm();\n    } catch {\n      setError(\"Something went wrong. Please try again.\");\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  async function toggleStatus(v: Video) {\n    const newStatus = v.status === \"active\" ? \"inactive\" : \"active\";\n    await fetch(\"/api/admin/videos\", {\n      method: \"PATCH\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ video_id: v.video_id, status: newStatus }),\n    });\n    setVideos((prev) =>\n      prev.map((vid) =>\n        vid.video_id === v.video_id ? { ...vid, status: newStatus } : vid,\n      ),\n    );\n  }\n\n  async function toggleFeatured(v: Video) {\n    const featured = v.featured !== \"feature\";\n    await fetch(\"/api/admin/videos\", {\n      method: \"PATCH\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ video_id: v.video_id, featured }),\n    });\n    setVideos((prev) =>\n      prev.map((vid) =>\n        vid.video_id === v.video_id\n          ? { ...vid, featured: featured ? \"feature\" : \"no\" }\n          : vid,\n      ),\n    );\n  }\n\n  async function handleDelete(id: number) {\n    if (!confirm(\"Delete this video? This cannot be undone.\")) return;\n    setDeleting(id);\n    try {\n      await fetch(`/api/admin/videos?id=${id}`, { method: \"DELETE\" });\n      setVideos((prev) => prev.filter((v) => v.video_id !== id));\n    } finally {\n      setDeleting(null);\n    }\n  }\n\n  const known = new Set(categories.map((c) => c.id));\n  const shown =\n    filter === \"all\"\n      ? videos\n      : filter === 0\n        ? videos.filter((v) => !known.has(v.category))\n        : videos.filter((v) => v.category === filter);\n\n  return (\n    <div className=\"space-y-8\">\n      {/* Add / Edit form */}\n      <div className=\"p-6 space-y-5 bg-white border border-border rounded-xl\">\n        <h2 className=\"text-lg font-bold font-display text-green\">\n          {editingId !== null ? \"Edit Video\" : \"Add a New Video\"}\n        </h2>\n\n        {/* Caption */}\n        <div>\n          <label className=\"block text-sm font-semibold text-ink-dark mb-1.5 font-body\">\n            Caption <span className=\"text-gold\">*</span>\n          </label>\n          <input\n            type=\"text\"\n            value={form.title}\n            onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}\n            className=\"w-full border border-border rounded-md px-3.5 py-2.5 text-sm font-body focus:outline-none focus:border-gold transition-colors\"\n            placeholder=\"e.g. Pakistan National Day Celebrations 2024\"\n          />\n        </div>\n\n        {/* YouTube URL */}\n        <div>\n          <label className=\"block text-sm font-semibold text-ink-dark mb-1.5 font-body\">\n            YouTube URL <span className=\"text-gold\">*</span>\n          </label>\n          <input\n            type=\"text\"\n            value={form.url}\n            onChange={(e) => handleUrlChange(e.target.value)}\n            className=\"w-full border border-border rounded-md px-3.5 py-2.5 text-sm font-body focus:outline-none focus:border-gold transition-colors\"\n            placeholder=\"https://www.youtube.com/watch?v=...\"\n          />\n          <p className=\"text-xs text-ink-muted font-body mt-1.5\">\n            Paste any YouTube URL - watch page, short, or share link. Thumbnail\n            is auto-extracted.\n          </p>\n        </div>\n\n        {/* Category */}\n        <div>\n          <label className=\"block text-sm font-semibold text-ink-dark mb-1.5 font-body\">\n            Category\n          </label>\n          <select\n            value={form.category}\n            onChange={(e) =>\n              setForm((f) => ({ ...f, category: Number(e.target.value) }))\n            }\n            className=\"w-full border border-border rounded-md px-3.5 py-2.5 text-sm font-body bg-white focus:outline-none focus:border-gold transition-colors\"\n          >\n            {categories.map((c) => (\n              <option key={c.id} value={c.id}>\n                {c.name}\n              </option>\n            ))}\n            <option value={0}>Uncategorised</option>\n          </select>\n          <p className=\"text-xs text-ink-muted font-body mt-1.5\">\n            Manage categories under{\" \"}\n            <a href=\"/admin/video-categories\" className=\"text-gold hover:underline\">\n              Pride TV → Video Categories\n            </a>\n            .\n          </p>\n        </div>\n\n        {/* Thumbnail preview */}\n        {preview && (\n          <div>\n            <p className=\"mb-2 text-xs font-semibold tracking-wide uppercase text-ink-muted font-body\">\n              Thumbnail Preview\n            </p>\n            <div className=\"w-48 overflow-hidden border rounded-lg border-border aspect-video\">\n              {/* eslint-disable-next-line @next/next/no-img-element */}\n              <img\n                src={preview}\n                alt=\"Video thumbnail\"\n                className=\"object-fit w-full h-full\"\n              />\n            </div>\n          </div>\n        )}\n\n        {/* Featured toggle */}\n        <label className=\"flex items-center gap-3 cursor-pointer select-none\">\n          <button\n            type=\"button\"\n            onClick={() => setForm((f) => ({ ...f, featured: !f.featured }))}\n            className={`w-10 h-5 rounded-full transition-colors flex items-center flex-shrink-0 ${form.featured ? \"bg-gold\" : \"bg-border\"}`}\n          >\n            <div\n              className={`w-4 h-4 bg-white rounded-full shadow transition-transform mx-0.5 ${form.featured ? \"translate-x-5\" : \"translate-x-0\"}`}\n            />\n          </button>\n          <div>\n            <p className=\"text-sm font-semibold text-ink-dark font-body\">\n              Featured\n            </p>\n            <p className=\"text-xs text-ink-muted font-body\">\n              Featured videos appear prominently on the homepage\n            </p>\n          </div>\n        </label>\n\n        {error && <p className=\"text-sm text-red-500 font-body\">{error}</p>}\n\n        <div className=\"flex gap-3\">\n          <button\n            onClick={handleSave}\n            disabled={saving}\n            className=\"bg-gold text-white px-6 py-2.5 rounded-md text-sm font-semibold font-body hover:bg-gold-light hover:text-ink-dark transition-colors disabled:opacity-50\"\n          >\n            {saving\n              ? \"Saving...\"\n              : editingId !== null\n                ? \"Update Video\"\n                : \"Add Video\"}\n          </button>\n          {editingId !== null && (\n            <button\n              onClick={resetForm}\n              className=\"border border-border text-ink-mid px-6 py-2.5 rounded-md text-sm font-semibold font-body hover:border-green hover:text-green transition-colors\"\n            >\n              Cancel\n            </button>\n          )}\n        </div>\n      </div>\n\n      {/* Video list */}\n      <div>\n        <div className=\"flex flex-wrap items-center justify-between gap-3 mb-4\">\n          <h2 className=\"text-lg font-bold font-display text-green\">\n            All Videos{\" \"}\n            <span className=\"text-base font-normal text-ink-muted\">\n              ({shown.length})\n            </span>\n          </h2>\n          <select\n            value={filter}\n            onChange={(e) =>\n              setFilter(e.target.value === \"all\" ? \"all\" : Number(e.target.value))\n            }\n            className=\"px-3 py-2 text-sm bg-white border rounded-md border-border font-body focus:outline-none focus:border-gold\"\n          >\n            <option value=\"all\">All categories</option>\n            {categories.map((c) => (\n              <option key={c.id} value={c.id}>\n                {c.name}\n              </option>\n            ))}\n            <option value={0}>Uncategorised</option>\n          </select>\n        </div>\n\n        {shown.length === 0 ? (\n          <div className=\"py-16 text-center bg-white border border-border rounded-xl\">\n            <p className=\"text-sm text-ink-muted font-body\">\n              {filter === \"all\"\n                ? \"No videos added yet. Add your first one above.\"\n                : \"No videos in this category.\"}\n            </p>\n          </div>\n        ) : (\n          <div className=\"space-y-3\">\n            {shown.map((v) => (\n              <div\n                key={v.video_id}\n                className=\"overflow-hidden bg-white border border-border rounded-xl\"\n              >\n                <div className=\"flex items-center gap-4 p-4\">\n                  {/* Thumbnail */}\n                  <div className=\"w-32 h-[72px] rounded-lg overflow-hidden bg-cream border border-border flex-shrink-0 relative\">\n                    {v.thumb_url ? (\n                      // eslint-disable-next-line @next/next/no-img-element\n                      <img\n                        src={v.thumb_url}\n                        alt={v.title}\n                        className=\"object-fit w-full h-full\"\n                      />\n                    ) : (\n                      <div className=\"flex items-center justify-center w-full h-full bg-green/10\">\n                        <div className=\"w-6 h-6 border-2 rounded-sm border-green/30\" />\n                      </div>\n                    )}\n                    {/* Play overlay */}\n                    <div className=\"absolute inset-0 flex items-center justify-center bg-black/20\">\n                      <div className=\"flex items-center justify-center rounded-full w-7 h-7 bg-white/90\">\n                        <div className=\"w-0 h-0 border-t-[5px] border-b-[5px] border-l-[9px] border-t-transparent border-b-transparent border-l-green ml-0.5\" />\n                      </div>\n                    </div>\n                  </div>\n\n                  {/* Info */}\n                  <div className=\"flex-1 min-w-0\">\n                    <div className=\"flex items-center gap-2 flex-wrap mb-0.5\">\n                      <p className=\"text-sm font-semibold truncate text-ink-dark font-body\">\n                        {v.title}\n                      </p>\n                      {v.featured === \"feature\" && (\n                        <span className=\"text-[10px] font-bold text-gold bg-gold-pale px-2 py-0.5 rounded font-body flex-shrink-0\">\n                          Featured\n                        </span>\n                      )}\n                    </div>\n                    <p className=\"text-xs text-ink-muted font-body\">\n                      Added{\" \"}\n                      {new Date(v.datetime).toLocaleDateString(\"en-GB\", {\n                        day: \"numeric\",\n                        month: \"short\",\n                        year: \"numeric\",\n                      })}\n                      {\" · \"}\n                      {v.views.toLocaleString()} views\n                      {\" · \"}\n                      <span className=\"font-semibold text-ink-mid\">\n                        {categoryName(v.category)}\n                      </span>\n                    </p>\n                  </div>\n\n                  {/* Actions */}\n                  <div className=\"flex flex-wrap items-center justify-end flex-shrink-0 gap-3\">\n                    <span\n                      className={`text-[11px] font-bold px-2.5 py-0.5 rounded border font-body ${\n                        v.status === \"active\"\n                          ? \"bg-green/10 text-green border-green/20\"\n                          : \"bg-gray-50 text-gray-400 border-gray-200\"\n                      }`}\n                    >\n                      {v.status}\n                    </span>\n                    <button\n                      onClick={() => toggleFeatured(v)}\n                      className=\"text-xs transition-colors text-ink-muted font-body hover:text-gold\"\n                    >\n                      {v.featured === \"feature\" ? \"Unfeature\" : \"Feature\"}\n                    </button>\n                    <button\n                      onClick={() => toggleStatus(v)}\n                      className=\"text-xs transition-colors text-ink-muted font-body hover:text-green\"\n                    >\n                      {v.status === \"active\" ? \"Deactivate\" : \"Activate\"}\n                    </button>\n                    <button\n                      onClick={() => openEdit(v)}\n                      className=\"text-xs font-semibold text-gold font-body hover:underline\"\n                    >\n                      Edit\n                    </button>\n                    <button\n                      onClick={() => handleDelete(v.video_id)}\n                      disabled={deleting === v.video_id}\n                      className=\"text-xs text-red-500 font-body hover:underline disabled:opacity-50\"\n                    >\n                      {deleting === v.video_id ? \"...\" : \"Delete\"}\n                    </button>\n                  </div>\n                </div>\n              </div>\n            ))}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/pages/page.tsx": "import Link from \"next/link\";\n\nconst GROUPS = [\n  {\n    title: \"Page headings\",\n    desc: \"The green banner at the top of each page.\",\n    pages: [\n      { label: \"Homepage\", href: \"/admin/homepage\" },\n      { label: \"Who Is Who\", href: \"/admin/pages/whoiswho\" },\n      { label: \"Pakistani Products\", href: \"/admin/pages/products\" },\n      { label: \"Pakistani Businesses\", href: \"/admin/pages/businesses\" },\n      { label: \"Discussion Forum\", href: \"/admin/pages/news\" },\n      { label: \"Your Stories\", href: \"/admin/pages/stories\" },\n      { label: \"Pride TV\", href: \"/admin/pages/pridetv\" },\n      { label: \"Pride Team\", href: \"/admin/pages/team\" },\n      { label: \"Our Sponsors\", href: \"/admin/pages/sponsors\" },\n    ],\n  },\n  {\n    title: \"Full pages\",\n    desc: \"Pages where you can edit all the text.\",\n    pages: [\n      { label: \"About Us\", href: \"/admin/pages/about\" },\n      { label: \"Our Mission\", href: \"/admin/pages/mission\" },\n      { label: \"Contact Us\", href: \"/admin/pages/contact\" },\n      { label: \"Terms & Conditions\", href: \"/admin/pages/legal/terms\" },\n      { label: \"Privacy Policy\", href: \"/admin/pages/legal/privacy\" },\n      { label: \"Disclaimer\", href: \"/admin/pages/legal/disclaimer\" },\n    ],\n  },\n];\n\nexport default function AdminPagesIndex() {\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <div className=\"max-w-[900px]\">\n        <h1 className=\"mb-1 text-2xl font-bold font-display text-green\">Pages</h1>\n        <p className=\"mb-8 text-sm text-ink-muted font-body\">Choose a page to edit.</p>\n        <div className=\"space-y-8\">\n          {GROUPS.map((g) => (\n            <div key={g.title}>\n              <h2 className=\"text-base font-bold font-display text-green\">{g.title}</h2>\n              <p className=\"mb-3 text-xs text-ink-muted font-body\">{g.desc}</p>\n              <div className=\"grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3\">\n                {g.pages.map((p) => (\n                  <Link\n                    key={p.href}\n                    href={p.href}\n                    className=\"flex items-center justify-between px-4 py-3.5 text-sm font-semibold no-underline bg-white border rounded-xl border-border text-ink-dark font-body hover:border-gold hover:text-gold transition-colors\"\n                  >\n                    {p.label}\n                    <span className=\"text-gold\">→</span>\n                  </Link>\n                ))}\n              </div>\n            </div>\n          ))}\n        </div>\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/pages/sponsors/page.tsx": "import { getPageContent } from \"@/app/lib/pageContent\";\nimport PageHeroEditor from \"../PageHeroEditor\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function Editor() {\n  const content = await getPageContent(\"page_sponsors\");\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <PageHeroEditor\n        section=\"page_sponsors\"\n        label=\"Our Sponsors Page\"\n        initial={{\n          eyebrow: content.eyebrow,\n          heading: content.heading,\n          subtext: content.subtext,\n        }}\n      />\n    </div>\n  );\n}\n",
"app/(admin)/admin/pages/team/page.tsx": "import { getPageContent } from \"@/app/lib/pageContent\";\nimport PageHeroEditor from \"../PageHeroEditor\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function Editor() {\n  const content = await getPageContent(\"page_team\");\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <PageHeroEditor\n        section=\"page_team\"\n        label=\"Pride Team Page\"\n        initial={{\n          eyebrow: content.eyebrow,\n          heading: content.heading,\n          subtext: content.subtext,\n        }}\n      />\n    </div>\n  );\n}\n",
"app/(admin)/admin/pages/legal/[slug]/page.tsx": "import { notFound } from \"next/navigation\";\nimport {\n  LEGAL_DEFAULTS,\n  LEGAL_PAGES,\n  getLegalContent,\n  isLegalSlug,\n} from \"@/app/lib/legalContent\";\nimport LegalEditorClient from \"./LegalEditorClient\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function LegalEditorPage({\n  params,\n}: {\n  params: Promise<{ slug: string }>;\n}) {\n  const { slug } = await params;\n  if (!isLegalSlug(slug)) notFound();\n\n  const content = await getLegalContent(slug);\n\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <LegalEditorClient\n        slug={slug}\n        label={LEGAL_PAGES[slug].label}\n        publicPath={LEGAL_PAGES[slug].path}\n        initial={content}\n        defaults={LEGAL_DEFAULTS[slug]}\n      />\n    </div>\n  );\n}\n",
"app/(admin)/admin/pages/legal/[slug]/LegalEditorClient.tsx": "\"use client\";\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport RichEditor from \"@/app/components/admin/RichEditor\";\nimport type { LegalContent, LegalSection } from \"@/app/lib/legalContent\";\n\nconst input =\n  \"w-full px-3 py-2.5 text-sm border border-border rounded-md font-body focus:outline-none focus:border-gold transition-colors\";\nconst labelCls =\n  \"block text-xs font-semibold text-ink-muted uppercase tracking-wide mb-1.5 font-body\";\n\nconst newId = () => `s${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n\nexport default function LegalEditorClient({\n  slug,\n  label,\n  publicPath,\n  initial,\n  defaults,\n}: {\n  slug: string;\n  label: string;\n  publicPath: string;\n  initial: LegalContent;\n  defaults: LegalContent;\n}) {\n  const [title, setTitle] = useState(initial.title);\n  const [intro, setIntro] = useState(initial.intro);\n  const [sections, setSections] = useState<LegalSection[]>(initial.sections);\n  const [updatedAt, setUpdatedAt] = useState(initial.updatedAt);\n  // Bumping this remounts every editor (used after \"Reset\")\n  const [version, setVersion] = useState(0);\n  const [saving, setSaving] = useState(false);\n  const [dirty, setDirty] = useState(false);\n  const [message, setMessage] = useState<{ ok: boolean; text: string } | null>(null);\n\n  function touch() {\n    setDirty(true);\n    setMessage(null);\n  }\n\n  function update(id: string, patch: Partial<LegalSection>) {\n    setSections((prev) => prev.map((s) => (s.id === id ? { ...s, ...patch } : s)));\n    touch();\n  }\n\n  function move(i: number, dir: -1 | 1) {\n    const j = i + dir;\n    if (j < 0 || j >= sections.length) return;\n    setSections((prev) => {\n      const next = [...prev];\n      [next[i], next[j]] = [next[j], next[i]];\n      return next;\n    });\n    touch();\n  }\n\n  function addSection(at?: number) {\n    const s: LegalSection = { id: newId(), heading: \"\", html: \"\" };\n    setSections((prev) => {\n      const next = [...prev];\n      next.splice(at ?? next.length, 0, s);\n      return next;\n    });\n    touch();\n  }\n\n  function removeSection(s: LegalSection) {\n    if (!confirm(`Delete the section \"${s.heading || \"untitled\"}\"?`)) return;\n    setSections((prev) => prev.filter((x) => x.id !== s.id));\n    touch();\n  }\n\n  function resetToOriginal() {\n    if (!confirm(\"Replace everything on this page with the original website text? You can still cancel by not saving.\")) return;\n    setTitle(defaults.title);\n    setIntro(defaults.intro);\n    setSections(defaults.sections.map((s) => ({ ...s, id: newId() })));\n    setVersion((v) => v + 1);\n    touch();\n  }\n\n  async function save() {\n    if (!title.trim()) return setMessage({ ok: false, text: \"Page title is required.\" });\n    setSaving(true);\n    setMessage(null);\n    try {\n      const res = await fetch(`/api/admin/legal/${slug}`, {\n        method: \"PATCH\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ title, intro, sections }),\n      });\n      const json = await res.json().catch(() => ({}));\n      if (!res.ok) return setMessage({ ok: false, text: json.error ?? \"Failed to save.\" });\n      setUpdatedAt(json.content.updatedAt);\n      setSections(json.content.sections);\n      setDirty(false);\n      setMessage({ ok: true, text: \"Saved. The page is updated on the website.\" });\n    } catch {\n      setMessage({ ok: false, text: \"Something went wrong.\" });\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  return (\n    <div className=\"max-w-[860px] pb-24\">\n      <div className=\"flex flex-wrap items-center gap-3 mb-2\">\n        <Link href=\"/admin/pages\" className=\"text-sm no-underline text-gold font-body hover:underline\">\n          ← Pages\n        </Link>\n        <span className=\"text-ink-muted\">/</span>\n        <h1 className=\"text-2xl font-bold font-display text-green\">{label}</h1>\n      </div>\n      <div className=\"flex flex-wrap items-center gap-4 mb-8 text-xs text-ink-muted font-body\">\n        <span>\n          {updatedAt\n            ? `Last saved ${new Date(updatedAt).toLocaleString(\"en-GB\", { day: \"numeric\", month: \"short\", year: \"numeric\", hour: \"2-digit\", minute: \"2-digit\" })}`\n            : \"Showing the original website text - not edited yet\"}\n        </span>\n        <a href={publicPath} target=\"_blank\" className=\"font-semibold text-gold hover:underline\">\n          View page ↗\n        </a>\n        <button type=\"button\" onClick={resetToOriginal} className=\"hover:text-red-500\">\n          Reset to original text\n        </button>\n      </div>\n\n      <div className=\"p-6 mb-6 space-y-5 bg-white border border-border rounded-xl\">\n        <div>\n          <label className={labelCls}>Page title</label>\n          <input className={input} value={title} onChange={(e) => { setTitle(e.target.value); touch(); }} />\n        </div>\n        <div>\n          <label className={labelCls}>Introduction (optional)</label>\n          <RichEditor\n            key={`intro-${version}`}\n            value={intro}\n            onChange={(html) => { setIntro(html); touch(); }}\n            minHeight={80}\n          />\n        </div>\n      </div>\n\n      <div className=\"flex items-center justify-between mb-3\">\n        <h2 className=\"text-lg font-bold font-display text-green\">\n          Sections <span className=\"text-base font-normal text-ink-muted\">({sections.length})</span>\n        </h2>\n        <button type=\"button\" onClick={() => addSection()} className=\"px-4 py-2 text-xs font-semibold text-white rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark\">\n          + Add Section\n        </button>\n      </div>\n\n      {sections.length === 0 && (\n        <div className=\"py-12 mb-4 text-center bg-white border-2 border-dashed border-border rounded-xl\">\n          <p className=\"text-sm text-ink-muted font-body\">No sections yet. Click &quot;Add Section&quot; to start.</p>\n        </div>\n      )}\n\n      <div className=\"space-y-4\">\n        {sections.map((s, i) => (\n          <div key={s.id} className={`p-5 space-y-3 border rounded-xl ${s.hidden ? \"bg-gray-50 border-border\" : \"bg-white border-border\"}`}>\n            <div className=\"flex flex-wrap items-center gap-3\">\n              <span className=\"text-[11px] font-bold uppercase tracking-wide text-ink-muted font-body\">Section {i + 1}</span>\n              <div className=\"flex items-center gap-3 ml-auto text-xs font-body\">\n                <button type=\"button\" onClick={() => move(i, -1)} disabled={i === 0} className=\"text-ink-muted hover:text-green disabled:opacity-30\">↑ Up</button>\n                <button type=\"button\" onClick={() => move(i, 1)} disabled={i === sections.length - 1} className=\"text-ink-muted hover:text-green disabled:opacity-30\">↓ Down</button>\n                <button\n                  type=\"button\"\n                  onClick={() => update(s.id, { hidden: !s.hidden })}\n                  className={`text-[11px] font-bold px-2.5 py-1 rounded-md border ${s.hidden ? \"bg-amber-50 text-amber-700 border-amber-200\" : \"bg-green/10 text-green border-green/20\"}`}\n                >\n                  {s.hidden ? \"● Hidden\" : \"● Live\"}\n                </button>\n                <button type=\"button\" onClick={() => removeSection(s)} className=\"text-red-500 hover:text-red-700\">Delete</button>\n              </div>\n            </div>\n            <input\n              className={input}\n              value={s.heading}\n              onChange={(e) => update(s.id, { heading: e.target.value })}\n              placeholder=\"Section heading (optional)\"\n            />\n            <RichEditor\n              key={`${s.id}-${version}`}\n              value={s.html}\n              onChange={(html) => update(s.id, { html })}\n            />\n            <button type=\"button\" onClick={() => addSection(i + 1)} className=\"text-xs font-semibold text-gold font-body hover:underline\">\n              + Add a section below\n            </button>\n          </div>\n        ))}\n      </div>\n\n      {/* Sticky save bar */}\n      <div className=\"fixed bottom-0 left-0 right-0 z-30 border-t lg:left-64 bg-white/95 backdrop-blur border-border\">\n        <div className=\"flex items-center gap-4 px-4 py-3 lg:px-8 max-w-[924px]\">\n          <button\n            type=\"button\"\n            onClick={save}\n            disabled={saving}\n            className=\"px-8 py-2.5 text-sm font-semibold text-white rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark disabled:opacity-50\"\n          >\n            {saving ? \"Saving…\" : \"Save Changes\"}\n          </button>\n          {message ? (\n            <p className={`text-sm font-body ${message.ok ? \"text-green\" : \"text-red-500\"}`}>{message.text}</p>\n          ) : dirty ? (\n            <p className=\"text-sm text-amber-700 font-body\">You have unsaved changes.</p>\n          ) : null}\n        </div>\n      </div>\n    </div>\n  );\n}\n",
"app/(admin)/admin/pages/contact/page.tsx": "import { getPageContent } from \"@/app/lib/pageContent\";\nimport { getContactInfo } from \"@/app/lib/contactInfo\";\nimport PageHeroEditor from \"../PageHeroEditor\";\nimport ContactInfoEditor from \"./ContactInfoEditor\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function ContactPageEditor() {\n  const [hero, info] = await Promise.all([\n    getPageContent(\"page_contact\"),\n    getContactInfo(),\n  ]);\n\n  return (\n    <div className=\"p-4 lg:p-8\">\n      <PageHeroEditor\n        section=\"page_contact\"\n        label=\"Contact Page\"\n        initial={{\n          eyebrow: hero.eyebrow,\n          heading: hero.heading,\n          subtext: hero.subtext,\n        }}\n      />\n      <ContactInfoEditor initial={info} />\n    </div>\n  );\n}\n",
"app/(admin)/admin/pages/contact/ContactInfoEditor.tsx": "\"use client\";\nimport { useState } from \"react\";\nimport type {\n  ContactInfo,\n  ContactItem,\n  ContactItemType,\n  SocialLink,\n  SocialPlatform,\n} from \"@/app/lib/contactInfo\";\n\nconst input =\n  \"w-full px-3 py-2.5 text-sm border border-border rounded-md font-body focus:outline-none focus:border-gold transition-colors bg-white\";\nconst labelCls =\n  \"block text-xs font-semibold text-ink-muted uppercase tracking-wide mb-1.5 font-body\";\nconst card = \"p-6 space-y-4 bg-white border border-border rounded-xl\";\n\nconst TYPES: { value: ContactItemType; label: string; placeholder: string }[] = [\n  { value: \"email\", label: \"Email\", placeholder: \"info@prideofpakistan.com\" },\n  { value: \"phone\", label: \"Phone\", placeholder: \"+44 20 1234 5678\" },\n  { value: \"url\", label: \"Website\", placeholder: \"www.prideofpakistan.com\" },\n  { value: \"text\", label: \"Text (e.g. address)\", placeholder: \"123 Street, London\" },\n];\n\nconst PLATFORMS: { value: SocialPlatform; label: string }[] = [\n  { value: \"facebook\", label: \"Facebook\" },\n  { value: \"instagram\", label: \"Instagram\" },\n  { value: \"youtube\", label: \"YouTube\" },\n  { value: \"linkedin\", label: \"LinkedIn\" },\n  { value: \"tiktok\", label: \"TikTok\" },\n  { value: \"whatsapp\", label: \"WhatsApp\" },\n  { value: \"other\", label: \"Other\" },\n];\n\nconst newId = () => `i${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n\nfunction moveIn<T>(list: T[], i: number, dir: -1 | 1): T[] {\n  const j = i + dir;\n  if (j < 0 || j >= list.length) return list;\n  const next = [...list];\n  [next[i], next[j]] = [next[j], next[i]];\n  return next;\n}\n\nfunction RowControls({\n  index,\n  total,\n  hidden,\n  onMove,\n  onToggle,\n  onRemove,\n}: {\n  index: number;\n  total: number;\n  hidden?: boolean;\n  onMove: (dir: -1 | 1) => void;\n  onToggle: () => void;\n  onRemove: () => void;\n}) {\n  return (\n    <div className=\"flex flex-wrap items-center gap-3 text-xs font-body\">\n      <button type=\"button\" onClick={() => onMove(-1)} disabled={index === 0} className=\"text-ink-muted hover:text-green disabled:opacity-30\">↑ Up</button>\n      <button type=\"button\" onClick={() => onMove(1)} disabled={index === total - 1} className=\"text-ink-muted hover:text-green disabled:opacity-30\">↓ Down</button>\n      <button\n        type=\"button\"\n        onClick={onToggle}\n        className={`ml-auto text-[11px] font-bold px-2.5 py-1 rounded-md border ${hidden ? \"bg-amber-50 text-amber-700 border-amber-200\" : \"bg-green/10 text-green border-green/20\"}`}\n      >\n        {hidden ? \"● Hidden\" : \"● Live\"}\n      </button>\n      <button type=\"button\" onClick={onRemove} className=\"text-red-500 hover:text-red-700\">Remove</button>\n    </div>\n  );\n}\n\nexport default function ContactInfoEditor({ initial }: { initial: ContactInfo }) {\n  const [info, setInfo] = useState(initial);\n  const [saving, setSaving] = useState(false);\n  const [message, setMessage] = useState<{ ok: boolean; text: string } | null>(null);\n\n  function set<K extends keyof ContactInfo>(key: K, value: ContactInfo[K]) {\n    setInfo((prev) => ({ ...prev, [key]: value }));\n    setMessage(null);\n  }\n\n  const field = (key: keyof ContactInfo) => ({\n    value: info[key] as string,\n    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>\n      set(key, e.target.value as never),\n  });\n\n  function updateItem(id: string, patch: Partial<ContactItem>) {\n    set(\"items\", info.items.map((it) => (it.id === id ? { ...it, ...patch } : it)));\n  }\n  function updateSocial(id: string, patch: Partial<SocialLink>) {\n    set(\"socials\", info.socials.map((s) => (s.id === id ? { ...s, ...patch } : s)));\n  }\n\n  async function save() {\n    setSaving(true);\n    setMessage(null);\n    try {\n      const res = await fetch(\"/api/admin/contact-info\", {\n        method: \"PATCH\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(info),\n      });\n      const json = await res.json().catch(() => ({}));\n      if (!res.ok) return setMessage({ ok: false, text: json.error ?? \"Failed to save.\" });\n      setInfo(json.content);\n      setMessage({ ok: true, text: \"Contact details saved. They're live on the Contact page.\" });\n    } catch {\n      setMessage({ ok: false, text: \"Something went wrong.\" });\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  return (\n    <div className=\"max-w-[700px] mt-10 space-y-6\">\n      <div>\n        <h2 className=\"text-xl font-bold font-display text-green\">Contact Page Content</h2>\n        <p className=\"mt-1 text-sm text-ink-muted font-body\">\n          Everything below the page heading. Empty rows are removed when you save.\n        </p>\n      </div>\n\n      {/* Intro */}\n      <div className={card}>\n        <h3 className=\"text-base font-bold font-display text-green\">Introduction</h3>\n        <div>\n          <label className={labelCls}>Heading</label>\n          <input className={input} {...field(\"introHeading\")} />\n        </div>\n        <div>\n          <label className={labelCls}>Text</label>\n          <textarea rows={4} className={`${input} resize-none`} {...field(\"introText\")} />\n        </div>\n      </div>\n\n      {/* Contact details */}\n      <div className={card}>\n        <div className=\"flex items-center justify-between\">\n          <h3 className=\"text-base font-bold font-display text-green\">Contact Details</h3>\n          <button\n            type=\"button\"\n            onClick={() => set(\"items\", [...info.items, { id: newId(), label: \"\", value: \"\", type: \"email\" }])}\n            className=\"px-4 py-2 text-xs font-semibold text-white rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark\"\n          >\n            + Add Detail\n          </button>\n        </div>\n        <div>\n          <label className={labelCls}>Box title</label>\n          <input className={input} {...field(\"infoTitle\")} />\n        </div>\n        {info.items.length === 0 && <p className=\"text-sm text-ink-muted font-body\">No contact details yet.</p>}\n        {info.items.map((it, i) => {\n          const type = TYPES.find((t) => t.value === it.type) ?? TYPES[0];\n          return (\n            <div key={it.id} className={`p-4 space-y-3 border rounded-lg ${it.hidden ? \"bg-gray-50 border-border\" : \"bg-cream border-border\"}`}>\n              <div className=\"grid grid-cols-1 gap-3 sm:grid-cols-[1fr_170px]\">\n                <input className={input} value={it.label} onChange={(e) => updateItem(it.id, { label: e.target.value })} placeholder=\"Label, e.g. General Enquiries\" />\n                <select className={input} value={it.type} onChange={(e) => updateItem(it.id, { type: e.target.value as ContactItemType })}>\n                  {TYPES.map((t) => (\n                    <option key={t.value} value={t.value}>{t.label}</option>\n                  ))}\n                </select>\n              </div>\n              <input className={input} value={it.value} onChange={(e) => updateItem(it.id, { value: e.target.value })} placeholder={type.placeholder} />\n              <RowControls\n                index={i}\n                total={info.items.length}\n                hidden={it.hidden}\n                onMove={(d) => set(\"items\", moveIn(info.items, i, d))}\n                onToggle={() => updateItem(it.id, { hidden: !it.hidden })}\n                onRemove={() => set(\"items\", info.items.filter((x) => x.id !== it.id))}\n              />\n            </div>\n          );\n        })}\n      </div>\n\n      {/* Response time */}\n      <div className={card}>\n        <h3 className=\"text-base font-bold font-display text-green\">Response Time Box</h3>\n        <p className=\"text-xs text-ink-muted font-body\">Leave both fields empty to hide this box.</p>\n        <div>\n          <label className={labelCls}>Title</label>\n          <input className={input} {...field(\"responseTitle\")} />\n        </div>\n        <div>\n          <label className={labelCls}>Text</label>\n          <input className={input} {...field(\"responseText\")} />\n        </div>\n      </div>\n\n      {/* Social */}\n      <div className={card}>\n        <div className=\"flex items-center justify-between\">\n          <h3 className=\"text-base font-bold font-display text-green\">Social Media</h3>\n          <button\n            type=\"button\"\n            onClick={() => set(\"socials\", [...info.socials, { id: newId(), platform: \"instagram\", label: \"\", url: \"\" }])}\n            className=\"px-4 py-2 text-xs font-semibold text-white rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark\"\n          >\n            + Add Link\n          </button>\n        </div>\n        <div>\n          <label className={labelCls}>Box title</label>\n          <input className={input} {...field(\"socialTitle\")} />\n        </div>\n        {info.socials.length === 0 && <p className=\"text-sm text-ink-muted font-body\">No social links - the box is hidden on the site.</p>}\n        {info.socials.map((s, i) => (\n          <div key={s.id} className={`p-4 space-y-3 border rounded-lg ${s.hidden ? \"bg-gray-50 border-border\" : \"bg-cream border-border\"}`}>\n            <div className=\"grid grid-cols-1 gap-3 sm:grid-cols-[170px_1fr]\">\n              <select className={input} value={s.platform} onChange={(e) => updateSocial(s.id, { platform: e.target.value as SocialPlatform })}>\n                {PLATFORMS.map((p) => (\n                  <option key={p.value} value={p.value}>{p.label}</option>\n                ))}\n              </select>\n              <input className={input} value={s.label} onChange={(e) => updateSocial(s.id, { label: e.target.value })} placeholder=\"Button text (optional)\" />\n            </div>\n            <input className={input} value={s.url} onChange={(e) => updateSocial(s.id, { url: e.target.value })} placeholder=\"https://...\" />\n            <RowControls\n              index={i}\n              total={info.socials.length}\n              hidden={s.hidden}\n              onMove={(d) => set(\"socials\", moveIn(info.socials, i, d))}\n              onToggle={() => updateSocial(s.id, { hidden: !s.hidden })}\n              onRemove={() => set(\"socials\", info.socials.filter((x) => x.id !== s.id))}\n            />\n          </div>\n        ))}\n      </div>\n\n      {/* Form */}\n      <div className={card}>\n        <h3 className=\"text-base font-bold font-display text-green\">Message Form</h3>\n        <div className=\"grid grid-cols-1 gap-4 sm:grid-cols-2\">\n          <div>\n            <label className={labelCls}>Form heading</label>\n            <input className={input} {...field(\"formHeading\")} />\n          </div>\n          <div>\n            <label className={labelCls}>Email shown under the form</label>\n            <input className={input} {...field(\"formEmail\")} />\n          </div>\n        </div>\n        <div>\n          <label className={labelCls}>Text under the heading</label>\n          <input className={input} {...field(\"formSubtext\")} />\n        </div>\n        <div className=\"grid grid-cols-1 gap-4 sm:grid-cols-2\">\n          <div>\n            <label className={labelCls}>After sending - heading</label>\n            <input className={input} {...field(\"successHeading\")} />\n          </div>\n          <div>\n            <label className={labelCls}>After sending - text</label>\n            <input className={input} {...field(\"successText\")} />\n          </div>\n        </div>\n      </div>\n\n      {message && (\n        <div className={`px-4 py-3 text-sm border rounded-lg font-body ${message.ok ? \"bg-green/10 border-green/20 text-green\" : \"bg-red-50 border-red-200 text-red-600\"}`}>\n          {message.text}\n        </div>\n      )}\n      <button\n        type=\"button\"\n        onClick={save}\n        disabled={saving}\n        className=\"w-full py-3 text-sm font-semibold text-white transition-colors rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark disabled:opacity-50\"\n      >\n        {saving ? \"Saving…\" : \"Save Contact Details\"}\n      </button>\n    </div>\n  );\n}\n",
"app/(public)/our-sponsors/page.tsx": "import type { Metadata } from \"next\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { resolveImage } from \"@/app/lib/images\";\nimport { getPageContent } from \"@/app/lib/pageContent\";\nimport Topbar from \"@/app/components/layout/Topbar\";\nimport Navbar from \"@/app/components/layout/Navbar\";\nimport Footer from \"@/app/components/layout/Footer\";\nimport PageHero from \"@/app/components/shared/PageHero\";\nimport Link from \"next/link\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport const metadata: Metadata = {\n  title: \"Our Sponsors | Pride of Pakistan\",\n  description: \"The organisations and businesses supporting Pride of Pakistan.\",\n};\n\nexport default async function OurSponsorsPage() {\n  const [hero, sponsors] = await Promise.all([\n    getPageContent(\"page_sponsors\"),\n    prisma.sponsor\n      .findMany({ where: { status: 1 }, orderBy: [{ sortOrder: \"asc\" }, { id: \"asc\" }] })\n      .catch(() => []),\n  ]);\n\n  return (\n    <>\n      <Topbar />\n      <Navbar />\n      <main className=\"min-h-screen bg-cream\">\n        <PageHero eyebrow={hero.eyebrow} title={hero.heading} subtitle={hero.subtext} />\n\n        <section className=\"py-14 sm:py-16\">\n          <div className=\"max-w-[1280px] mx-auto px-4 sm:px-8 lg:px-12\">\n            {sponsors.length === 0 ? (\n              <div className=\"py-20 text-center bg-white border border-border rounded-2xl\">\n                <p className=\"text-sm text-ink-muted font-body\">Our sponsors will be listed here soon.</p>\n              </div>\n            ) : (\n              <div className=\"grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n                {sponsors.map((s) => {\n                  const logo = resolveImage(s.smallimage);\n                  return (\n                    <div key={s.id} className=\"flex flex-col overflow-hidden bg-white border border-border rounded-2xl\">\n                      <div className=\"flex items-center justify-center h-40 p-6 border-b border-border bg-cream/40\">\n                        {logo ? (\n                          // eslint-disable-next-line @next/next/no-img-element\n                          <img src={logo} alt={s.title} className=\"object-contain w-full h-full\" />\n                        ) : (\n                          <span className=\"text-4xl font-bold font-display text-green\">{s.title.charAt(0)}</span>\n                        )}\n                      </div>\n                      <div className=\"flex flex-col flex-1 p-5\">\n                        <h2 className=\"mb-2 text-lg font-bold leading-snug font-display text-green\">{s.title}</h2>\n                        {s.shortdesc && (\n                          <p className=\"flex-1 text-sm leading-relaxed text-left text-ink-mid font-body\">{s.shortdesc}</p>\n                        )}\n                        {s.website && (\n                          <a\n                            href={s.website}\n                            target=\"_blank\"\n                            rel=\"noopener noreferrer sponsored\"\n                            className=\"inline-flex items-center gap-1.5 mt-4 text-sm font-semibold no-underline text-gold font-body hover:underline\"\n                          >\n                            Visit website ↗\n                          </a>\n                        )}\n                      </div>\n                    </div>\n                  );\n                })}\n              </div>\n            )}\n\n            <div className=\"p-6 mt-12 text-center border sm:p-8 bg-green/5 border-green/20 rounded-2xl\">\n              <h2 className=\"mb-2 text-xl font-bold font-display text-green\">Become a Sponsor</h2>\n              <p className=\"mb-5 text-sm text-center text-ink-mid font-body\">\n                Help us share the best of Pakistan with the world.\n              </p>\n              <Link\n                href=\"/contact\"\n                className=\"inline-flex items-center px-6 py-3 text-sm font-semibold text-white no-underline transition-colors rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark\"\n              >\n                Get in Touch\n              </Link>\n            </div>\n          </div>\n        </section>\n      </main>\n      <Footer />\n    </>\n  );\n}\n",
"app/(public)/terms-of-use/page.tsx": "import type { Metadata } from \"next\";\nimport LegalPage from \"@/app/components/shared/LegalPage\";\nimport { getLegalContent } from \"@/app/lib/legalContent\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport async function generateMetadata(): Promise<Metadata> {\n  const { title } = await getLegalContent(\"terms\");\n  return { title: `${title} | Pride of Pakistan` };\n}\n\nexport default function TermsOfUsePage() {\n  return <LegalPage slug=\"terms\" />;\n}\n",
"app/(public)/pride-team/page.tsx": "import type { Metadata } from \"next\";\nimport { prisma } from \"@/app/lib/prisma\";\nimport { resolveImage } from \"@/app/lib/images\";\nimport { getPageContent } from \"@/app/lib/pageContent\";\nimport Topbar from \"@/app/components/layout/Topbar\";\nimport Navbar from \"@/app/components/layout/Navbar\";\nimport Footer from \"@/app/components/layout/Footer\";\nimport PageHero from \"@/app/components/shared/PageHero\";\nimport PrideTeamClient from \"./PrideTeamClient\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport const metadata: Metadata = {\n  title: \"Pride Team | Pride of Pakistan\",\n  description: \"Meet the people behind Pride of Pakistan.\",\n};\n\nexport default async function PrideTeamPage() {\n  const [hero, members] = await Promise.all([\n    getPageContent(\"page_team\"),\n    prisma.prideTeam\n      .findMany({\n        where: { status: 1 },\n        orderBy: { fullname: \"asc\" },\n        // phone & email are deliberately NOT selected - they stay private\n        select: { id: true, fullname: true, designation: true, city: true, country: true, image: true, description: true },\n      })\n      .catch(() => []),\n  ]);\n\n  return (\n    <>\n      <Topbar />\n      <Navbar />\n      <main className=\"min-h-screen bg-cream\">\n        <PageHero eyebrow={hero.eyebrow} title={hero.heading} subtitle={hero.subtext} />\n        <PrideTeamClient members={members.map((m) => ({ ...m, image: resolveImage(m.image) }))} />\n      </main>\n      <Footer />\n    </>\n  );\n}\n",
"app/(public)/pride-team/PrideTeamClient.tsx": "\"use client\";\nimport { useMemo, useState } from \"react\";\n\ninterface Member {\n  id: number;\n  fullname: string;\n  designation: string;\n  city: string;\n  country: string;\n  image: string | null;\n  description: string;\n}\n\nconst PER_PAGE = 12;\nconst ALPHABET = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\".split(\"\");\n\nfunction MemberCard({ m }: { m: Member }) {\n  const [open, setOpen] = useState(false);\n  const long = m.description.length > 160;\n  const place = [m.city, m.country].filter(Boolean).join(\", \");\n\n  return (\n    <div className=\"flex flex-col overflow-hidden bg-white border border-border rounded-2xl\">\n      <div className=\"relative w-full overflow-hidden aspect-square bg-green\">\n        {m.image ? (\n          // eslint-disable-next-line @next/next/no-img-element\n          <img src={m.image} alt={m.fullname} className=\"object-cover object-top w-full h-full\" loading=\"lazy\" />\n        ) : (\n          <div className=\"flex items-center justify-center w-full h-full\">\n            <span className=\"text-6xl font-bold text-white/90 font-display\">{m.fullname.charAt(0)}</span>\n          </div>\n        )}\n      </div>\n      <div className=\"flex flex-col flex-1 p-5\">\n        <h3 className=\"text-lg font-bold leading-snug font-display text-green\">{m.fullname}</h3>\n        {m.designation && <p className=\"mt-0.5 text-sm font-semibold text-gold font-body\">{m.designation}</p>}\n        {place && <p className=\"mt-1 text-xs text-ink-muted font-body\">{place}</p>}\n        {m.description && (\n          <>\n            <p className={`mt-3 text-sm leading-relaxed text-left text-ink-mid font-body ${open ? \"\" : \"line-clamp-3\"}`}>\n              {m.description}\n            </p>\n            {long && (\n              <button\n                onClick={() => setOpen(!open)}\n                className=\"self-start mt-2 text-xs font-semibold text-gold font-body hover:underline\"\n              >\n                {open ? \"Show less\" : \"Read more\"}\n              </button>\n            )}\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n\nexport default function PrideTeamClient({ members }: { members: Member[] }) {\n  const [search, setSearch] = useState(\"\");\n  const [letter, setLetter] = useState<string | null>(null);\n  const [page, setPage] = useState(1);\n\n  const available = useMemo(\n    () => new Set(members.map((m) => m.fullname.charAt(0).toUpperCase())),\n    [members],\n  );\n\n  const filtered = useMemo(() => {\n    const q = search.trim().toLowerCase();\n    return members.filter((m) => {\n      if (letter && m.fullname.charAt(0).toUpperCase() !== letter) return false;\n      if (!q) return true;\n      return [m.fullname, m.designation, m.city, m.country].some((v) => v.toLowerCase().includes(q));\n    });\n  }, [members, search, letter]);\n\n  const pages = Math.max(1, Math.ceil(filtered.length / PER_PAGE));\n  const current = Math.min(page, pages);\n  const visible = filtered.slice((current - 1) * PER_PAGE, current * PER_PAGE);\n\n  function goTo(p: number) {\n    setPage(p);\n    document.getElementById(\"team-grid\")?.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n  }\n\n  if (members.length === 0) {\n    return (\n      <section className=\"py-20\">\n        <div className=\"max-w-[700px] mx-auto px-4 text-center\">\n          <p className=\"text-sm text-ink-muted font-body\">Our team members will be introduced here soon.</p>\n        </div>\n      </section>\n    );\n  }\n\n  return (\n    <section className=\"py-12 sm:py-16\">\n      <div className=\"max-w-[1280px] mx-auto px-4 sm:px-8 lg:px-12\">\n        <div className=\"p-4 mb-6 space-y-4 bg-white border sm:p-5 border-border rounded-2xl\">\n          <div className=\"flex flex-col gap-3 sm:flex-row sm:items-center\">\n            <input\n              type=\"search\"\n              value={search}\n              onChange={(e) => {\n                setSearch(e.target.value);\n                setPage(1);\n              }}\n              placeholder=\"Search by name, role, city or country…\"\n              className=\"flex-1 px-4 py-2.5 text-sm border rounded-md border-border font-body focus:outline-none focus:border-gold\"\n            />\n            <p className=\"text-xs text-ink-muted font-body sm:w-32 sm:text-right\">\n              {filtered.length} member{filtered.length === 1 ? \"\" : \"s\"}\n            </p>\n          </div>\n          <div className=\"flex flex-wrap gap-1\">\n            <button\n              onClick={() => {\n                setLetter(null);\n                setPage(1);\n              }}\n              className={`px-2.5 h-8 rounded text-xs font-semibold font-body transition-colors ${\n                letter === null ? \"bg-green text-white\" : \"text-ink-mid hover:bg-gold-pale\"\n              }`}\n            >\n              All\n            </button>\n            {ALPHABET.map((l) => {\n              const on = available.has(l);\n              return (\n                <button\n                  key={l}\n                  disabled={!on}\n                  onClick={() => {\n                    setLetter(l === letter ? null : l);\n                    setPage(1);\n                  }}\n                  className={`w-8 h-8 rounded text-xs font-semibold font-body transition-colors ${\n                    letter === l\n                      ? \"bg-green text-white\"\n                      : on\n                        ? \"text-ink-mid hover:bg-gold-pale hover:text-gold\"\n                        : \"text-ink-muted/30 cursor-not-allowed\"\n                  }`}\n                >\n                  {l}\n                </button>\n              );\n            })}\n          </div>\n        </div>\n\n        <div id=\"team-grid\" className=\"scroll-mt-6\">\n          {visible.length === 0 ? (\n            <div className=\"py-16 text-center bg-white border border-border rounded-2xl\">\n              <p className=\"text-sm text-ink-muted font-body\">No team members match your search.</p>\n            </div>\n          ) : (\n            <div className=\"grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4\">\n              {visible.map((m) => (\n                <MemberCard key={m.id} m={m} />\n              ))}\n            </div>\n          )}\n        </div>\n\n        {pages > 1 && (\n          <div className=\"flex flex-wrap items-center justify-center gap-2 mt-10\">\n            <button\n              onClick={() => goTo(current - 1)}\n              disabled={current === 1}\n              className=\"px-4 py-2 text-sm bg-white border rounded-md border-border text-ink-mid font-body hover:border-gold hover:text-gold disabled:opacity-40\"\n            >\n              ← Previous\n            </button>\n            {Array.from({ length: pages }, (_, i) => i + 1).map((p) => (\n              <button\n                key={p}\n                onClick={() => goTo(p)}\n                className={`w-9 h-9 rounded-md text-sm font-semibold font-body border ${\n                  p === current ? \"bg-gold text-white border-gold\" : \"bg-white border-border text-ink-mid hover:border-gold\"\n                }`}\n              >\n                {p}\n              </button>\n            ))}\n            <button\n              onClick={() => goTo(current + 1)}\n              disabled={current === pages}\n              className=\"px-4 py-2 text-sm bg-white border rounded-md border-border text-ink-mid font-body hover:border-gold hover:text-gold disabled:opacity-40\"\n            >\n              Next →\n            </button>\n          </div>\n        )}\n      </div>\n    </section>\n  );\n}\n",
"app/(public)/pride-tv/PrideTVPageClient.tsx": "\"use client\";\nimport { useState } from \"react\";\n\ninterface Video {\n  video_id: number;\n  title: string;\n  thumb_url: string;\n  featured: string;\n  views: number;\n  video_embed_code: string;\n  category: number;\n}\n\nfunction getEmbedSrc(embedCode: string): string {\n  if (!embedCode) return \"\";\n  const code = embedCode.trim();\n  if (code.includes(\"youtube.com/embed/\")) return code;\n  const watchMatch = code.match(/youtube\\.com\\/watch\\?v=([^&\\s]+)/);\n  if (watchMatch?.[1])\n    return `https://www.youtube.com/embed/${watchMatch[1]}?rel=0`;\n  const shortMatch = code.match(/youtu\\.be\\/([^?&\\s]+)/);\n  if (shortMatch?.[1])\n    return `https://www.youtube.com/embed/${shortMatch[1]}?rel=0`;\n  const srcMatch = code.match(/src=[\"']([^\"']+)[\"']/);\n  if (srcMatch?.[1]) return srcMatch[1];\n  if (/^[a-zA-Z0-9_-]{11}$/.test(code))\n    return `https://www.youtube.com/embed/${code}?rel=0`;\n  return code;\n}\n\nfunction getThumbnail(embedCode: string, existingThumb: string): string {\n  if (existingThumb) return existingThumb;\n  const code = embedCode.trim();\n  if (/^[a-zA-Z0-9_-]{11}$/.test(code))\n    return `https://img.youtube.com/vi/${code}/hqdefault.jpg`;\n  const patterns = [\n    /youtube\\.com\\/embed\\/([^\"?&/\\s]+)/,\n    /youtu\\.be\\/([^\"?&/\\s]+)/,\n    /youtube\\.com\\/watch\\?v=([^\"?&/\\s]+)/,\n  ];\n  for (const p of patterns) {\n    const m = code.match(p);\n    if (m?.[1]) return `https://img.youtube.com/vi/${m[1]}/hqdefault.jpg`;\n  }\n  return \"\";\n}\n\nexport default function PrideTVPageClient({\n  videos: allVideos,\n  categories = [],\n  initialCategory = null,\n}: {\n  videos: Video[];\n  categories?: { id: number; name: string }[];\n  initialCategory?: number | null;\n}) {\n  const [category, setCategory] = useState<number | null>(initialCategory);\n  const videos =\n    category === null\n      ? allVideos\n      : allVideos.filter((v) => v.category === category);\n\n  const [activeId, setActiveId] = useState<number | null>(\n    videos.find((v) => v.featured === \"feature\")?.video_id ??\n      videos[0]?.video_id ??\n      null,\n  );\n\n  const activeVideo = videos.find((v) => v.video_id === activeId) ?? videos[0];\n\n  function chooseCategory(id: number | null) {\n    setCategory(id);\n    const list =\n      id === null ? allVideos : allVideos.filter((v) => v.category === id);\n    setActiveId(\n      list.find((v) => v.featured === \"feature\")?.video_id ??\n        list[0]?.video_id ??\n        null,\n    );\n    const url = new URL(window.location.href);\n    if (id === null) url.searchParams.delete(\"category\");\n    else url.searchParams.set(\"category\", String(id));\n    window.history.replaceState(null, \"\", url.toString());\n  }\n\n  if (allVideos.length === 0) {\n    return (\n      <div className=\"flex items-center justify-center min-h-screen px-4 text-center bg-green\">\n        <div>\n          <p className=\"text-[11px] font-bold tracking-[.16em] uppercase text-gold-light mb-3 font-body\">\n            Pride TV\n          </p>\n          <h1 className=\"mb-3 text-3xl font-bold text-white font-display\">\n            Coming Soon\n          </h1>\n          <p className=\"text-sm text-white/60 font-body\">\n            Video content is being added. Check back soon.\n          </p>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"min-h-screen bg-green\">\n      {/* Hero - active player */}\n      <div className=\"max-w-[1280px] mx-auto px-4 sm:px-8 lg:px-12 pt-8 pb-6\">\n        <p className=\"text-[11px] font-bold tracking-[.16em] uppercase text-gold-light mb-2 font-body\">\n          Pride TV\n        </p>\n        <h1 className=\"mb-6 text-2xl font-bold text-white font-display sm:text-3xl\">\n          Watch Pakistan\n        </h1>\n\n        {categories.length > 0 && (\n          <div className=\"flex gap-2 pb-1 mb-6 -mx-1 overflow-x-auto\">\n            {[{ id: null as number | null, name: \"All Videos\" }, ...categories].map(\n              (c) => (\n                <button\n                  key={c.id ?? \"all\"}\n                  onClick={() => chooseCategory(c.id)}\n                  className={`flex-shrink-0 mx-1 px-4 py-1.5 rounded-full text-xs font-semibold font-body transition-colors border ${\n                    category === c.id\n                      ? \"bg-gold text-white border-gold\"\n                      : \"bg-white/[.06] text-white/70 border-white/15 hover:bg-white/15 hover:text-white\"\n                  }`}\n                >\n                  {c.name}\n                </button>\n              ),\n            )}\n          </div>\n        )}\n\n        <div className=\"grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-6 items-start\">\n          {/* Main player */}\n          <div>\n            <div className=\"relative w-full overflow-hidden bg-black shadow-2xl aspect-video rounded-xl\">\n              {activeVideo && (\n                <iframe\n                  key={activeId}\n                  src={getEmbedSrc(activeVideo.video_embed_code)}\n                  title={activeVideo.title}\n                  className=\"absolute inset-0 w-full h-full\"\n                  allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\n                  allowFullScreen\n                />\n              )}\n            </div>\n            {activeVideo && (\n              <div className=\"mt-4\">\n                <h2 className=\"text-lg font-bold leading-snug text-white sm:text-xl font-display\">\n                  {activeVideo.title}\n                </h2>\n                {activeVideo.views > 0 && (\n                  <p className=\"mt-1 text-xs text-white/40 font-body\">\n                    {activeVideo.views.toLocaleString()} views\n                  </p>\n                )}\n              </div>\n            )}\n          </div>\n\n          {/* Playlist sidebar */}\n          <div className=\"bg-white/[.06] rounded-xl overflow-hidden\">\n            <div className=\"px-4 py-3 border-b border-white/10\">\n              <p className=\"text-xs font-bold tracking-wide uppercase text-white/60 font-body\">\n                Up Next - {videos.length} videos\n              </p>\n            </div>\n            <div className=\"overflow-y-auto max-h-[480px] divide-y divide-white/[.06]\">\n              {videos.map((v) => (\n                <button\n                  key={v.video_id}\n                  onClick={() => setActiveId(v.video_id)}\n                  className={`w-full flex items-start gap-3 p-3 text-left transition-all ${\n                    activeId === v.video_id\n                      ? \"bg-white/15\"\n                      : \"hover:bg-white/[.08]\"\n                  }`}\n                >\n                  {/* Thumbnail */}\n                  <div className=\"relative flex-shrink-0 w-24 overflow-hidden rounded-lg h-14 bg-white/10\">\n                    {/* eslint-disable-next-line @next/next/no-img-element */}\n                    <img\n                      src={getThumbnail(v.video_embed_code, v.thumb_url)}\n                      alt={v.title}\n                      className=\"object-fit w-full h-full\"\n                    />\n                    {activeId === v.video_id && (\n                      <div className=\"absolute inset-0 flex items-center justify-center bg-green/60\">\n                        <div className=\"flex items-center justify-center w-6 h-6 rounded-full bg-gold\">\n                          <div className=\"w-0 h-0 border-t-[5px] border-b-[5px] border-l-[8px] border-t-transparent border-b-transparent border-l-white ml-0.5\" />\n                        </div>\n                      </div>\n                    )}\n                  </div>\n\n                  {/* Info */}\n                  <div className=\"flex-1 min-w-0\">\n                    <p\n                      className={`text-xs font-semibold font-body leading-snug line-clamp-2 ${\n                        activeId === v.video_id ? \"text-white\" : \"text-white/65\"\n                      }`}\n                    >\n                      {v.title}\n                    </p>\n                    <div className=\"flex items-center gap-2 mt-1\">\n                      {v.featured === \"feature\" && (\n                        <span className=\"text-[9px] font-bold text-gold font-body uppercase tracking-wide\">\n                          Featured\n                        </span>\n                      )}\n                      {v.views > 0 && (\n                        <span className=\"text-[10px] text-white/30 font-body\">\n                          {v.views.toLocaleString()} views\n                        </span>\n                      )}\n                    </div>\n                  </div>\n                </button>\n              ))}\n            </div>\n          </div>\n        </div>\n      </div>\n\n      {/* All videos grid below */}\n      <div className=\"max-w-[1280px] mx-auto px-4 sm:px-8 lg:px-12 pb-16\">\n        <div className=\"pt-10 mt-4 border-t border-white/10\">\n          <h2 className=\"mb-6 text-xl font-bold text-white font-display\">\n            {category === null\n              ? \"All Videos\"\n              : (categories.find((c) => c.id === category)?.name ?? \"Videos\")}\n          </h2>\n          <div className=\"grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5\">\n            {videos.map((v) => (\n              <button\n                key={v.video_id}\n                onClick={() => {\n                  setActiveId(v.video_id);\n                  window.scrollTo({ top: 0, behavior: \"smooth\" });\n                }}\n                className=\"text-left group\"\n              >\n                <div className=\"relative w-full mb-2 overflow-hidden rounded-lg aspect-video bg-white/10\">\n                  {/* eslint-disable-next-line @next/next/no-img-element */}\n                  <img\n                    src={getThumbnail(v.video_embed_code, v.thumb_url)}\n                    alt={v.title}\n                    className=\"object-fit w-full h-full transition-transform duration-300 group-hover:scale-105\"\n                  />\n                  {/* Play button overlay */}\n                  <div className=\"absolute inset-0 flex items-center justify-center transition-colors bg-black/0 group-hover:bg-black/30\">\n                    <div className=\"flex items-center justify-center w-10 h-10 transition-opacity rounded-full opacity-0 bg-white/90 group-hover:opacity-100\">\n                      <div className=\"w-0 h-0 border-t-[6px] border-b-[6px] border-l-[10px] border-t-transparent border-b-transparent border-l-green ml-1\" />\n                    </div>\n                  </div>\n                  {activeId === v.video_id && (\n                    <div className=\"absolute top-2 left-2 bg-gold text-white text-[9px] font-bold px-2 py-0.5 rounded font-body uppercase\">\n                      Playing\n                    </div>\n                  )}\n                  {v.featured === \"feature\" && activeId !== v.video_id && (\n                    <div className=\"absolute top-2 left-2 bg-green text-white text-[9px] font-bold px-2 py-0.5 rounded font-body uppercase\">\n                      Featured\n                    </div>\n                  )}\n                </div>\n                <p className=\"text-xs font-semibold leading-snug transition-colors text-white/80 font-body line-clamp-2 group-hover:text-white\">\n                  {v.title}\n                </p>\n                {v.views > 0 && (\n                  <p className=\"text-[10px] text-white/35 font-body mt-0.5\">\n                    {v.views.toLocaleString()} views\n                  </p>\n                )}\n              </button>\n            ))}\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
"app/(public)/pride-tv/page.tsx": "import { prisma } from '@/app/lib/prisma'\nimport Topbar from '@/app/components/layout/Topbar'\nimport Navbar from '@/app/components/layout/Navbar'\nimport Footer from '@/app/components/layout/Footer'\nimport PrideTVPageClient from './PrideTVPageClient'\nimport { getPageContent } from '@/app/lib/pageContent'\nimport PageHero from '@/app/components/shared/PageHero'\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function PrideTVPage({\n  searchParams,\n}: {\n  searchParams: Promise<{ category?: string }>\n}) {\n  const { category } = await searchParams\n  let videos: {\n    video_id: number\n    title: string\n    thumb_url: string\n    featured: string\n    views: number\n    video_embed_code: string\n    category: number\n  }[] = []\n\n  try {\n    const rows = await prisma.video.findMany({\n      where: { status: 'active' },\n      orderBy: [{ featured: 'desc' }, { datetime: 'desc' }],\n    })\n    videos = rows.map((v) => ({\n      video_id: Number(v.video_id),\n      title: v.title,\n      thumb_url: v.thumb_url,\n      featured: v.featured,\n      views: Number(v.views),\n      video_embed_code: v.video_embed_code,\n      category: v.category,\n    }))\n  } catch {\n    videos = []\n  }\n  const [hero, categoryRows] = await Promise.all([\n    getPageContent('page_pridetv'),\n    prisma.videoCategory\n      .findMany({\n        where: { status: 1 },\n        orderBy: [{ sortOrder: 'asc' }, { name: 'asc' }],\n        select: { id: true, name: true },\n      })\n      .catch(() => []),\n  ])\n  // Only show categories that actually have videos\n  const usedIds = new Set(videos.map((v) => v.category))\n  const categories = categoryRows.filter((c) => usedIds.has(c.id))\n  const initialCategory = categories.some((c) => c.id === Number(category))\n    ? Number(category)\n    : null\n\n  return (\n    <>\n      <Topbar />\n      <Navbar />\n      <main>\n        <PageHero\n          eyebrow={hero.eyebrow}\n          title={hero.heading}\n          subtitle={hero.subtext}\n        />\n        <PrideTVPageClient\n          videos={videos}\n          categories={categories}\n          initialCategory={initialCategory}\n        />\n      </main>\n      <Footer />\n    </>\n  );\n}",
"app/(public)/privacy-policy/page.tsx": "import type { Metadata } from \"next\";\nimport LegalPage from \"@/app/components/shared/LegalPage\";\nimport { getLegalContent } from \"@/app/lib/legalContent\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport async function generateMetadata(): Promise<Metadata> {\n  const { title } = await getLegalContent(\"privacy\");\n  return { title: `${title} | Pride of Pakistan` };\n}\n\nexport default function PrivacyPolicyPage() {\n  return <LegalPage slug=\"privacy\" />;\n}\n",
"app/(public)/contact/page.tsx": "import { getPageContent } from \"@/app/lib/pageContent\";\nimport { getContactInfo } from \"@/app/lib/contactInfo\";\nimport ContactPageClient from \"./ContactPageClient\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function ContactPage() {\n  const [hero, info] = await Promise.all([\n    getPageContent(\"page_contact\"),\n    getContactInfo(),\n  ]);\n  return <ContactPageClient hero={hero} info={info} />;\n}\n",
"app/(public)/contact/ContactPageClient.tsx": "\"use client\";\nimport type { PageHeroContent } from \"@/app/lib/pageContent\";\nimport type { ContactInfo, ContactItem, SocialPlatform } from \"@/app/lib/contactInfo\";\nimport { useState } from \"react\";\nimport Topbar from \"@/app/components/layout/Topbar\";\nimport Navbar from \"@/app/components/layout/Navbar\";\nimport Footer from \"@/app/components/layout/Footer\";\nimport PageHero from \"@/app/components/shared/PageHero\";\n\nfunction contactHref(item: Pick<ContactItem, \"type\" | \"value\">): string | null {\n  const v = item.value.trim();\n  if (!v) return null;\n  if (item.type === \"email\") return `mailto:${v}`;\n  if (item.type === \"phone\") return `tel:${v.replace(/[^\\d+]/g, \"\")}`;\n  if (item.type === \"url\") return /^https?:\\/\\//i.test(v) ? v : `https://${v}`;\n  return null;\n}\n\nconst svg = {\n  width: 18,\n  height: 18,\n  viewBox: \"0 0 24 24\",\n  fill: \"none\",\n  stroke: \"currentColor\",\n  strokeWidth: 2,\n  strokeLinecap: \"round\" as const,\n  strokeLinejoin: \"round\" as const,\n};\n\nconst ITEM_ICONS: Record<ContactItem[\"type\"], React.ReactNode> = {\n  email: (\n    <svg {...svg}>\n      <rect width=\"20\" height=\"16\" x=\"2\" y=\"4\" rx=\"2\" />\n      <path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\" />\n    </svg>\n  ),\n  phone: (\n    <svg {...svg}>\n      <path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.18 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.1 9.9a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.9.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z\" />\n    </svg>\n  ),\n  url: (\n    <svg {...svg}>\n      <circle cx=\"12\" cy=\"12\" r=\"10\" />\n      <path d=\"M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\" />\n    </svg>\n  ),\n  text: (\n    <svg {...svg}>\n      <path d=\"M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z\" />\n      <circle cx=\"12\" cy=\"10\" r=\"3\" />\n    </svg>\n  ),\n};\n\nconst SOCIAL_STYLE: Record<SocialPlatform, { name: string; cls: string }> = {\n  facebook: { name: \"Facebook\", cls: \"text-blue-600 border-blue-200 bg-blue-50 hover:bg-blue-100\" },\n  instagram: { name: \"Instagram\", cls: \"text-pink-600 border-pink-200 bg-pink-50 hover:bg-pink-100\" },\n  youtube: { name: \"YouTube\", cls: \"text-red-600 border-red-200 bg-red-50 hover:bg-red-100\" },\n  linkedin: { name: \"LinkedIn\", cls: \"text-sky-700 border-sky-200 bg-sky-50 hover:bg-sky-100\" },\n  tiktok: { name: \"TikTok\", cls: \"text-ink-dark border-border bg-cream hover:bg-gold-pale\" },\n  whatsapp: { name: \"WhatsApp\", cls: \"text-green-700 border-green-200 bg-green-50 hover:bg-green-100\" },\n  other: { name: \"Website\", cls: \"text-ink-mid border-border bg-cream hover:bg-gold-pale\" },\n};\n\nconst FACEBOOK_PATH =\n  \"M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z\";\n\nexport default function ContactPageClient({\n  hero,\n  info,\n}: {\n  hero: PageHeroContent;\n  info: ContactInfo;\n}) {\n  const [submitted, setSubmitted] = useState(false);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  const items = info.items.filter((i) => !i.hidden && i.value);\n  const socials = info.socials.filter((s) => !s.hidden && s.url);\n  const email = info.formEmail;\n\n  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {\n    e.preventDefault();\n    setLoading(true);\n    setError(null);\n    const form = e.currentTarget;\n    const data = {\n      name: (form.elements.namedItem(\"name\") as HTMLInputElement).value,\n      email: (form.elements.namedItem(\"email\") as HTMLInputElement).value,\n      subject: (form.elements.namedItem(\"subject\") as HTMLInputElement).value,\n      message: (form.elements.namedItem(\"message\") as HTMLTextAreaElement).value,\n    };\n    try {\n      const res = await fetch(\"/api/contact\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(data),\n      });\n      if (!res.ok) throw new Error(\"Failed\");\n      setSubmitted(true);\n      form.reset();\n    } catch {\n      setError(\n        email\n          ? `Something went wrong. Please email us directly at ${email}`\n          : \"Something went wrong. Please try again later.\",\n      );\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  const fieldCls =\n    \"w-full border border-border rounded-md px-3.5 py-2.5 text-sm font-body focus:outline-none focus:border-gold transition-colors\";\n  const labelCls =\n    \"block text-xs font-semibold text-ink-muted uppercase tracking-wide mb-1.5 font-body\";\n\n  return (\n    <>\n      <Topbar />\n      <Navbar />\n      <main className=\"min-h-screen bg-cream\">\n        <PageHero eyebrow={hero.eyebrow} title={hero.heading} subtitle={hero.subtext} />\n\n        <section className=\"py-16 sm:py-20\">\n          <div className=\"max-w-[1100px] mx-auto px-4 sm:px-8 lg:px-12\">\n            <div className=\"grid grid-cols-1 lg:grid-cols-[1fr_480px] gap-12 lg:gap-16 items-start\">\n              {/* Left - contact info */}\n              <div className=\"space-y-8\">\n                {(info.introHeading || info.introText) && (\n                  <div>\n                    {info.introHeading && (\n                      <>\n                        <h2 className=\"mb-3 text-2xl font-bold font-display sm:text-3xl text-green\">\n                          {info.introHeading}\n                        </h2>\n                        <div className=\"w-10 h-[3px] bg-gold rounded mb-5\" />\n                      </>\n                    )}\n                    {info.introText && (\n                      <p className=\"leading-relaxed whitespace-pre-line text-ink-mid font-body\">\n                        {info.introText}\n                      </p>\n                    )}\n                  </div>\n                )}\n\n                <div className=\"space-y-4\">\n                  {items.length > 0 && (\n                    <div className=\"p-5 bg-white border border-border rounded-xl\">\n                      {info.infoTitle && (\n                        <h3 className=\"mb-4 text-sm font-bold tracking-wide uppercase font-display text-green\">\n                          {info.infoTitle}\n                        </h3>\n                      )}\n                      <div className=\"space-y-4\">\n                        {items.map((item) => {\n                          const href = contactHref(item);\n                          const body = (\n                            <>\n                              <div className=\"flex items-center justify-center flex-shrink-0 w-10 h-10 transition-colors rounded-lg bg-gold/10 text-gold group-hover:bg-gold group-hover:text-white\">\n                                {ITEM_ICONS[item.type]}\n                              </div>\n                              <div className=\"min-w-0\">\n                                {item.label && (\n                                  <p className=\"text-[11px] font-bold uppercase tracking-wide text-ink-muted font-body\">\n                                    {item.label}\n                                  </p>\n                                )}\n                                <p className=\"text-sm font-semibold break-words transition-colors text-ink-dark font-body group-hover:text-gold\">\n                                  {item.value}\n                                </p>\n                              </div>\n                            </>\n                          );\n                          return href ? (\n                            <a\n                              key={item.id}\n                              href={href}\n                              {...(item.type === \"url\" && { target: \"_blank\", rel: \"noopener noreferrer\" })}\n                              className=\"flex items-center gap-4 no-underline group\"\n                            >\n                              {body}\n                            </a>\n                          ) : (\n                            <div key={item.id} className=\"flex items-center gap-4\">\n                              {body}\n                            </div>\n                          );\n                        })}\n                      </div>\n                    </div>\n                  )}\n\n                  {(info.responseTitle || info.responseText) && (\n                    <div className=\"p-5 border bg-green/5 border-green/20 rounded-xl\">\n                      <div className=\"flex items-start gap-3\">\n                        <div className=\"w-8 h-8 rounded-full bg-green/10 flex items-center justify-center flex-shrink-0 mt-0.5\">\n                          <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" className=\"text-green\">\n                            <circle cx=\"12\" cy=\"12\" r=\"10\" />\n                            <polyline points=\"12 6 12 12 16 14\" />\n                          </svg>\n                        </div>\n                        <div>\n                          {info.responseTitle && (\n                            <p className=\"text-sm font-bold text-green font-body\">{info.responseTitle}</p>\n                          )}\n                          {info.responseText && (\n                            <p className=\"text-xs text-ink-muted font-body mt-0.5\">{info.responseText}</p>\n                          )}\n                        </div>\n                      </div>\n                    </div>\n                  )}\n\n                  {socials.length > 0 && (\n                    <div className=\"p-5 bg-white border border-border rounded-xl\">\n                      {info.socialTitle && (\n                        <h3 className=\"mb-4 text-sm font-bold tracking-wide uppercase font-display text-green\">\n                          {info.socialTitle}\n                        </h3>\n                      )}\n                      <div className=\"flex flex-wrap gap-3\">\n                        {socials.map((s) => {\n                          const style = SOCIAL_STYLE[s.platform] ?? SOCIAL_STYLE.other;\n                          return (\n                            <a\n                              key={s.id}\n                              href={s.url}\n                              target=\"_blank\"\n                              rel=\"noopener noreferrer\"\n                              className={`flex items-center gap-2 px-3 py-2 text-xs font-semibold no-underline transition-colors border rounded-lg font-body ${style.cls}`}\n                            >\n                              {s.platform === \"facebook\" ? (\n                                <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"currentColor\">\n                                  <path d={FACEBOOK_PATH} />\n                                </svg>\n                              ) : (\n                                <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n                                  <path d=\"M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71\" />\n                                  <path d=\"M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71\" />\n                                </svg>\n                              )}\n                              {s.label || style.name}\n                            </a>\n                          );\n                        })}\n                      </div>\n                    </div>\n                  )}\n                </div>\n              </div>\n\n              {/* Right - form */}\n              <div className=\"p-6 bg-white border border-border rounded-2xl sm:p-8 lg:sticky lg:top-8\">\n                <h2 className=\"mb-1 text-2xl font-bold font-display text-green\">\n                  {info.formHeading || \"Send a Message\"}\n                </h2>\n                {info.formSubtext && (\n                  <p className=\"mb-6 text-sm text-ink-muted font-body\">{info.formSubtext}</p>\n                )}\n\n                {submitted ? (\n                  <div className=\"py-12 text-center\">\n                    <div className=\"flex items-center justify-center mx-auto mb-4 rounded-full w-14 h-14 bg-green/10\">\n                      <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" className=\"text-green\">\n                        <polyline points=\"20 6 9 17 4 12\" />\n                      </svg>\n                    </div>\n                    <h3 className=\"mb-2 text-xl font-bold font-display text-green\">\n                      {info.successHeading || \"Message Sent!\"}\n                    </h3>\n                    {info.successText && (\n                      <p className=\"text-sm text-center text-ink-muted font-body\">{info.successText}</p>\n                    )}\n                    <button\n                      onClick={() => setSubmitted(false)}\n                      className=\"mt-6 text-sm font-semibold text-gold font-body hover:underline\"\n                    >\n                      Send another message\n                    </button>\n                  </div>\n                ) : (\n                  <form onSubmit={handleSubmit} className=\"space-y-4\">\n                    <div className=\"grid grid-cols-1 gap-4 sm:grid-cols-2\">\n                      <div>\n                        <label className={labelCls}>\n                          Name <span className=\"text-gold\">*</span>\n                        </label>\n                        <input name=\"name\" type=\"text\" required placeholder=\"Your full name\" className={fieldCls} />\n                      </div>\n                      <div>\n                        <label className={labelCls}>\n                          Email <span className=\"text-gold\">*</span>\n                        </label>\n                        <input name=\"email\" type=\"email\" required placeholder=\"you@example.com\" className={fieldCls} />\n                      </div>\n                    </div>\n                    <div>\n                      <label className={labelCls}>\n                        Subject <span className=\"text-gold\">*</span>\n                      </label>\n                      <input name=\"subject\" type=\"text\" required placeholder=\"e.g. Sponsorship enquiry\" className={fieldCls} />\n                    </div>\n                    <div>\n                      <label className={labelCls}>\n                        Message <span className=\"text-gold\">*</span>\n                      </label>\n                      <textarea name=\"message\" required rows={6} placeholder=\"Tell us how we can help…\" className={`${fieldCls} resize-none`} />\n                    </div>\n                    {error && <p className=\"text-sm text-red-500 font-body\">{error}</p>}\n                    <button\n                      type=\"submit\"\n                      disabled={loading}\n                      className=\"w-full py-3 text-sm font-semibold text-white transition-colors rounded-md bg-gold font-body hover:bg-gold-light hover:text-ink-dark disabled:opacity-50\"\n                    >\n                      {loading ? \"Sending…\" : \"Send Message\"}\n                    </button>\n                    {email && (\n                      <p className=\"text-xs text-center text-ink-muted font-body\">\n                        Or email us directly at{\" \"}\n                        <a href={`mailto:${email}`} className=\"text-gold hover:underline\">\n                          {email}\n                        </a>\n                      </p>\n                    )}\n                  </form>\n                )}\n              </div>\n            </div>\n          </div>\n        </section>\n      </main>\n      <Footer />\n    </>\n  );\n}\n",
"app/(public)/disclaimer/page.tsx": "import type { Metadata } from \"next\";\nimport LegalPage from \"@/app/components/shared/LegalPage\";\nimport { getLegalContent } from \"@/app/lib/legalContent\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport async function generateMetadata(): Promise<Metadata> {\n  const { title } = await getLegalContent(\"disclaimer\");\n  return { title: `${title} | Pride of Pakistan` };\n}\n\nexport default function DisclaimerPage() {\n  return <LegalPage slug=\"disclaimer\" />;\n}\n",
"scripts/apply-feature-edits.mjs": "// One-time script: adds the small pieces of the new features to files you\n// already have (schema, business pages, homepage, footer...).\n// Safe to run more than once - edits that are already there are skipped.\n//\n//   node scripts/apply-feature-edits.mjs\n//\nimport { readFileSync, writeFileSync, existsSync } from \"node:fs\";\n\nconst edits = [\n  // ── prisma/schema.prisma ─────────────────────────────────────────────\n  {\n    file: \"prisma/schema.prisma\",\n    name: \"Business.video_url column\",\n    done: /video_url\\s+String/,\n    find: /\\n(\\s*@@map\\(\"busniss\"\\))/,\n    replace: '\\n  video_url           String            @default(\"\") @db.VarChar(500)\\n$1',\n  },\n  {\n    file: \"prisma/schema.prisma\",\n    name: \"Sponsor.website + sortOrder columns\",\n    done: /model Sponsor \\{[^}]*website/,\n    find: /(model Sponsor \\{[^}]*?)(\\n\\s*@@map\\(\"sponsors\"\\))/,\n    replace:\n      '$1\\n  website    String @default(\"\") @db.VarChar(500)\\n  sortOrder  Int    @default(0)$2',\n  },\n  {\n    file: \"prisma/schema.prisma\",\n    name: \"VideoCategory model\",\n    done: /model VideoCategory/,\n    find: /\\s*$/,\n    replace:\n      '\\n\\nmodel VideoCategory {\\n  id        Int    @id @default(autoincrement())\\n  name      String @db.VarChar(100)\\n  sortOrder Int    @default(0)\\n  status    Int    @default(1)\\n\\n  @@map(\"video_categories\")\\n}\\n',\n  },\n\n  // ── app/lib/pageContent.ts ───────────────────────────────────────────\n  {\n    file: \"app/lib/pageContent.ts\",\n    name: \"Hero defaults for Sponsors & Pride Team pages\",\n    done: /page_sponsors/,\n    find: /(const FALLBACKS: Record<string, PageHeroContent> = \\{\\n)/,\n    replace:\n      '$1  page_sponsors: {\\n    eyebrow: \"Our Supporters\",\\n    heading: \"Our Sponsors\",\\n    subtext:\\n      \"The organisations and businesses that help Pride of Pakistan share the best of Pakistan with the world.\",\\n  },\\n  page_team: {\\n    eyebrow: \"The People Behind It\",\\n    heading: \"Pride Team\",\\n    subtext:\\n      \"A growing network of people who believe in a brighter future for Pakistan.\",\\n  },\\n',\n  },\n\n  // ── Admin business edit page ─────────────────────────────────────────\n  {\n    file: \"app/(admin)/admin/business/[id]/edit/page.tsx\",\n    name: \"Import BusinessVideoField\",\n    done: /BusinessVideoField from/,\n    find: /(import BusinessEditClient from \"\\.\\/BusinessEditClient\";?\\n)/,\n    replace: '$1import BusinessVideoField from \"./BusinessVideoField\";\\n',\n  },\n  {\n    file: \"app/(admin)/admin/business/[id]/edit/page.tsx\",\n    name: \"Show video field under the business form\",\n    done: /<BusinessVideoField/,\n    find: /(\\n)([ \\t]*)(<BusinessEditClient business=\\{serialized\\} categories=\\{cats\\} \\/>)/,\n    replace: '$1$2$3\\n$2<BusinessVideoField businessId={biz.id} initial={biz.video_url ?? \"\"} />',\n  },\n\n  // ── Public business page ─────────────────────────────────────────────\n  {\n    file: \"app/(public)/business/[id]/page.tsx\",\n    name: \"Import VideoEmbed\",\n    done: /VideoEmbed from/,\n    find: /(import CommentSection from \"@\\/app\\/components\\/shared\\/CommentSection\";?\\n)/,\n    replace: '$1import VideoEmbed from \"@/app/components/shared/VideoEmbed\";\\n',\n  },\n  {\n    file: \"app/(public)/business/[id]/page.tsx\",\n    name: \"Video card on the business page\",\n    done: /<VideoEmbed/,\n    find: /(\\n)([ \\t]*)(\\{\\/\\* Basic Information \\*\\/\\})/,\n    replace:\n      '$1$2{/* Video */}\\n$2{biz.video_url && (\\n$2  <div className=\"overflow-hidden bg-white border border-border rounded-xl\">\\n$2    <div className=\"px-5 py-3 border-b bg-green/10 border-border\">\\n$2      <h2 className=\"text-sm font-bold tracking-wide uppercase text-green font-display\">\\n$2        Video\\n$2      </h2>\\n$2    </div>\\n$2    <div className=\"p-4\">\\n$2      <VideoEmbed url={biz.video_url} title={`${biz.company_name} video`} />\\n$2    </div>\\n$2  </div>\\n$2)}\\n\\n$2$3',\n  },\n\n  // ── List your business (public form) ────────────────────────────────\n  {\n    file: \"app/(public)/list-business/ListBusinessClient.tsx\",\n    name: \"Video link field on the List Business form\",\n    done: /name=\"video_url\"/,\n    find: /(name=\"site_url\"[^>]*?\\/>\\s*<\\/div>\\n)/,\n    replace:\n      '$1\\n                {/* Video */}\\n                <div>\\n                  <label className=\"block text-sm font-semibold text-ink-dark mb-1.5 font-body\">\\n                    Business Video\\n                  </label>\\n                  <input\\n                    name=\"video_url\"\\n                    type=\"text\"\\n                    className=\"w-full border border-border rounded-md px-3.5 py-2.5 text-sm font-body focus:outline-none focus:border-gold transition-colors\"\\n                    placeholder=\"https://www.youtube.com/watch?v=...\"\\n                  />\\n                  <p className=\"text-xs text-ink-muted font-body mt-1.5\">\\n                    Optional. Paste a YouTube or Vimeo link and it will play on\\n                    your business page.\\n                  </p>\\n                </div>\\n',\n  },\n  {\n    file: \"app/api/list-business/route.ts\",\n    name: \"Import video parser\",\n    done: /parseVideoUrl/,\n    find: /(import \\{ v2 as cloudinary \\} from \"cloudinary\";?\\n)/,\n    replace: '$1import { parseVideoUrl } from \"@/app/lib/video\";\\n',\n  },\n  {\n    file: \"app/api/list-business/route.ts\",\n    name: \"Validate the submitted video link\",\n    done: /const videoRaw/,\n    find: /(\\n)([ \\t]*)(const imageFileRaw = formData\\.get\\(\"image\"\\);)/,\n    replace:\n      '$1$2const videoRaw = ((formData.get(\"video_url\") as string) || \"\").trim();\\n$2const video = videoRaw ? parseVideoUrl(videoRaw) : null;\\n$2if (videoRaw && !video) {\\n$2  return NextResponse.json(\\n$2    { error: \"The video link must be a YouTube or Vimeo link.\" },\\n$2    { status: 400 },\\n$2  );\\n$2}\\n\\n$2$3',\n  },\n  {\n    file: \"app/api/list-business/route.ts\",\n    name: \"Save the video link\",\n    done: /video_url: video/,\n    find: /(\\n)([ \\t]*)(lat: \"\",\\n)/,\n    replace: '$1$2$3$2video_url: video?.watchUrl ?? \"\",\\n',\n  },\n\n  // ── Homepage + footer ────────────────────────────────────────────────\n  {\n    file: \"app/page.tsx\",\n    name: \"Import SponsorsSection\",\n    done: /SponsorsSection from/,\n    find: /(import PrideTVSection[^\\n]*\\n)/,\n    replace: '$1import SponsorsSection from \"@/app/components/home/SponsorsSection\";\\n',\n  },\n  {\n    file: \"app/page.tsx\",\n    name: \"Sponsors strip on the homepage\",\n    done: /<SponsorsSection/,\n    find: /(\\n)([ \\t]*)(<PrideTVSection[^\\n]*\\/>)/,\n    replace: '$1$2$3\\n$2<SponsorsSection />',\n  },\n  {\n    file: \"app/components/layout/Footer.tsx\",\n    name: \"Pride Team link in the footer\",\n    done: /\\/pride-team/,\n    find: /(\\n)([ \\t]*)(\\{ label: \"Pride TV\", href: \"\\/pride-tv\" \\},)/,\n    replace: '$1$2$3\\n$2{ label: \"Pride Team\", href: \"/pride-team\" },',\n  },\n];\n\nlet failed = 0;\nconst cache = new Map();\n\nfor (const e of edits) {\n  if (!existsSync(e.file)) {\n    console.log(`✗ ${e.name}\\n    file not found: ${e.file}`);\n    failed++;\n    continue;\n  }\n  if (!cache.has(e.file)) {\n    const raw = readFileSync(e.file, \"utf8\");\n    cache.set(e.file, { crlf: raw.includes(\"\\r\\n\"), text: raw.replace(/\\r\\n/g, \"\\n\"), changed: false });\n  }\n  const f = cache.get(e.file);\n  if (e.done.test(f.text)) {\n    console.log(`• ${e.name} (already there)`);\n    continue;\n  }\n  if (!e.find.test(f.text)) {\n    console.log(`✗ ${e.name}\\n    couldn't find the spot in ${e.file} - add it by hand (see INSTALL.md)`);\n    failed++;\n    continue;\n  }\n  f.text = f.text.replace(e.find, e.replace);\n  f.changed = true;\n  console.log(`✓ ${e.name}`);\n}\n\nfor (const [file, f] of cache) {\n  if (f.changed) writeFileSync(file, f.crlf ? f.text.replace(/\\n/g, \"\\r\\n\") : f.text, \"utf8\");\n}\n\nconsole.log(failed ? `\\n${failed} edit(s) need doing by hand.` : \"\\nAll edits applied.\");\nprocess.exit(failed ? 1 : 0);\n"
};

let n = 0;
for (const [path, content] of Object.entries(FILES)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content, "utf8");
  console.log("wrote " + path);
  n++;
}
console.log(`\nDone - ${n} files written. Next: npm install sanitize-html @types/sanitize-html, then node scripts/apply-feature-edits.mjs`);
